INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('309bfcf2-c1b9-5f40-adbb-cd0a7bfeb5ae', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 17, 17, 'Jehoshaphat the son of Paruah, in Issachar;'),
  ('9a3997b5-8cee-5a88-a3c6-bdc62d3e98c9', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 18, 18, 'Shimei the son of Ela, in Benjamin;'),
  ('18080992-8a2f-5b3b-a321-ac79655c30b1', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 19, 19, 'Geber the son of Uri, in the land of Gilead, the country of Sihon king of the Amorites and of Og king of Bashan; and [he was] the only officer who was in the land.'),
  ('4f88c41c-e976-5ea9-a732-67e034c1e61f', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 20, 20, 'Judah and Israel were many as the sand which is by the sea in multitude, eating and drinking and making merry.'),
  ('041ae630-983e-5ab8-aee3-67ba771d7be2', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 21, 21, 'Solomon ruled over all the kingdoms from the River to the land of the Philistines, and to the border of Egypt: they brought tribute, and served Solomon all the days of his life.'),
  ('33f86950-48f5-532f-a0ab-929e2ba44324', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 22, 22, 'Solomon''s provision for one day was thirty measures of fine flour, and sixty measures of meal,'),
  ('ec599c89-0c9f-5af3-ae29-1cc3a34c4a2f', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 23, 23, 'ten head of fat cattle, and twenty head of cattle out of the pastures, and one hundred sheep, besides harts, and gazelles, and roebucks, and fattened fowl.'),
  ('3fa99197-6561-5852-a955-f7ed2da63b5a', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 24, 24, 'For he had dominion over all [the region] on this side the River, from Tiphsah even to Gaza, over all the kings on this side the River: and he had peace on all sides around him.'),
  ('c6ef3586-3927-56b9-ac3c-9fa2f8a64c1f', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 25, 25, 'Judah and Israel lived safely, every man under his vine and under his fig tree, from Dan even to Beersheba, all the days of Solomon.'),
  ('c9d31172-5830-53d8-a8a4-fbb157eba6cd', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 26, 26, 'Solomon had forty thousand stalls of horses for his chariots, and twelve thousand horsemen.'),
  ('9cd1765b-3edb-5206-aedc-516cff326974', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 27, 27, 'Those officers provided food for king Solomon, and for all who came to king Solomon''s table, every man in his month; they let nothing be lacking.'),
  ('fdd7ef68-69e7-53a9-a64f-9cb13a51290f', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 28, 28, 'Barley also and straw for the horses and swift steeds brought they to the place where [the officers] were, every man according to his duty.'),
  ('db590ea2-61c7-50c3-a605-55956afd8e15', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 29, 29, 'God gave Solomon wisdom and understanding exceeding much, and very great understanding, even as the sand that is on the seashore.'),
  ('ffbdbf46-84ba-59f6-aa2d-236dda3ced72', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 30, 30, 'Solomon''s wisdom excelled the wisdom of all the children of the east, and all the wisdom of Egypt.'),
  ('4924da68-596a-5f55-a42e-16a548ce8053', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 31, 31, 'For he was wiser than all men; than Ethan the Ezrahite, and Heman, and Calcol, and Darda, the sons of Mahol: and his fame was in all the nations all around.'),
  ('bd3d2e1a-fb3a-5cc3-a39d-20ef5ab24118', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 32, 32, 'He spoke three thousand proverbs; and his songs were one thousand five.'),
  ('327ac4d4-522d-5dd7-aa8d-24c42d967efd', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 33, 33, 'He spoke of trees, from the cedar that is in Lebanon even to the hyssop that springs out of the wall; he spoke also of animals, and of birds, and of creeping things, and of fish.'),
  ('210c182b-156b-5b81-a80a-683b6543785c', '2ab28e7e-eada-5e1d-ae79-ae2aee3d0ec8', NULL, 34, 34, 'There came of all peoples to hear the wisdom of Solomon, from all kings of the earth, who had heard of his wisdom.'),
  ('bbf58f46-ed93-543c-a3f5-668cd3aa175e', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 1, 1, 'Hiram king of Tyre sent his servants to Solomon; for he had heard that they had anointed him king in the place of his father: for Hiram was ever a lover of David.'),
  ('bc824803-33e2-539e-a8d3-a341cfe06164', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 2, 2, 'Solomon sent to Hiram, saying,'),
  ('8e69d5ed-4aeb-54a8-ac38-7a627c5ac568', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 3, 3, '"You know how that David my father could not build a house for the name of Yahweh his God for the wars which were about him on every side, until Yahweh put them under the soles of his feet.'),
  ('df07146f-98b7-5183-a5d9-c4c5fd6676c4', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 4, 4, 'But now Yahweh my God has given me rest on every side. There is neither adversary, nor evil occurrence.'),
  ('c53aab29-8ba4-5ade-ab96-960e730bff8a', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 5, 5, 'Behold, I purpose to build a house for the name of Yahweh my God, as Yahweh spoke to David my father, saying, ''Your son, whom I will set on your throne in your place, he shall build the house for my name.'''),
  ('fd144e63-6175-5aa2-a642-00c987aa687c', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 6, 6, 'Now therefore command that they cut me cedar trees out of Lebanon. My servants shall be with your servants; and I will give you wages for your servants according to all that you shall say. For you know that there is not among us any who knows how to cut timber like the Sidonians."'),
  ('519061e6-e5f3-545c-acb1-f444d8a473b8', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 7, 7, 'It happened, when Hiram heard the words of Solomon, that he rejoiced greatly, and said, "Blessed is Yahweh this day, who has given to David a wise son over this great people."'),
  ('c08d5f0c-5b19-5e42-a348-f423e994c06a', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 8, 8, 'Hiram sent to Solomon, saying, "I have heard the message which you have sent to me. I will do all your desire concerning timber of cedar, and concerning timber of fir.'),
  ('43dbce2c-2059-59f5-a4af-adb5909060d9', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 9, 9, 'My servants shall bring them down from Lebanon to the sea. I will make them into rafts to go by sea to the place that you shall appoint me, and will cause them to be broken up there, and you shall receive them. You shall accomplish my desire, in giving food for my household."'),
  ('6b26ec93-daa4-5476-a7d8-5258db6211fe', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 10, 10, 'So Hiram gave Solomon timber of cedar and timber of fir according to all his desire.'),
  ('9f46fb51-4bc3-5824-aba4-df842f939180', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 11, 11, 'Solomon gave Hiram twenty thousand measures of wheat for food to his household, and twenty measures of pure oil. Solomon gave this to Hiram year by year.'),
  ('e98118b5-39b1-5585-aad4-39626045bd8e', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 12, 12, 'Yahweh gave Solomon wisdom, as he promised him; and there was peace between Hiram and Solomon; and they two made a treaty together.'),
  ('2c032b01-8539-550d-a34a-24fb4a5b48b8', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 13, 13, 'King Solomon raised a levy out of all Israel; and the levy was thirty thousand men.'),
  ('84e2f9c1-820d-59b7-a22e-325448df65e3', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 14, 14, 'He sent them to Lebanon, ten thousand a month by courses; a month they were in Lebanon, and two months at home; and Adoniram was over the men subject to forced labor.'),
  ('c9e7f423-2419-52b7-adcc-57c32948049a', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 15, 15, 'Solomon had seventy thousand who bore burdens, and eighty thousand who were stone cutters in the mountains;'),
  ('bc856ce0-6bc9-5c0f-a0cf-8ac2d59d3b1d', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 16, 16, 'besides Solomon''s chief officers who were over the work, three thousand and three hundred, who bore rule over the people who labored in the work.'),
  ('4aab61aa-92ec-5e2e-adeb-2ab69b0f0206', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 17, 17, 'The king commanded, and they cut out great stones, costly stones, to lay the foundation of the house with worked stone.'),
  ('d041df01-dfce-5d60-ab89-142792a46a30', 'f7dd470a-39df-5993-ab6b-932fe5e89d03', NULL, 18, 18, 'Solomon''s builders and Hiram''s builders and the Gebalites did fashion them, and prepared the timber and the stones to build the house.'),
  ('fd70092e-abee-5d15-a0c6-813b52fc56d2', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 1, 1, 'It happened in the four hundred and eightieth year after the children of Israel were come out of the land of Egypt, in the fourth year of Solomon''s reign over Israel, in the month Ziv, which is the second month, that he began to build the house of Yahweh.'),
  ('bc1b4d54-352b-5014-af6e-bdca2eb4c53f', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 2, 2, 'The house which king Solomon built for Yahweh, its length was sixty cubits, and its breadth twenty [cubits], and its height thirty cubits.'),
  ('10ef90ab-6359-5769-a24a-61e4273ebe5b', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 3, 3, 'The porch before the temple of the house, twenty cubits was its length, according to the breadth of the house; [and] ten cubits was its breadth before the house.'),
  ('9cb716c6-33ba-5767-a36d-37a4917ae94b', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 4, 4, 'For the house he made windows of fixed lattice work.'),
  ('9d53bf1d-a6db-57d1-aac1-17d33d031859', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 5, 5, 'Against the wall of the house he built stories all around, against the walls of the house all around, both of the temple and of the oracle; and he made side rooms all around.'),
  ('5c0845aa-61fe-512b-a254-fcbbf8ec55cc', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 6, 6, 'The nethermost story was five cubits broad, and the middle was six cubits broad, and the third was seven cubits broad; for on the outside he made offsets [in the wall] of the house all around, that [the beams] should not have hold in the walls of the house.'),
  ('41f9f8b0-3ecb-569d-a4e9-a95250562454', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 7, 7, 'The house, when it was in building, was built of stone prepared at the quarry; and there was neither hammer nor axe nor any tool of iron heard in the house, while it was in building.'),
  ('64463858-d0c6-5fe2-a757-0101fa446427', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 8, 8, 'The door for the middle side rooms was in the right side of the house: and they went up by winding stairs into the middle [story], and out of the middle into the third.'),
  ('9ab0adbd-2e09-5661-a8f0-353220e52e15', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 9, 9, 'So he built the house, and finished it; and he covered the house with beams and planks of cedar.'),
  ('6e2ff163-fb03-5bac-af67-823c96bcc975', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 10, 10, 'He built the stories against all the house, each five cubits high: and they rested on the house with timber of cedar.'),
  ('2dcb7346-69d4-598a-a63d-efee58d98298', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 11, 11, 'The word of Yahweh came to Solomon, saying,'),
  ('5138f6bf-3afa-5c1b-a078-b8ce0dfcd511', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 12, 12, '"Concerning this house which you are building, if you will walk in my statutes, and execute my ordinances, and keep all my commandments to walk in them; then will I establish my word with you, which I spoke to David your father.'),
  ('9b0bfa81-ab16-5ffd-af9a-de37c040f952', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 13, 13, 'I will dwell among the children of Israel, and will not forsake my people Israel."'),
  ('fb153eeb-4889-5771-a427-eab14fd67786', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 14, 14, 'So Solomon built the house, and finished it.'),
  ('d8abc18c-b077-5067-a7f0-9feee5056b58', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 15, 15, 'He built the walls of the house within with boards of cedar: from the floor of the house to the walls of the ceiling, he covered them on the inside with wood; and he covered the floor of the house with boards of fir.'),
  ('8f6856de-8ec1-534f-a5ad-8082fefecefa', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 16, 16, 'He built twenty cubits on the hinder part of the house with boards of cedar from the floor to the walls [of the ceiling]: he built [them] for it within, for an oracle, even for the most holy place.'),
  ('57028615-90fd-5598-a6e2-20bc42ec913a', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 17, 17, 'The house, that is, the temple before [the oracle], was forty cubits [long].'),
  ('a69f8915-1f10-5d01-a6f2-166f2af7ffbc', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 18, 18, 'There was cedar on the house within, carved with buds and open flowers: all was cedar; there was no stone seen.'),
  ('2aeb548d-69c6-5655-a62c-d10f094835fc', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 19, 19, 'He prepared an oracle in the midst of the house within, to set there the ark of the covenant of Yahweh.'),
  ('f02265f0-8cdd-5aa0-a72f-1e0eac23e9c5', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 20, 20, 'Within the oracle was [a space of] twenty cubits in length, and twenty cubits in breadth, and twenty cubits in its height; and he overlaid it with pure gold: and he covered the altar with cedar.'),
  ('e3568dac-4dd1-5ea0-a7a5-d8c39d6afff2', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 21, 21, 'So Solomon overlaid the house within with pure gold: and he drew chains of gold across before the oracle; and he overlaid it with gold.'),
  ('fc353151-0260-581a-a7c7-a2cf9f61fb4e', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 22, 22, 'The whole house he overlaid with gold, until all the house was finished: also the whole altar that belonged to the oracle he overlaid with gold.'),
  ('1b83447b-f4e4-5160-acc5-3f83b6d7dbb2', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 23, 23, 'In the oracle he made two cherubim of olive wood, each ten cubits high.'),
  ('e3ebc1d4-9ca5-55bd-a8f4-afd17c184802', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 24, 24, 'Five cubits was the one wing of the cherub, and five cubits the other wing of the cherub: from the uttermost part of the one wing to the uttermost part of the other were ten cubits.'),
  ('ca7e2aee-602c-5931-a827-488d3fb984f3', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 25, 25, 'The other cherub was ten cubits: both the cherubim were of one measure and one form.'),
  ('def7ca0b-a7e3-5a73-a21e-174ed92c97e1', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 26, 26, 'The height of the one cherub was ten cubits, and so was it of the other cherub.'),
  ('f1889a28-4a2b-5b5f-a332-762c5445b64a', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 27, 27, 'He set the cherubim within the inner house; and the wings of the cherubim were stretched forth, so that the wing of the one touched the one wall, and the wing of the other cherub touched the other wall; and their wings touched one another in the midst of the house.'),
  ('588d76db-1a6b-5eb0-ac25-1836a0a8cdb2', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 28, 28, 'He overlaid the cherubim with gold.'),
  ('a641abe1-cdeb-5015-ace9-f0700ca1158d', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 29, 29, 'He carved all the walls of the house around with carved figures of cherubim and palm trees and open flowers, inside and outside.'),
  ('c1e80b03-492e-5f5f-a0a1-c0720fe391d7', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 30, 30, 'The floor of the house he overlaid with gold, inside and outside.'),
  ('0a55bc5c-3666-5f90-a237-5eb7c57eabe2', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 31, 31, 'For the entrance of the oracle he made doors of olive wood: the lintel [and] door posts were a fifth part [of the wall].'),
  ('92bd1f54-9199-5048-a0f9-eee7df039eeb', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 32, 32, 'So [he made] two doors of olive wood; and he carved on them carvings of cherubim and palm trees and open flowers, and overlaid them with gold; and he spread the gold on the cherubim, and on the palm trees.'),
  ('62d752e0-ebf5-527b-af65-dfec8bff6e96', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 33, 33, 'So also made he for the entrance of the temple door posts of olive wood, out of a fourth part [of the wall];'),
  ('f4d3e90f-0920-5d0a-ac63-1847f280dfe5', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 34, 34, 'and two doors of fir wood: the two leaves of the one door were folding, and the two leaves of the other door were folding.'),
  ('f1755d80-a4ce-5d41-af70-98aabe5c8c22', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 35, 35, 'He carved [thereon] cherubim and palm trees and open flowers; and he overlaid them with gold fitted on the engraved work.'),
  ('c1bb87b6-a5c9-574f-a912-5cc518afbd13', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 36, 36, 'He built the inner court with three courses of cut stone, and a course of cedar beams.'),
  ('6c3b1ef0-3fb3-58fb-ab15-a3c02937bb0d', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 37, 37, 'In the fourth year was the foundation of the house of Yahweh laid, in the month Ziv.'),
  ('ec68956c-6dc0-5580-ae2f-2777229101ba', '1c109af3-fad6-5425-a25d-6520a89ce404', NULL, 38, 38, 'In the eleventh year, in the month Bul, which is the eighth month, was the house finished throughout all its parts, and according to all its fashion. So was he seven years in building it.'),
  ('db1211a2-f383-586c-a755-7a2887df448d', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 1, 1, 'Solomon was building his own house thirteen years, and he finished all his house.'),
  ('15c28a87-44fe-5af5-a2f0-037ff4728b03', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 2, 2, 'For he built the house of the forest of Lebanon; its length was one hundred cubits, and its breadth fifty cubits, and its height thirty cubits, on four rows of cedar pillars, with cedar beams on the pillars.'),
  ('24c89f47-481e-54d7-a26c-722811b13776', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 3, 3, 'It was covered with cedar above over the forty-five beams, that were on the pillars; fifteen in a row.'),
  ('904d6021-e5a3-5a76-ab53-32d7f352f24e', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 4, 4, 'There were beams in three rows, and window was over against window in three ranks.'),
  ('e8135366-6202-5db8-a030-f8d5f6ea8faa', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 5, 5, 'All the doors and posts were made square with beams: and window was over against window in three ranks.'),
  ('e32e4ec9-1195-5452-a021-998a6c6a59ab', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 6, 6, 'He made the porch of pillars; its length was fifty cubits, and its breadth thirty cubits; and a porch before them; and pillars and a threshold before them.'),
  ('7e421c2c-733d-57ac-aa0b-7d4c2b1d829b', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 7, 7, 'He made the porch of the throne where he was to judge, even the porch of judgment: and it was covered with cedar from floor to floor.'),
  ('43c631c5-56a9-51a2-aebf-f417b4b85140', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 8, 8, 'His house where he was to dwell, the other court within the porch, was of the like work. He made also a house for Pharaoh''s daughter (whom Solomon had taken as wife), like this porch.'),
  ('802386c3-fce5-5cbf-a495-36024ffeb7c3', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 9, 9, 'All these were of costly stones, even of cut stone, according to measure, sawed with saws, inside and outside, even from the foundation to the coping, and so on the outside to the great court.'),
  ('1f995af7-f56c-5ec0-a48b-a92920a5fa2f', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 10, 10, 'The foundation was of costly stones, even great stones, stones of ten cubits, and stones of eight cubits.'),
  ('d6d4bbd5-22ec-5254-a49d-28789050e3cf', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 11, 11, 'Above were costly stones, even cut stone, according to measure, and cedar wood.'),
  ('03ae26e4-9797-5685-a3b9-eda4083d004c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 12, 12, 'The great court around had three courses of cut stone, and a course of cedar beams; like as the inner court of the house of Yahweh, and the porch of the house.'),
  ('4fde5fc8-8c52-5ce6-a193-d77ab12e3d14', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 13, 13, 'King Solomon sent and fetched Hiram out of Tyre.'),
  ('5734f072-db6e-5663-ab46-9e7e1f3507cd', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 14, 14, 'He was the son of a widow of the tribe of Naphtali, and his father was a man of Tyre, a worker in brass; and he was filled with wisdom and understanding and skill, to work all works in brass. He came to king Solomon, and performed all his work.'),
  ('d6aad493-5186-56ab-a9fa-797e19304b05', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 15, 15, 'For he fashioned the two pillars of brass, eighteen cubits high apiece: and a line of twelve cubits encircled either of them about.'),
  ('361c9e09-eb66-5c0c-a79b-14514c58756a', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 16, 16, 'He made two capitals of molten brass, to set on the tops of the pillars: the height of the one capital was five cubits, and the height of the other capital was five cubits.'),
  ('6619f5d4-5c70-5d1f-a4f8-7061bcffe277', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 17, 17, 'There were nets of checker work, and wreaths of chain work, for the capitals which were on the top of the pillars; seven for the one capital, and seven for the other capital.'),
  ('c6186d65-e8e1-5ccf-a309-3d3272c52d63', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 18, 18, 'So he made the pillars; and there were two rows around on the one network, to cover the capitals that were on the top of the pillars: and so did he for the other capital.'),
  ('891322c3-3485-5af1-ac30-70bd62ec21ed', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 19, 19, 'The capitals that were on the top of the pillars in the porch were of lily work, four cubits.'),
  ('d73da9ed-6c73-5dc0-a0b0-6a6956b5447c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 20, 20, 'There were capitals above also on the two pillars, close by the belly which was beside the network: and the pomegranates were two hundred, in rows around on the other capital.'),
  ('b4dec8a1-7a01-5a0c-a5ad-45a8eb7ca92c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 21, 21, 'He set up the pillars at the porch of the temple: and he set up the right pillar, and called its name Jachin; and he set up the left pillar, and called its name Boaz.'),
  ('bc048c17-0c15-5a3d-a602-824675e41899', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 22, 22, 'On the top of the pillars was lily work: so was the work of the pillars finished.'),
  ('d632cd8a-8c40-54b2-a902-f982cd13333c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 23, 23, 'He made the molten sea of ten cubits from brim to brim, round in compass, and its height was five cubits; and a line of thirty cubits encircled it.'),
  ('054b07d4-a5a0-5fc5-a910-73d9395ade49', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 24, 24, 'Under its brim around there were buds which encircled it, for ten cubits, encircling the sea: the buds were in two rows, cast when it was cast.'),
  ('8d0acc6a-06fa-5f52-a760-66e6f1fabdc7', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 25, 25, 'It stood on twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east; and the sea was set on them above, and all their hinder parts were inward.'),
  ('15065eb4-71b3-588d-a905-e9539415b916', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 26, 26, 'It was a handbreadth thick: and its brim was worked like the brim of a cup, like the flower of a lily: it held two thousand baths.'),
  ('def63f97-53db-570b-a0f0-9a1fd39f81cf', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 27, 27, 'He made the ten bases of brass; four cubits was the length of one base, and four cubits its breadth, and three cubits its height.'),
  ('4d804f21-ad1b-5726-ae9f-02034c73c93b', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 28, 28, 'The work of the bases was like this: they had panels; and there were panels between the ledges;'),
  ('d9abd750-7676-53c1-ace1-3cd6a47bbf87', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 29, 29, 'and on the panels that were between the ledges were lions, oxen, and cherubim; and on the ledges there was a pedestal above; and beneath the lions and oxen were wreaths of hanging work.'),
  ('b216ec33-4761-5783-abca-44b1396e99d8', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 30, 30, 'Every base had four bronze wheels, and axles of brass; and the four feet of it had supports: beneath the basin were the supports molten, with wreaths at the side of each.'),
  ('33e8375f-e54c-58b5-a706-3c84732b9351', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 31, 31, 'The mouth of it within the capital and above was a cubit: and its mouth was round after the work of a pedestal, a cubit and a half; and also on its mouth were engravings, and their panels were foursquare, not round.'),
  ('7d7e3445-819c-5c90-a168-f2ac1029a1a9', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 32, 32, 'The four wheels were underneath the panels; and the axles of the wheels were in the base: and the height of a wheel was a cubit and half a cubit.'),
  ('3a5bb2f6-2eaa-5529-aca8-5e7cc9640098', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 33, 33, 'The work of the wheels was like the work of a chariot wheel: their axles, and their rims, and their spokes, and their naves, were all molten.'),
  ('04a58992-40fe-5d81-ab1f-7058f9cc3541', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 34, 34, 'There were four supports at the four corners of each base: its supports were of the base itself.'),
  ('cde44f2d-e35a-5bf3-a396-df33d2c3404f', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 35, 35, 'In the top of the base was there a round compass half a cubit high; and on the top of the base its stays and its panels were of the same.'),
  ('a4c9446f-3457-5fb7-ad3a-3db4a057ea22', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 36, 36, 'On the plates of its stays, and on its panels, he engraved cherubim, lions, and palm trees, according to the space of each, with wreaths all around.'),
  ('29f820e2-9add-56dd-a7f0-bfad4c246b23', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 37, 37, 'In this way, he made the ten bases: all of them had one casting, one measure, and one form.'),
  ('05f1eeba-dc3a-582d-a654-f661e6dd5172', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 38, 38, 'He made ten basins of brass: one basin contained forty baths; and every basin was four cubits; and on every one of the ten bases one basin.'),
  ('2d6f726e-11d0-5bf8-a889-2724a2977000', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 39, 39, 'He set the bases, five on the right side of the house, and five on the left side of the house: and he set the sea on the right side of the house eastward, toward the south.'),
  ('8e7f854c-fbe6-5bf3-a136-012b9b359565', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 40, 40, 'Hiram made the basins, and the shovels, and the basins. So Hiram made an end of doing all the work that he worked for king Solomon in the house of Yahweh:'),
  ('8b6888e4-d06c-55c6-aae1-c5cdcacad75c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 41, 41, 'the two pillars, and the two bowls of the capitals that were on the top of the pillars; and the two networks to cover the two bowls of the capitals that were on the top of the pillars;'),
  ('8ba2eb50-2305-52bb-a81c-4a060898ef20', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 42, 42, 'and the four hundred pomegranates for the two networks; two rows of pomegranates for each network, to cover the two bowls of the capitals that were on the pillars;'),
  ('8a906112-347f-50ff-a657-4d69fe9df418', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 43, 43, 'and the ten bases, and the ten basins on the bases;'),
  ('acb1724e-1f7a-573d-a6ef-0542f82199ea', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 44, 44, 'and the one sea, and the twelve oxen under the sea;'),
  ('02c7f2c5-ea54-5e4b-a465-e335583f03ab', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 45, 45, 'and the pots, and the shovels, and the basins: even all these vessels, which Hiram made for king Solomon, in the house of Yahweh, were of burnished brass.'),
  ('a7bc2e8b-8ae4-57a3-a4c7-cecd3d436fc1', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 46, 46, 'In the plain of the Jordan did the king cast them, in the clay ground between Succoth and Zarethan.'),
  ('a9f2393c-f86c-555b-ac42-c0daf34d34b2', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 47, 47, 'Solomon left all the vessels [unweighed], because they were exceeding many: the weight of the brass could not be found out.'),
  ('605cf76e-8992-5ed1-a83d-d0fc9064836c', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 48, 48, 'Solomon made all the vessels that were in the house of Yahweh: the golden altar, and the table whereupon the show bread was, of gold;'),
  ('1f5c1073-9f71-5966-ac0f-ef8781f580ab', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 49, 49, 'and the lampstands, five on the right side, and five on the left, before the oracle, of pure gold; and the flowers, and the lamps, and the tongs, of gold;'),
  ('4218ad16-42c4-57d6-a450-6a449342d7bb', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 50, 50, 'and the cups, and the snuffers, and the basins, and the spoons, and the fire pans, of pure gold; and the hinges, both for the doors of the inner house, the most holy place, and for the doors of the house, [to wit], of the temple, of gold.'),
  ('c409db72-b69a-530a-af85-7e2375e41255', '2e42d65e-8a8b-5b0c-a708-ab514b6ebbae', NULL, 51, 51, 'Thus all the work that king Solomon worked in the house of Yahweh was finished. Solomon brought in the things which David his father had dedicated, [even] the silver, and the gold, and the vessels, and put them in the treasuries of the house of Yahweh.'),
  ('75ec5a31-4b26-551c-ae33-4c96180d5373', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 1, 1, 'Then Solomon assembled the elders of Israel, and all the heads of the tribes, the princes of the fathers'' [houses] of the children of Israel, to king Solomon in Jerusalem, to bring up the ark of the covenant of Yahweh out of the city of David, which is Zion.'),
  ('6a8830c8-4fa7-58d9-abc5-5f13f868d217', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 2, 2, 'All the men of Israel assembled themselves to king Solomon at the feast, in the month Ethanim, which is the seventh month.'),
  ('04026a45-4d7c-5022-a4fe-2184ba4c3200', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 3, 3, 'All the elders of Israel came, and the priests took up the ark.'),
  ('eccb8a72-06d5-52bb-a875-746912e612bd', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 4, 4, 'They brought up the ark of Yahweh, and the Tent of Meeting, and all the holy vessels that were in the Tent; even these did the priests and the Levites bring up.'),
  ('9f1fa6ba-b3c7-50ed-afa5-f944a237995f', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 5, 5, 'King Solomon and all the congregation of Israel, who were assembled to him, were with him before the ark, sacrificing sheep and cattle, that could not be counted nor numbered for multitude.'),
  ('599a1b80-b62b-5fc6-a9ca-672e690a4670', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 6, 6, 'The priests brought in the ark of the covenant of Yahweh to its place, into the oracle of the house, to the most holy place, even under the wings of the cherubim.'),
  ('b28b7ed0-7123-5310-ad2d-02740ba9aa5b', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 7, 7, 'For the cherubim spread forth their wings over the place of the ark, and the cherubim covered the ark and its poles above.'),
  ('29859fae-30dd-54cd-a73c-a34ecc1b9d6c', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 8, 8, 'The poles were so long that the ends of the poles were seen from the holy place before the oracle; but they were not seen outside: and there they are to this day.'),
  ('d3897080-47f5-5b01-ae59-71b48f55ba59', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 9, 9, 'There was nothing in the ark except the two tables of stone which Moses put there at Horeb, when Yahweh made a covenant with the children of Israel, when they came out of the land of Egypt.'),
  ('6388854a-f8e4-587b-aec1-0d345d02fdb7', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 10, 10, 'It came to pass, when the priests were come out of the holy place, that the cloud filled the house of Yahweh,'),
  ('d1227caa-d00c-54ee-ae24-7fd780d617c4', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 11, 11, 'so that the priests could not stand to minister by reason of the cloud; for the glory of Yahweh filled the house of Yahweh.'),
  ('61af5fae-d5c1-548d-ac90-31ab8c3854a2', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 12, 12, 'Then Solomon said, "Yahweh has said that he would dwell in the thick darkness.'),
  ('1e1490b5-fa86-5e5b-a270-8fc4e3cf7add', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 13, 13, 'I have surely built you a house of habitation, a place for you to dwell in forever."'),
  ('a33d8948-6d7a-5d79-aaee-e8732636cccd', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 14, 14, 'The king turned his face about, and blessed all the assembly of Israel: and all the assembly of Israel stood.'),
  ('c1a23ac8-2fcb-5f33-ad25-2f872a868221', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 15, 15, 'He said, "Blessed is Yahweh, the God of Israel, who spoke with his mouth to David your father, and has with his hand fulfilled it, saying,'),
  ('9706b199-ae9a-55fd-a174-62565f528212', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 16, 16, '''Since the day that I brought forth my people Israel out of Egypt, I chose no city out of all the tribes of Israel to build a house, that my name might be there; but I chose David to be over my people Israel.'''),
  ('05bc42e7-c558-5ddc-a4b7-4390cd8e8989', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 17, 17, '"Now it was in the heart of David my father to build a house for the name of Yahweh, the God of Israel.'),
  ('3b7aa252-257c-5c66-a49c-446da7813df1', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 18, 18, 'But Yahweh said to David my father, ''Whereas it was in your heart to build a house for my name, you did well that it was in your heart.'),
  ('5f72940b-a7d2-5ff2-a180-fc33f3bd7008', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 19, 19, 'Nevertheless, you shall not build the house; but your son who shall come forth out of your body, he shall build the house for my name.'''),
  ('83b8620d-a97e-5479-a4dc-45d5e0b1a744', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 20, 20, 'Yahweh has established his word that he spoke; for I have risen up in the place of David my father, and I sit on the throne of Israel, as Yahweh promised, and have built the house for the name of Yahweh, the God of Israel.'),
  ('17ea23a1-55d5-59d0-aa75-87da204a766f', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 21, 21, 'There I have set a place for the ark, in which is the covenant of Yahweh, which he made with our fathers, when he brought them out of the land of Egypt."'),
  ('a2df304a-c01c-5514-afce-64f5841106c0', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 22, 22, 'Solomon stood before the altar of Yahweh in the presence of all the assembly of Israel, and spread forth his hands toward heaven;'),
  ('337a92b9-1449-5b8d-a336-92038f0d28cf', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 23, 23, 'and he said, "Yahweh, the God of Israel, there is no God like you, in heaven above, or on earth beneath; who keep covenant and loving kindness with your servants, who walk before you with all their heart;'),
  ('f4784599-a340-5f3c-a9b3-638ae5be12d4', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 24, 24, 'who have kept with your servant David my father that which you promised him. Yes, you spoke with your mouth, and have fulfilled it with your hand, as it is this day.'),
  ('11afb5c7-aa08-5c34-a085-5323ab0b4c9d', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 25, 25, 'Now therefore, may Yahweh, the God of Israel, keep with your servant David my father that which you have promised him, saying, ''There shall not fail you a man in my sight to sit on the throne of Israel, if only your children take heed to their way, to walk before me as you have walked before me.'''),
  ('4c9b847a-53ca-5ec1-afc0-d16a7e442590', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 26, 26, '"Now therefore, God of Israel, please let your word be verified, which you spoke to your servant David my father.'),
  ('a7525b4c-e7bc-5313-adc7-5eacea1171e3', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 27, 27, 'But will God in very deed dwell on the earth? Behold, heaven and the heaven of heavens can''t contain you; how much less this house that I have built!'),
  ('04bfa1d8-aa94-582b-ad0a-959b9123f8cb', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 28, 28, 'Yet have respect for the prayer of your servant, and for his supplication, Yahweh my God, to listen to the cry and to the prayer which your servant prays before you this day;'),
  ('a776ab68-1b8d-5404-a24b-9217c488b840', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 29, 29, 'that your eyes may be open toward this house night and day, even toward the place of which you have said, ''My name shall be there;'' to listen to the prayer which your servant shall pray toward this place.'),
  ('dce8caa2-a9e1-5752-a1b0-25616f3cda85', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 30, 30, 'Listen to the supplication of your servant, and of your people Israel, when they shall pray toward this place. Yes, hear in heaven, your dwelling place; and when you hear, forgive.'),
  ('e913cc8a-f4c9-51ca-a558-6d5260be21ca', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 31, 31, '"If a man sins against his neighbor, and an oath is laid on him to cause him to swear, and he comes and swear before your altar in this house;'),
  ('b381771d-db90-5570-a238-81edd433ba16', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 32, 32, 'then hear in heaven, and do, and judge your servants, condemning the wicked, to bring his way on his own head, and justifying the righteous, to give him according to his righteousness.'),
  ('5f522df6-bfdf-59ec-a285-002019d95f3e', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 33, 33, '"When your people Israel are struck down before the enemy, because they have sinned against you; if they turn again to you, and confess your name, and pray and make supplication to you in this house:'),
  ('af4d1253-8372-5f2a-ad2f-86a102b9a039', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 34, 34, 'then hear in heaven, and forgive the sin of your people Israel, and bring them again to the land which you gave to their fathers.'),
  ('9660744a-d796-5fae-a265-de2f08962ab9', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 35, 35, '"When the sky is shut up, and there is no rain, because they have sinned against you; if they pray toward this place, and confess your name, and turn from their sin, when you afflict them:'),
  ('52f9720f-8bf1-5c58-af9b-b81b7f639719', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 36, 36, 'then hear in heaven, and forgive the sin of your servants, and of your people Israel, when you teach them the good way in which they should walk; and send rain on your land, which you have given to your people for an inheritance.'),
  ('216aac9b-acb8-5f02-ad69-041c0f89ff2c', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 37, 37, '"If there is famine in the land, if there is pestilence, if there is blight, mildew, locust or caterpillar; if their enemy besieges them in the land of their cities; whatever plague, whatever sickness there is;'),
  ('4573b2a0-b152-5e0d-abe9-3fb3c149be94', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 38, 38, 'whatever prayer and supplication is made by any man, or by all your people Israel, who shall each know the plague of his own heart, and spread forth his hands toward this house:'),
  ('2312f8a7-6562-58cc-acc7-6e96b31aed1d', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 39, 39, 'then hear in heaven, your dwelling place, and forgive, and do, and render to every man according to all his ways, whose heart you know; (for you, even you only, know the hearts of all the children of men;)'),
  ('ab979781-b781-5721-a88c-b5c6fdcb4077', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 40, 40, 'that they may fear you all the days that they live in the land which you gave to our fathers.'),
  ('0431539e-555f-564a-a754-f5e7ac932ae2', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 41, 41, '"Moreover concerning the foreigner, who is not of your people Israel, when he shall come out of a far country for your name''s sake'),
  ('ae652468-f5c1-5199-a5ee-1c26612792de', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 42, 42, '(for they shall hear of your great name, and of your mighty hand, and of your outstretched arm); when he shall come and pray toward this house;'),
  ('c48c1377-b264-58aa-a817-c82f755693e0', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 43, 43, 'hear in heaven, your dwelling place, and do according to all that the foreigner calls to you for; that all the peoples of the earth may know your name, to fear you, as do your people Israel, and that they may know that this house which I have built is called by your name.'),
  ('1a2c91a4-5bae-527d-a255-6b1c12b6d21c', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 44, 44, '"If your people go out to battle against their enemy, by whatever way you shall send them, and they pray to Yahweh toward the city which you have chosen, and toward the house which I have built for your name;'),
  ('834443b0-3f70-5fd5-a843-b37759943837', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 45, 45, 'then hear in heaven their prayer and their supplication, and maintain their cause.'),
  ('c3e5c3bd-bd85-56d3-a912-41f9f1ce4938', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 46, 46, 'If they sin against you (for there is no man who doesn''t sin), and you are angry with them, and deliver them to the enemy, so that they carry them away captive to the land of the enemy, far off or near;'),
  ('d505bdfc-b883-5a46-ab46-41c16c070059', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 47, 47, 'yet if they shall repent in the land where they are carried captive, and turn again, and make supplication to you in the land of those who carried them captive, saying, ''We have sinned, and have done perversely; we have dealt wickedly;'''),
  ('140f48f2-8096-5c02-ab35-ed69a534a138', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 48, 48, 'if they return to you with all their heart and with all their soul in the land of their enemies, who carried them captive, and pray to you toward their land, which you gave to their fathers, the city which you have chosen, and the house which I have built for your name:'),
  ('f67d68cb-275b-5a7c-a4bd-886acfe48f2d', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 49, 49, 'then hear their prayer and their supplication in heaven, your dwelling place, and maintain their cause;'),
  ('762bd03f-43e9-5bf2-a6da-71fc6ddd0f49', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 50, 50, 'and forgive your people who have sinned against you, and all their transgressions in which they have transgressed against you; and give them compassion before those who carried them captive, that they may have compassion on them'),
  ('7bee8098-9461-527a-a1d4-3daf0a218497', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 51, 51, '(for they are your people, and your inheritance, which you brought forth out of Egypt, from the midst of the furnace of iron);'),
  ('d4deb727-3cef-5225-ae30-98d65db86acf', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 52, 52, 'that your eyes may be open to the supplication of your servant, and to the supplication of your people Israel, to listen to them whenever they cry to you.'),
  ('8166d112-941b-5b95-a723-136528abc006', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 53, 53, 'For you separated them from among all the peoples of the earth, to be your inheritance, as you spoke by Moses your servant, when you brought our fathers out of Egypt, Lord Yahweh."'),
  ('d84d997a-6402-5cff-a799-2588a8ca729d', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 54, 54, 'It was so, that when Solomon had made an end of praying all this prayer and supplication to Yahweh, he arose from before the altar of Yahweh, from kneeling on his knees with his hands spread forth toward heaven.'),
  ('ae1b870a-e3d7-59c2-ae26-3a07def2c032', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 55, 55, 'He stood, and blessed all the assembly of Israel with a loud voice, saying,'),
  ('eadbfc6f-864a-50af-a89f-97ae1619f5f0', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 56, 56, '"Blessed be Yahweh, who has given rest to his people Israel, according to all that he promised. There has not failed one word of all his good promise, which he promised by Moses his servant.'),
  ('92b0acfa-469b-5fc1-a577-684467817dda', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 57, 57, 'May Yahweh our God be with us, as he was with our fathers. Let him not leave us, nor forsake us;'),
  ('b4216e66-0fd0-5fa4-a93f-78d6a623dfac', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 58, 58, 'that he may incline our hearts to him, to walk in all his ways, and to keep his commandments, and his statutes, and his ordinances, which he commanded our fathers.'),
  ('16e16bf3-d097-5712-a34c-6dba45484dbf', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 59, 59, 'Let these my words, with which I have made supplication before Yahweh, be near to Yahweh our God day and night, that he may maintain the cause of his servant, and the cause of his people Israel, as every day shall require;'),
  ('1b88a0d3-764f-5a58-a5b3-9d95eded16ac', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 60, 60, 'that all the peoples of the earth may know that Yahweh, he is God. There is none else.'),
  ('431ade70-66c2-54fa-af2b-5976e5a60892', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 61, 61, '"Let your heart therefore be perfect with Yahweh our God, to walk in his statutes, and to keep his commandments, as at this day."'),
  ('5e5a0f2b-b0a6-5ea1-a982-b3059ab661da', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 62, 62, 'The king, and all Israel with him, offered sacrifice before Yahweh.'),
  ('cdffd2b8-0058-56af-aa0f-dbb7c771ddcf', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 63, 63, 'Solomon offered for the sacrifice of peace offerings, which he offered to Yahweh, two and twenty thousand head of cattle, and one hundred twenty thousand sheep. So the king and all the children of Israel dedicated the house of Yahweh.'),
  ('362da3d9-ddab-529a-ab68-68adff16ab55', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 64, 64, 'The same day did the king make the middle of the court holy that was before the house of Yahweh; for there he offered the burnt offering, and the meal offering, and the fat of the peace offerings, because the bronze altar that was before Yahweh was too little to receive the burnt offering, and the meal offering, and the fat of the peace offerings.'),
  ('6c335776-e7c5-5b1a-a449-bc4438ca8acd', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 65, 65, 'So Solomon held the feast at that time, and all Israel with him, a great assembly, from the entrance of Hamath to the brook of Egypt, before Yahweh our God, seven days and seven days, even fourteen days.'),
  ('1b2d4ec8-cd7c-5f26-ac5f-07ef71f903ee', 'e8f31f69-18db-525a-a82c-3ae71748321f', NULL, 66, 66, 'On the eighth day he sent the people away; and they blessed the king, and went to their tents joyful and glad of heart for all the goodness that Yahweh had shown to David his servant, and to Israel his people.'),
  ('b5980b78-6a52-5ff9-a227-a31c21cc0827', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 1, 1, 'It happened, when Solomon had finished the building of the house of Yahweh, and the king''s house, and all Solomon''s desire which he was pleased to do,'),
  ('9476c1f1-a492-539f-a7c5-aa6c1f2ef339', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 2, 2, 'that Yahweh appeared to Solomon the second time, as he had appeared to him at Gibeon.'),
  ('92f299e3-be12-55d5-a1aa-e83db41089a2', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 3, 3, 'Yahweh said to him, "I have heard your prayer and your supplication, that you have made before me. I have made this house holy, which you have built, to put my name there forever; and my eyes and my heart shall be there perpetually.'),
  ('71259c07-95db-5eee-ac57-53f058d5a018', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 4, 4, 'As for you, if you will walk before me, as David your father walked, in integrity of heart, and in uprightness, to do according to all that I have commanded you, and will keep my statutes and my ordinances;'),
  ('d8f022c9-dd6f-5a46-af07-26e03c721cae', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 5, 5, 'then I will establish the throne of your kingdom over Israel forever, according as I promised to David your father, saying, ''There shall not fail you a man on the throne of Israel.'''),
  ('6cd41dfb-3d49-52bf-acd0-91daeff762e8', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 6, 6, 'But if you turn away from following me, you or your children, and not keep my commandments and my statutes which I have set before you, but shall go and serve other gods, and worship them;'),
  ('23aecf0f-75f9-5091-a40c-1800ccfc0841', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 7, 7, 'then will I cut off Israel out of the land which I have given them; and this house, which I have made holy for my name, will I cast out of my sight; and Israel shall be a proverb and a byword among all peoples.'),
  ('5b1eb537-8861-577f-a6d9-cd20570b2aab', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 8, 8, 'Though this house is so high, yet shall everyone who passes by it be astonished, and shall hiss; and they shall say, ''Why has Yahweh done thus to this land, and to this house?'''),
  ('535a499d-8c06-5c1b-a5c2-d41f4ea5af51', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 9, 9, 'and they shall answer, ''Because they forsook Yahweh their God, who brought forth their fathers out of the land of Egypt, and laid hold of other gods, and worshiped them, and served them. Therefore Yahweh has brought all this evil on them.''"'),
  ('ea9ad91f-fc0b-59b0-ae61-03f6945cbc32', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 10, 10, 'It happened at the end of twenty years, in which Solomon had built the two houses, the house of Yahweh and the king''s house'),
  ('28629f53-be48-5e84-ac58-c50016e38f9c', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 11, 11, '(now Hiram the king of Tyre had furnished Solomon with cedar trees and fir trees, and with gold, according to all his desire), that then king Solomon gave Hiram twenty cities in the land of Galilee.'),
  ('61dd3bdc-c8e2-5abc-adb8-cca3741ae0f5', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 12, 12, 'Hiram came out from Tyre to see the cities which Solomon had given him; and they didn''t please him.'),
  ('c8da8504-043f-5ea4-a3f2-067d3ebf0101', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 13, 13, 'He said, "What cities are these which you have given me, my brother?" He called them the land of Cabul to this day.'),
  ('4f59b079-c7cc-5e88-a4ef-c9caa8efd8b7', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 14, 14, 'Hiram sent to the king one hundred twenty talents of gold.'),
  ('fae048af-c5a1-5978-a07f-b05d9d87c69f', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 15, 15, 'This is the reason of the levy which king Solomon raised, to build the house of Yahweh, and his own house, and Millo, and the wall of Jerusalem, and Hazor, and Megiddo, and Gezer.'),
  ('54dabbda-51c1-5a8b-a5c3-af4ac15ccb89', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 16, 16, 'Pharaoh king of Egypt had gone up, and taken Gezer, and burnt it with fire, and slain the Canaanites who lived in the city, and given it for a portion to his daughter, Solomon''s wife.'),
  ('e2e07a95-c90b-5eb1-a49d-cc502c977855', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 17, 17, 'Solomon built Gezer, and Beth Horon the lower,'),
  ('6bc5525a-b72a-580b-ae4e-889a197e9e23', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 18, 18, 'and Baalath, and Tamar in the wilderness, in the land,'),
  ('6a52151a-d2b7-5189-a0ce-2abbcdf51734', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 19, 19, 'and all the storage cities that Solomon had, and the cities for his chariots, and the cities for his horsemen, and that which Solomon desired to build for his pleasure in Jerusalem, and in Lebanon, and in all the land of his dominion.'),
  ('2d2ad886-160a-5453-aa85-e173c9aa8a75', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 20, 20, 'As for all the people who were left of the Amorites, the Hittites, the Perizzites, the Hivites, and the Jebusites, who were not of the children of Israel;'),
  ('81044239-97b6-514b-ac9a-16dbba949283', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 21, 21, 'their children who were left after them in the land, whom the children of Israel were not able utterly to destroy, of them did Solomon raise a levy of bondservants to this day.'),
  ('d6429688-4473-5ac9-a241-ade3654fc4cc', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 22, 22, 'But of the children of Israel did Solomon make no bondservants; but they were the men of war, and his servants, and his princes, and his captains, and rulers of his chariots and of his horsemen.'),
  ('4d2db246-b5c2-5d81-a2ad-1979959952ab', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 23, 23, 'These were the chief officers who were over Solomon''s work, five hundred fifty, who bore rule over the people who labored in the work.'),
  ('675182ff-b69a-5a50-a9c6-073aed135c74', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 24, 24, 'But Pharaoh''s daughter came up out of the city of David to her house which [Solomon] had built for her: then did he build Millo.'),
  ('fbb0bcbb-f797-5a08-a0e6-9a72982cd2d1', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 25, 25, 'Three times a year did Solomon offer burnt offerings and peace offerings on the altar which he built to Yahweh, burning incense therewith, [on the altar] that was before Yahweh. So he finished the house.'),
  ('b959e669-e7ca-5355-ad44-16eb13420ac5', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 26, 26, 'King Solomon made a navy of ships in Ezion Geber, which is beside Eloth, on the shore of the Red Sea, in the land of Edom.'),
  ('4e70645a-4f7f-5424-afae-db2495ec64d5', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 27, 27, 'Hiram sent in the navy his servants, sailors who had knowledge of the sea, with the servants of Solomon.'),
  ('ac3851af-1947-584f-a560-b85073712d28', 'add1f7df-3203-57ef-a87a-8f5e35b40a88', NULL, 28, 28, 'They came to Ophir, and fetched from there gold, four hundred and twenty talents, and brought it to king Solomon.'),
  ('6cbce31e-58d6-59de-a27b-6c2e9d03ab05', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 1, 1, 'When the queen of Sheba heard of the fame of Solomon concerning the name of Yahweh, she came to prove him with hard questions.'),
  ('a4b8b2ee-0d63-570a-a44c-99e8c10050aa', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 2, 2, 'She came to Jerusalem with a very great train, with camels that bore spices, and very much gold, and precious stones; and when she was come to Solomon, she talked with him of all that was in her heart.'),
  ('64e98d68-b84e-5fcd-a6ec-87a0cbeb1025', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 3, 3, 'Solomon told her all her questions: there was not anything hidden from the king which he didn''t tell her.'),
  ('40c6d90f-f83d-5fef-a318-7e2dbcc36d28', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 4, 4, 'When the queen of Sheba had seen all the wisdom of Solomon, and the house that he had built,'),
  ('c8a760bc-1078-5c0d-aea8-4e9353d43fbf', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 5, 5, 'and the food of his table, and the sitting of his servants, and the attendance of his ministers, and their clothing, and his cup bearers, and his ascent by which he went up to the house of Yahweh; there was no more spirit in her.'),
  ('b38defcc-91c1-5605-a95f-992f1558c5c1', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 6, 6, 'She said to the king, "It was a true report that I heard in my own land of your acts, and of your wisdom.'),
  ('835b4c5d-54da-5f72-a89f-d0e54f66f449', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 7, 7, 'However I didn''t believe the words, until I came, and my eyes had seen it. Behold, the half was not told me! Your wisdom and prosperity exceed the fame which I heard.'),
  ('269f280d-c1b3-5afb-a6c4-7e9b897c961f', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 8, 8, 'Happy are your men, happy are these your servants, who stand continually before you, who hear your wisdom.'),
  ('e49f7906-2904-5626-ad20-f4393836741b', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 9, 9, 'Blessed is Yahweh your God, who delighted in you, to set you on the throne of Israel. Because Yahweh loved Israel forever, therefore made he you king, to do justice and righteousness."'),
  ('05e27d6e-201f-510c-ac8f-815d8e836bad', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 10, 10, 'She gave the king one hundred twenty talents of gold, and of spices very great store, and precious stones. There came no more such abundance of spices as these which the queen of Sheba gave to king Solomon.'),
  ('6705a784-bce6-5b01-a26b-0a788f08b3ad', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 11, 11, 'The navy also of Hiram, that brought gold from Ophir, brought in from Ophir great plenty of almug trees and precious stones.'),
  ('6e05ec0c-6b3a-5a14-a6c6-06d2dd409770', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 12, 12, 'The king made of the almug trees pillars for the house of Yahweh, and for the king''s house, harps also and stringed instruments for the singers: there came no such almug trees, nor were seen, to this day.'),
  ('6c20264d-bc1a-56a9-ad7b-a9b1d6e89860', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 13, 13, 'King Solomon gave to the queen of Sheba all her desire, whatever she asked, besides that which Solomon gave her of his royal bounty. So she turned, and went to her own land, she and her servants.'),
  ('07a9cac4-f018-5a49-ae40-327cf1d13842', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 14, 14, 'Now the weight of gold that came to Solomon in one year was six hundred sixty-six talents of gold,'),
  ('a87107e8-c9fc-534a-a203-3e262e18780d', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 15, 15, 'besides [that which] the traders [brought], and the traffic of the merchants, and of all the kings of the mixed people, and of the governors of the country.'),
  ('26f9a37e-2802-5786-a5cf-79399f7285c9', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 16, 16, 'King Solomon made two hundred bucklers of beaten gold; six hundred [shekels] of gold went to one buckler.'),
  ('4aaa938a-3a1a-5c86-acde-e219dccc7fec', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 17, 17, '[he made] three hundred shields of beaten gold; three minas of gold went to one shield: and the king put them in the house of the forest of Lebanon.'),
  ('6536aaff-7f7a-5fc4-a3ff-3d7456abb90d', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 18, 18, 'Moreover the king made a great throne of ivory, and overlaid it with the finest gold.'),
  ('f608655f-3207-560d-a94c-510fbae9179c', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 19, 19, 'There were six steps to the throne, and the top of the throne was round behind; and there were stays on either side by the place of the seat, and two lions standing beside the stays.'),
  ('41a93445-ebe6-574a-a831-69caa3575043', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 20, 20, 'Twelve lions stood there on the one side and on the other on the six steps: there was nothing like it made in any kingdom.'),
  ('8c2811c0-e209-5caa-a9a2-14895a2affef', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 21, 21, 'All king Solomon''s drinking vessels were of gold, and all the vessels of the house of the forest of Lebanon were of pure gold: none were of silver; it was nothing accounted of in the days of Solomon.'),
  ('c55a5f5e-8766-5a99-a8d1-377ba508720a', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 22, 22, 'For the king had at sea a navy of Tarshish with the navy of Hiram: once every three years came the navy of Tarshish, bringing gold, and silver, ivory, and apes, and peacocks.'),
  ('65c007d5-704b-54b9-a496-94027e85fff6', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 23, 23, 'So king Solomon exceeded all the kings of the earth in riches and in wisdom.'),
  ('b6d6f1ad-44ea-5473-acb2-9791bb8ade19', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 24, 24, 'All the earth sought the presence of Solomon, to hear his wisdom, which God had put in his heart.'),
  ('1310c5bf-d288-5652-afe5-2673a01c98e1', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 25, 25, 'They brought every man his tribute, vessels of silver, and vessels of gold, and clothing, and armor, and spices, horses, and mules, a rate year by year.'),
  ('36e1b54d-540e-536c-a3d2-cb4f0408a1fe', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 26, 26, 'Solomon gathered together chariots and horsemen: and he had a thousand and four hundred chariots, and twelve thousand horsemen, that he bestowed in the chariot cities, and with the king at Jerusalem.'),
  ('7d5c163c-f8b3-561f-a664-91ed5f3d098d', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 27, 27, 'The king made silver to be in Jerusalem as stones, and cedars made he to be as the sycamore trees that are in the lowland, for abundance.'),
  ('043a8766-9f59-5099-a820-73b5ba7a4811', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 28, 28, 'The horses which Solomon had were brought out of Egypt; and the king''s merchants received them in droves, each drove at a price.'),
  ('2778f49c-84b1-5599-a361-bc392bf9b547', '23db08d5-704a-5cec-a497-261ca99adf04', NULL, 29, 29, 'A chariot came up and went out of Egypt for six hundred [shekels] of silver, and a horse for one hundred fifty; and so for all the kings of the Hittites, and for the kings of Syria, did they bring them out by their means.'),
  ('17043b5d-88e3-5067-ae86-c5b1658a6cec', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 1, 1, 'Now king Solomon loved many foreign women, together with the daughter of Pharaoh, women of the Moabites, Ammonites, Edomites, Sidonians, and Hittites;'),
  ('52caba30-f4a5-52b6-a078-7601c1f6065b', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 2, 2, 'of the nations concerning which Yahweh said to the children of Israel, "You shall not go among them, neither shall they come among you; for surely they will turn away your heart after their gods." Solomon joined to these in love.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('87e460a3-ac8a-5a3a-a32e-fcd1b8b808d9', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 3, 3, 'He had seven hundred wives, princesses, and three hundred concubines; and his wives turned away his heart.'),
  ('fc6f99bf-58ba-517b-a29d-5e564b289f8c', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 4, 4, 'For it happened, when Solomon was old, that his wives turned away his heart after other gods; and his heart was not perfect with Yahweh his God, as was the heart of David his father.'),
  ('c5eb0955-09ba-557f-ac71-9a2327425c1c', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 5, 5, 'For Solomon went after Ashtoreth the goddess of the Sidonians, and after Milcom the abomination of the Ammonites.'),
  ('e735a706-f6ea-5881-affc-c1490498f142', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 6, 6, 'Solomon did that which was evil in the sight of Yahweh, and didn''t go fully after Yahweh, as did David his father.'),
  ('53d81d8d-4199-51b0-a174-f35e9beea010', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 7, 7, 'Then did Solomon build a high place for Chemosh the abomination of Moab, on the mountain that is before Jerusalem, and for Molech the abomination of the children of Ammon.'),
  ('8a750f5e-6ae2-5a3d-a75b-d862d1daf83c', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 8, 8, 'So did he for all his foreign wives, who burnt incense and sacrificed to their gods.'),
  ('601346a3-8054-59fa-a620-29327ce8fd58', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 9, 9, 'Yahweh was angry with Solomon, because his heart was turned away from Yahweh, the God of Israel, who had appeared to him twice,'),
  ('fdc9069f-5849-5a26-a7d6-66cc5a4b4954', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 10, 10, 'and had commanded him concerning this thing, that he should not go after other gods: but he didn''t keep that which Yahweh commanded.'),
  ('d27db6f8-b0d1-509f-acac-54273395a859', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 11, 11, 'Therefore Yahweh said to Solomon, "Because this is done by you, and you have not kept my covenant and my statutes, which I have commanded you, I will surely tear the kingdom from you, and will give it to your servant.'),
  ('499a209d-eff8-5e2b-aaeb-b42721a0d98b', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 12, 12, 'Notwithstanding I will not do it in your days, for David your father''s sake; but I will tear it out of the hand of your son.'),
  ('19074c4a-0a4c-5f1b-a235-88a9f62d0c82', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 13, 13, 'However I will not tear away all the kingdom; but I will give one tribe to your son, for David my servant''s sake, and for Jerusalem''s sake which I have chosen."'),
  ('10f943a4-030d-50c8-aa91-26f960665155', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 14, 14, 'Yahweh raised up an adversary to Solomon, Hadad the Edomite: he was of the king''s seed in Edom.'),
  ('2e522e34-c0fa-5c53-a39d-2e9bb1e0d40c', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 15, 15, 'For it happened, when David was in Edom, and Joab the captain of the army was gone up to bury the slain, and had struck every male in Edom'),
  ('0b3ec9b2-c400-5392-ad8a-9c657895ddd1', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 16, 16, '(for Joab and all Israel remained there six months, until he had cut off every male in Edom);'),
  ('b3e47106-01a8-5f6a-a2f2-4a2c08346cbc', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 17, 17, 'that Hadad fled, he and certain Edomites of his father''s servants with him, to go into Egypt, Hadad being yet a little child.'),
  ('61ef7f5c-00b8-5eb5-a2a1-176aeb59c341', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 18, 18, 'They arose out of Midian, and came to Paran; and they took men with them out of Paran, and they came to Egypt, to Pharaoh king of Egypt, who gave him a house, and appointed him food, and gave him land.'),
  ('e28d88ba-3aef-5835-aaea-3f440a6d91e9', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 19, 19, 'Hadad found great favor in the sight of Pharaoh, so that he gave him as wife the sister of his own wife, the sister of Tahpenes the queen.'),
  ('e3e428b3-d23c-5188-a1fc-4c0ee7a6b8dc', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 20, 20, 'The sister of Tahpenes bore him Genubath his son, whom Tahpenes weaned in Pharaoh''s house; and Genubath was in Pharaoh''s house among the sons of Pharaoh.'),
  ('019a8d34-2695-5789-ab13-f70c4b0d5999', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 21, 21, 'When Hadad heard in Egypt that David slept with his fathers, and that Joab the captain of the army was dead, Hadad said to Pharaoh, "Let me depart, that I may go to my own country."'),
  ('39254b7a-83b4-5050-a3dc-f629c555c7ff', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 22, 22, 'Then Pharaoh said to him, "But what have you lacked with me, that behold, you seek to go to your own country?" He answered, "Nothing, however only let me depart."'),
  ('cb8235cd-f4f3-5b2a-acf6-649128e36539', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 23, 23, 'God raised up [another] adversary to him, Rezon the son of Eliada, who had fled from his lord Hadadezer king of Zobah.'),
  ('228a725c-726a-5c54-a4bc-97a3c15ee21d', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 24, 24, 'He gathered men to him, and became captain over a troop, when David killed them [of Zobah]: and they went to Damascus, and lived therein, and reigned in Damascus.'),
  ('250cf6a9-ab9f-5ee1-a116-b1cc34b42046', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 25, 25, 'He was an adversary to Israel all the days of Solomon, besides the mischief that Hadad [did]: and he abhorred Israel, and reigned over Syria.'),
  ('9dd4eb5a-50f2-57a4-ab6b-0c3159c5a63e', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 26, 26, 'Jeroboam the son of Nebat, an Ephraimite of Zeredah, a servant of Solomon, whose mother''s name was Zeruah, a widow, he also lifted up his hand against the king.'),
  ('7d8685d3-9d8f-5518-a3e7-7fd9ad106ffd', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 27, 27, 'This was the reason why he lifted up his hand against the king: Solomon built Millo, and repaired the breach of the city of David his father.'),
  ('81565eea-58a2-5c31-af6f-b124b53b59f6', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 28, 28, 'The man Jeroboam was a mighty man of valor; and Solomon saw the young man that he was industrious, and he put him in charge of all the labor of the house of Joseph.'),
  ('39d5d075-eb90-561e-a800-90fd8d6ba219', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 29, 29, 'It happened at that time, when Jeroboam went out of Jerusalem, that the prophet Ahijah the Shilonite found him in the way; now [Ahijah] had clad himself with a new garment; and they two were alone in the field.'),
  ('e8d8e82d-54aa-5e62-a6ef-f409845f5c93', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 30, 30, 'Ahijah laid hold of the new garment that was on him, and tore it in twelve pieces.'),
  ('234bcbe3-c3f5-58a7-a407-250f062e9030', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 31, 31, 'He said to Jeroboam, "Take ten pieces; for thus says Yahweh, the God of Israel, ''Behold, I will tear the kingdom out of the hand of Solomon, and will give ten tribes to you'),
  ('6ff31110-6f83-5cba-afcb-49740508bde0', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 32, 32, '(but he shall have one tribe, for my servant David''s sake and for Jerusalem''s sake, the city which I have chosen out of all the tribes of Israel);'),
  ('d0e18676-7f7e-565f-ac2c-e0e4aec89d89', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 33, 33, 'because that they have forsaken me, and have worshiped Ashtoreth the goddess of the Sidonians, Chemosh the god of Moab, and Milcom the god of the children of Ammon. They have not walked in my ways, to do that which is right in my eyes, and [to keep] my statutes and my ordinances, as David his father did.'),
  ('8cffd92d-c181-52c3-a0dc-f9a6e943209b', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 34, 34, '"''However I will not take the whole kingdom out of his hand; but I will make him prince all the days of his life, for David my servant''s sake whom I chose, who kept my commandments and my statutes;'),
  ('d65555c7-2165-544d-a0bf-ce7f05a9ac6e', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 35, 35, 'but I will take the kingdom out of his son''s hand, and will give it to you, even ten tribes.'),
  ('15ccf43e-e75e-5b5a-a3c5-73d3d0483771', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 36, 36, 'To his son will I give one tribe, that David my servant may have a lamp always before me in Jerusalem, the city which I have chosen me to put my name there.'),
  ('3315e5bd-26bc-51a8-adf0-aa8d94c3d264', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 37, 37, 'I will take you, and you shall reign according to all that your soul desires, and shall be king over Israel.'),
  ('fef01e4c-e132-56e1-a2ff-17977527db45', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 38, 38, 'It shall be, if you will listen to all that I command you, and will walk in my ways, and do that which is right in my eyes, to keep my statutes and my commandments, as David my servant did; that I will be with you, and will build you a sure house, as I built for David, and will give Israel to you.'),
  ('079d6b27-57b3-5b8a-a12d-41fe3cb670af', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 39, 39, 'I will for this afflict the seed of David, but not forever.''"'),
  ('6113c51d-6c3c-5ff5-a09c-1a4464efa5ba', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 40, 40, 'Solomon sought therefore to kill Jeroboam; but Jeroboam arose, and fled into Egypt, to Shishak king of Egypt, and was in Egypt until the death of Solomon.'),
  ('dcd61805-a48a-5579-a546-de7246463db8', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 41, 41, 'Now the rest of the acts of Solomon, and all that he did, and his wisdom, aren''t they written in the book of the acts of Solomon?'),
  ('459cf223-148f-5030-a807-1b469a262ea5', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 42, 42, 'The time that Solomon reigned in Jerusalem over all Israel was forty years.'),
  ('e81e1300-349d-55c6-a03e-3ce6306eab4b', '125e7aec-67be-5498-ab75-c835800a4604', NULL, 43, 43, 'Solomon slept with his fathers, and was buried in the city of David his father: and Rehoboam his son reigned in his place.'),
  ('d781cbbd-073e-5156-a830-3cc9bd656d19', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 1, 1, 'Rehoboam went to Shechem: for all Israel were come to Shechem to make him king.'),
  ('6466c0c7-868d-5c58-aaf4-3a4433b79ad7', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 2, 2, 'It happened, when Jeroboam the son of Nebat heard of it (for he was yet in Egypt, where he had fled from the presence of king Solomon, and Jeroboam lived in Egypt,'),
  ('2ff6bb9e-73cf-5e67-a539-11e9f20b4cda', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 3, 3, 'and they sent and called him), that Jeroboam and all the assembly of Israel came, and spoke to Rehoboam, saying,'),
  ('8fab76fa-f287-5c07-abfe-6af1541a3a6e', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 4, 4, '"Your father made our yoke grievous: now therefore make you the grievous service of your father, and his heavy yoke which he put on us, lighter, and we will serve you."'),
  ('d32d5d5a-e459-51d7-a36c-edfa92b80a2d', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 5, 5, 'He said to them, "Depart for three days, then come back to me." The people departed.'),
  ('2fbcff32-11f1-5ea2-ac57-2c0f5b150f50', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 6, 6, 'King Rehoboam took counsel with the old men, who had stood before Solomon his father while he yet lived, saying, "What counsel do you give me to return answer to this people?"'),
  ('a8fffd01-5a4f-5d15-a73c-fa4cf4f1d839', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 7, 7, 'They spoke to him, saying, "If you will be a servant to this people this day, and will serve them, and answer them, and speak good words to them, then they will be your servants forever."'),
  ('d203b848-c628-5cf9-ad0a-ba696432daa1', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 8, 8, 'But he forsook the counsel of the old men which they had given him, and took counsel with the young men who had grown up with him, who stood before him.'),
  ('d1c38d87-5a42-5755-ab52-99ced4e2e7b0', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 9, 9, 'He said to them, "What counsel do you give, that we may return answer to this people, who have spoken to me, saying, ''Make the yoke that your father did put on us lighter?''"'),
  ('63f13279-9a15-593c-a20a-d11728130e49', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 10, 10, 'The young men who had grown up with him spoke to him, saying, "Thus you shall tell this people who spoke to you, saying, ''Your father made our yoke heavy, but make it lighter to us;'' you shall say to them, ''My little finger is thicker than my father''s waist.'),
  ('d66913c4-74ee-5363-a5a8-c346cef970ac', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 11, 11, 'Now whereas my father burdened you with a heavy yoke, I will add to your yoke: my father chastised you with whips, but I will chastise you with scorpions.''"'),
  ('28c17cd6-ef5b-58de-aee8-0282570cf9a1', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 12, 12, 'So Jeroboam and all the people came to Rehoboam the third day, as the king asked, saying, "Come to me again the third day."'),
  ('86cf444b-f8de-5573-a9a3-50e1eb3d2e7d', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 13, 13, 'The king answered the people roughly, and forsook the counsel of the old men which they had given him,'),
  ('35d96c7e-0d3c-5650-a5bd-af9fee00b072', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 14, 14, 'and spoke to them according to the counsel of the young men, saying, "My father made your yoke heavy, but I will add to your yoke. My father chastised you with whips, but I will chastise you with scorpions."'),
  ('95347381-c051-5d68-af2f-b42cf889b802', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 15, 15, 'So the king didn''t listen to the people; for it was a thing brought about of Yahweh, that he might establish his word, which Yahweh spoke by Ahijah the Shilonite to Jeroboam the son of Nebat.'),
  ('168896bf-a67d-593b-a2d5-cf0aa9638ce8', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 16, 16, 'When all Israel saw that the king didn''t listen to them, the people answered the king, saying, "What portion have we in David? Neither do we have an inheritance in the son of Jesse. To your tents, Israel! Now see to your own house, David." So Israel departed to their tents.'),
  ('eecf487f-67c2-5719-a0ae-1c18ca0d75d2', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 17, 17, 'But as for the children of Israel who lived in the cities of Judah, Rehoboam reigned over them.'),
  ('534cf063-8507-516f-aa81-6366d8cfd0ff', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 18, 18, 'Then king Rehoboam sent Adoram, who was over the men subject to forced labor; and all Israel stoned him to death with stones. King Rehoboam made speed to get him up to his chariot, to flee to Jerusalem.'),
  ('3e532853-8292-5ffc-ae46-3e067bd4820c', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 19, 19, 'So Israel rebelled against the house of David to this day.'),
  ('d08523b0-42e2-507f-ade3-a5f3a6c3e472', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 20, 20, 'It happened, when all Israel heard that Jeroboam was returned, that they sent and called him to the congregation, and made him king over all Israel: there was none who followed the house of David, but the tribe of Judah only.'),
  ('8ccbb71b-a84b-51c5-abc8-5c22be327cb1', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 21, 21, 'When Rehoboam was come to Jerusalem, he assembled all the house of Judah, and the tribe of Benjamin, a hundred and eighty thousand chosen men, who were warriors, to fight against the house of Israel, to bring the kingdom again to Rehoboam the son of Solomon.'),
  ('b3421e04-0d2a-50a1-ae17-721f93b801b0', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 22, 22, 'But the word of God came to Shemaiah the man of God, saying,'),
  ('f1571445-f721-5d64-a433-098f8c73aaf0', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 23, 23, '"Speak to Rehoboam the son of Solomon, king of Judah, and to all the house of Judah and Benjamin, and to the rest of the people, saying,'),
  ('6dd0b831-d422-5278-a882-2d367cec8e71', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 24, 24, '''Thus says Yahweh, "You shall not go up, nor fight against your brothers, the children of Israel. Everyone return to his house; for this thing is of me."''" So they listened to the word of Yahweh, and returned and went their way, according to the word of Yahweh.'),
  ('805c0e22-e6bb-5b59-aec5-c680c5fecbed', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 25, 25, 'Then Jeroboam built Shechem in the hill country of Ephraim, and lived in it; and he went out from there, and built Penuel.'),
  ('acc3be3c-2c26-5155-a69f-420b0d744895', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 26, 26, 'Jeroboam said in his heart, "Now the kingdom will return to the house of David.'),
  ('c9aa9789-b167-54a0-a552-aafbfa4a80f5', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 27, 27, 'If this people goes up to offer sacrifices in the house of Yahweh at Jerusalem, then the heart of this people will turn again to their lord, even to Rehoboam king of Judah; and they will kill me, and return to Rehoboam king of Judah."'),
  ('271b5639-3868-5292-a05d-68b54fcbabd9', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 28, 28, 'Whereupon the king took counsel, and made two calves of gold; and he said to them, "It is too much for you to go up to Jerusalem. Look and see your gods, Israel, which brought you up out of the land of Egypt!"'),
  ('7bb58af0-e528-591b-abaf-4fbcf5e97f21', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 29, 29, 'He set the one in Bethel, and the other put he in Dan.'),
  ('32b68a1d-b6e6-569d-a6ea-c932a88650c6', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 30, 30, 'This thing became a sin; for the people went [to worship] before the one, even to Dan.'),
  ('e0a59808-8e99-5e11-ae93-ed05c72a078a', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 31, 31, 'He made houses of high places, and made priests from among all the people, who were not of the sons of Levi.'),
  ('e1da313c-d3ab-58d8-a31b-1c059fc72ef5', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 32, 32, 'Jeroboam ordained a feast in the eighth month, on the fifteenth day of the month, like the feast that is in Judah, and he went up to the altar; so did he in Bethel, sacrificing to the calves that he had made: and he placed in Bethel the priests of the high places that he had made.'),
  ('f368f785-67e3-5470-ad7d-711eeac7daa2', 'a7063e42-f63b-53bf-aca8-646ef3427ef7', NULL, 33, 33, 'He went up to the altar which he had made in Bethel on the fifteenth day in the eighth month, even in the month which he had devised of his own heart: and he ordained a feast for the children of Israel, and went up to the altar, to burn incense.'),
  ('a3e7c70f-041c-55c5-a0f6-a3aaf0e15b29', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 1, 1, 'Behold, there came a man of God out of Judah by the word of Yahweh to Beth El: and Jeroboam was standing by the altar to burn incense.'),
  ('ed8b2e81-918c-5134-a6c6-4d6bb662fba3', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 2, 2, 'He cried against the altar by the word of Yahweh, and said, "Altar, altar, thus says Yahweh: ''Behold, a son shall be born to the house of David, Josiah by name. On you he shall sacrifice the priests of the high places who burn incense on you, and they will burn men''s bones on you.''"'),
  ('91cd6526-7218-54be-a00d-64efa393f0d7', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 3, 3, 'He gave a sign the same day, saying, "This is the sign which Yahweh has spoken: Behold, the altar will be split apart, and the ashes that are on it will be poured out."'),
  ('b19f4ae2-d865-5cef-a19f-581be1219e73', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 4, 4, 'It happened, when the king heard the saying of the man of God, which he cried against the altar in Bethel, that Jeroboam put out his hand from the altar, saying, "Seize him!" His hand, which he put out against him, dried up, so that he could not draw it back again to himself.'),
  ('cfc78cfe-92fd-5662-ab8a-a495db4c5035', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 5, 5, 'The altar also was split apart, and the ashes poured out from the altar, according to the sign which the man of God had given by the word of Yahweh.'),
  ('dd44287f-3196-5b3c-afad-e1b807e9587f', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 6, 6, 'The king answered the man of God, "Now entreat the favor of Yahweh your God, and pray for me, that my hand may be restored me again." The man of God entreated Yahweh, and the king''s hand was restored him again, and became as it was before.'),
  ('50a5f478-c3d6-5563-ab66-4e1bcc986e6e', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 7, 7, 'The king said to the man of God, "Come home with me, and refresh yourself, and I will give you a reward."'),
  ('20ffc2d3-5bed-5faa-a078-278c1a3d016b', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 8, 8, 'The man of God said to the king, "Even if you gave me half of your house, I would not go in with you, neither would I eat bread nor drink water in this place;'),
  ('93a7a059-3658-566d-aeee-c206753c677a', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 9, 9, 'for so was it commanded me by the word of Yahweh, saying, ''You shall eat no bread, nor drink water, neither return by the way that you came.''"'),
  ('339fd02e-e78d-5cb6-ac80-4319baf43805', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 10, 10, 'So he went another way, and didn''t return by the way that he came to Bethel.'),
  ('bf24ccd4-a9dc-5bb6-a495-071c21f266f3', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 11, 11, 'Now there lived an old prophet in Bethel; and one of his sons came and told him all the works that the man of God had done that day in Bethel. They also told their father the words which he had spoken to the king.'),
  ('564398fc-c48d-5272-ae6d-c2386acb01a0', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 12, 12, 'Their father said to them, "Which way did he go?" Now his sons had seen which way the man of God went, who came from Judah.'),
  ('994f2f4b-9683-54fb-a198-3449d3c912ed', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 13, 13, 'He said to his sons, "Saddle the donkey for me." So they saddled the donkey for him; and he rode on it.'),
  ('78ecd687-d546-5106-a5d5-34d28399b061', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 14, 14, 'He went after the man of God, and found him sitting under an oak. He said to him, "Are you the man of God who came from Judah?" He said, "I am."'),
  ('9a60eed7-633c-51a7-a99c-c47dda0074a7', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 15, 15, 'Then he said to him, "Come home with me, and eat bread."'),
  ('1b099ad4-b091-505e-af2a-92e300d577a4', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 16, 16, 'He said, "I may not return with you, nor go in with you; neither will I eat bread nor drink water with you in this place.'),
  ('795715d4-578f-5f1f-a87f-e1bed9c358d1', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 17, 17, 'For it was said to me by the word of Yahweh, ''You shall eat no bread nor drink water there, nor turn again to go by the way that you came.''"'),
  ('66809c95-152d-54b2-a95c-a3a874f05fa1', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 18, 18, 'He said to him, "I also am a prophet as you are; and an angel spoke to me by the word of Yahweh, saying, ''Bring him back with you into your house, that he may eat bread and drink water.''" He lied to him.'),
  ('0197edd9-5a02-5982-aff1-4c9127da8a70', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 19, 19, 'So he went back with him, and ate bread in his house, and drank water.'),
  ('2e20e61b-a429-5ae9-acb3-1ef12054b22f', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 20, 20, 'It happened, as they sat at the table, that the word of Yahweh came to the prophet who brought him back;'),
  ('fcd75d5e-e55f-599c-a093-aeb16294b61e', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 21, 21, 'and he cried to the man of God who came from Judah, saying, "Thus says Yahweh, ''Because you have been disobedient to the mouth of Yahweh, and have not kept the commandment which Yahweh your God commanded you,'),
  ('975661f6-1e03-5685-a042-b5c774690378', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 22, 22, 'but came back, and have eaten bread and drunk water in the place of which he said to you, "Eat no bread, and drink no water;" your body shall not come to the tomb of your fathers.''"'),
  ('6dcf5ae8-da67-5c20-a58b-272c9862c91c', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 23, 23, 'It happened, after he had eaten bread, and after he had drunk, that he saddled the donkey for the prophet whom he had brought back.'),
  ('425b6ce7-d090-5c09-a8ac-af24e6e85615', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 24, 24, 'When he had gone, a lion met him by the way, and killed him. His body was cast in the way, and the donkey stood by it. The lion also stood by the body.'),
  ('b9b89c4d-ae1f-5fb8-a104-2e8c923309d4', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 25, 25, 'Behold, men passed by, and saw the body cast in the way, and the lion standing by the body; and they came and told it in the city where the old prophet lived.'),
  ('25f403b6-d882-5627-a819-ada6331a8cf3', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 26, 26, 'When the prophet who brought him back from the way heard of it, he said, "It is the man of God who was disobedient to the mouth of Yahweh. Therefore Yahweh has delivered him to the lion, which has mauled him and slain him, according to the word of Yahweh, which he spoke to him."'),
  ('ba67de1b-d37d-5d1e-a69d-3166495a49ec', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 27, 27, 'He spoke to his sons, saying, "Saddle the donkey for me." They saddled it.'),
  ('f82931d4-8b28-5bb8-aa01-13602b224cf2', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 28, 28, 'He went and found his body cast in the way, and the donkey and the lion standing by the body. The lion had not eaten the body, nor mauled the donkey.'),
  ('8e342403-055f-5ce6-aac9-ba1ec6fc47b7', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 29, 29, 'The prophet took up the body of the man of God, and laid it on the donkey, and brought it back. He came to the city of the old prophet to mourn, and to bury him.'),
  ('2f2535b7-98ee-5c04-a9e2-7700776c4822', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 30, 30, 'He laid his body in his own grave; and they mourned over him, saying, "Alas, my brother!"'),
  ('50ed590b-8b94-5dbe-a9b9-cdc8ee15a723', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 31, 31, 'It happened, after he had buried him, that he spoke to his sons, saying, "When I am dead, then bury me in the tomb in which the man of God is buried. Lay my bones beside his bones.'),
  ('98746eef-7855-5c92-afdf-db61d75c20a0', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 32, 32, 'For the saying which he cried by the word of Yahweh against the altar in Bethel, and against all the houses of the high places which are in the cities of Samaria, will surely happen."'),
  ('33734411-fd45-5980-a657-aa1bd71c48ea', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 33, 33, 'After this thing Jeroboam didn''t return from his evil way, but again made priests of the high places from among all the people. Whoever wanted to, he consecrated him, that there might be priests of the high places.'),
  ('5aaab1a4-308b-5a6f-ae28-bc86df0f879d', '5a841b94-7445-5cea-aca1-52bfcd2431f4', NULL, 34, 34, 'This thing became sin to the house of Jeroboam, even to cut it off, and to destroy it from off the surface of the earth.'),
  ('066af58f-812c-5938-a352-52bc97aea438', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 1, 1, 'At that time Abijah the son of Jeroboam fell sick.'),
  ('551850dc-5971-5182-a275-2997c66766cc', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 2, 2, 'Jeroboam said to his wife, "Please get up and disguise yourself, that you won''t be recognized as the wife of Jeroboam. Go to Shiloh. Behold, there is Ahijah the prophet, who spoke concerning me that I should be king over this people.'),
  ('e9d292fc-7aa8-56a1-ab65-ced75712c238', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 3, 3, 'Take with you ten loaves, and cakes, and a jar of honey, and go to him. He will tell you what will become of the child."'),
  ('9d66cf99-f02f-59c5-a11a-22c241327619', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 4, 4, 'Jeroboam''s wife did so, and arose, and went to Shiloh, and came to the house of Ahijah. Now Ahijah could not see; for his eyes were set by reason of his age.'),
  ('95510274-4c95-540c-a686-bf92a2bf903a', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 5, 5, 'Yahweh said to Ahijah, "Behold, the wife of Jeroboam comes to inquire of you concerning her son; for he is sick. Thus and thus you shall tell her; for it will be, when she comes in, that she will pretend to be another woman."'),
  ('ac8523a2-1277-5df9-a522-3b31d947abc2', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 6, 6, 'It was so, when Ahijah heard the sound of her feet, as she came in at the door, that he said, "Come in, you wife of Jeroboam! Why do you pretend to be another? For I am sent to you with heavy news.'),
  ('151b2366-f0c8-5327-a380-025377c76c02', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 7, 7, 'Go, tell Jeroboam, ''Thus says Yahweh, the God of Israel: "Because I exalted you from among the people, and made you prince over my people Israel,'),
  ('011685a7-eb93-5dee-ab03-fa5896f61e0b', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 8, 8, 'and tore the kingdom away from the house of David, and gave it you; and yet you have not been as my servant David, who kept my commandments, and who followed me with all his heart, to do that only which was right in my eyes,'),
  ('26d81417-db48-5688-a58e-2e41c4eb50ec', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 9, 9, 'but have done evil above all who were before you, and have gone and made you other gods, and molten images, to provoke me to anger, and have cast me behind your back:'),
  ('b160e981-c004-57db-a461-fbcd9cc2843a', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 10, 10, 'therefore, behold, I will bring evil on the house of Jeroboam, and will cut off from Jeroboam everyone who urinates on a wall, he who is shut up and he who is left at large in Israel, and will utterly sweep away the house of Jeroboam, as a man sweeps away dung, until it is all gone.'),
  ('af5bdfed-1f60-58bb-a15f-ada76f2c42fa', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 11, 11, 'He who dies of Jeroboam in the city shall the dogs eat; and he who dies in the field shall the birds of the sky eat: for Yahweh has spoken it."'''),
  ('e9dde360-3488-507f-a35a-8b498d723d83', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 12, 12, 'Arise therefore, and go to your house. When your feet enter into the city, the child shall die.'),
  ('248e931c-2b0a-5436-a371-8f968c588eca', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 13, 13, 'All Israel shall mourn for him, and bury him; for he only of Jeroboam shall come to the grave, because in him there is found some good thing toward Yahweh, the God of Israel, in the house of Jeroboam.'),
  ('998ffa4b-1e6e-5360-a7e7-6ff87ed94539', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 14, 14, 'Moreover Yahweh will raise him up a king over Israel, who shall cut off the house of Jeroboam. This is day! What? Even now.'),
  ('a9689388-8a3d-51f3-a62c-bfc9a2715bcf', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 15, 15, 'For Yahweh will strike Israel, as a reed is shaken in the water; and he will root up Israel out of this good land which he gave to their fathers, and will scatter them beyond the River, because they have made their Asherim, provoking Yahweh to anger.'),
  ('7ff6f7c5-01f3-58ce-a1db-1066780cbc40', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 16, 16, 'He will give Israel up because of the sins of Jeroboam, which he has sinned, and with which he has made Israel to sin."'),
  ('f245d77d-8864-5bdb-a149-1f2a10a2a3ee', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 17, 17, 'Jeroboam''s wife arose, and departed, and came to Tirzah. As she came to the threshold of the house, the child died.'),
  ('4d4b867a-2a9e-57b5-aa85-56200358707a', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 18, 18, 'All Israel buried him, and mourned for him, according to the word of Yahweh, which he spoke by his servant Ahijah the prophet.'),
  ('c0d60393-d4f3-5c09-a1b4-b3884320ab2b', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 19, 19, 'The rest of the acts of Jeroboam, how he warred, and how he reigned, behold, they are written in the book of the chronicles of the kings of Israel.'),
  ('5a75ce34-5967-5e21-ae78-082afdeb9b68', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 20, 20, 'The days which Jeroboam reigned were two and twenty years: and he slept with his fathers, and Nadab his son reigned in his place.'),
  ('dd771c9c-4b27-5312-a19e-c77e5003239b', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 21, 21, 'Rehoboam the son of Solomon reigned in Judah. Rehoboam was forty-one years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which Yahweh had chosen out of all the tribes of Israel, to put his name there: and his mother''s name was Naamah the Ammonitess.'),
  ('85ef454a-0c8f-5f3e-a872-89e1a3d655a0', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 22, 22, 'Judah did that which was evil in the sight of Yahweh, and they provoked him to jealousy with their sins which they committed, above all that their fathers had done.'),
  ('2918f7c3-9cfe-503e-adcb-1a63356b0f5d', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 23, 23, 'For they also built them high places, and pillars, and Asherim, on every high hill, and under every green tree;'),
  ('e44a7114-905e-593b-aeed-b0de6d1536c7', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 24, 24, 'and there were also sodomites in the land: they did according to all the abominations of the nations which Yahweh drove out before the children of Israel.'),
  ('2dc9445d-a99a-5475-ab1b-0da24f0f6aaf', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 25, 25, 'It happened in the fifth year of king Rehoboam, that Shishak king of Egypt came up against Jerusalem;'),
  ('ef7401ea-ff08-540a-ab0c-f440ed4f8f47', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 26, 26, 'and he took away the treasures of the house of Yahweh, and the treasures of the king''s house; he even took away all: and he took away all the shields of gold which Solomon had made.'),
  ('e216a04d-1903-5386-ac08-f2474653ac9a', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 27, 27, 'King Rehoboam made in their place shields of brass, and committed them to the hands of the captains of the guard, who kept the door of the king''s house.'),
  ('9edad6a3-c0ce-54ac-ab66-7c19641cae53', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 28, 28, 'It was so, that as often as the king went into the house of Yahweh, the guard bore them, and brought them back into the guard room.'),
  ('1a642317-c52a-5edb-a116-1900fc9d74f0', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 29, 29, 'Now the rest of the acts of Rehoboam, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('d2957b2d-a78e-5dae-a56b-a14d3d8b1af8', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 30, 30, 'There was war between Rehoboam and Jeroboam continually.'),
  ('495434e2-1818-557f-ab8d-fabf306001de', 'bc661782-50e7-501e-a2b5-1031496b4114', NULL, 31, 31, 'Rehoboam slept with his fathers, and was buried with his fathers in the city of David: and his mother''s name was Naamah the Ammonitess. Abijam his son reigned in his place.'),
  ('d58a50c1-6a19-57de-a232-b62e7b47297d', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 1, 1, 'Now in the eighteenth year of king Jeroboam the son of Nebat began Abijam to reign over Judah.'),
  ('325e00c5-ae4c-5343-a322-18ae038d3768', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 2, 2, 'Three years reigned he in Jerusalem: and his mother''s name was Maacah the daughter of Abishalom.'),
  ('e2a0fa4d-5be3-5dd1-a565-be8dc4b9f716', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 3, 3, 'He walked in all the sins of his father, which he had done before him; and his heart was not perfect with Yahweh his God, as the heart of David his father.'),
  ('4361c013-21f0-5483-a4b2-cdc5f1245ea2', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 4, 4, 'Nevertheless for David''s sake did Yahweh his God give him a lamp in Jerusalem, to set up his son after him, and to establish Jerusalem;'),
  ('6492917c-983e-5c13-a30b-06cb14960e25', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 5, 5, 'because David did that which was right in the eyes of Yahweh, and didn''t turn aside from anything that he commanded him all the days of his life, except only in the matter of Uriah the Hittite.'),
  ('64900083-1e2e-5a30-a543-51e4aea412ac', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 6, 6, 'Now there was war between Rehoboam and Jeroboam all the days of his life.'),
  ('97c06103-f2aa-5967-abdb-15b4065cc3fb', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 7, 7, 'The rest of the acts of Abijam, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah? There was war between Abijam and Jeroboam.'),
  ('1bfd75d9-856b-5ce5-a2eb-f7eb4f3e56e7', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 8, 8, 'Abijam slept with his fathers; and they buried him in the city of David: and Asa his son reigned in his place.'),
  ('2dc45ba2-0b8b-5bbe-a29e-d6844680048a', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 9, 9, 'In the twentieth year of Jeroboam king of Israel began Asa to reign over Judah.'),
  ('33bd20a2-24f7-5d9f-af9b-e6e1653efb7e', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 10, 10, 'Forty-one years reigned he in Jerusalem: and his mother''s name was Maacah the daughter of Abishalom.'),
  ('37649f86-ea85-57ea-ab6e-3ffdb6bba56c', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 11, 11, 'Asa did that which was right in the eyes of Yahweh, as did David his father.'),
  ('17fe050e-9cb4-59cc-aeb7-2a396d0f352d', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 12, 12, 'He put away the sodomites out of the land, and removed all the idols that his fathers had made.'),
  ('a7af6d8f-4391-5fef-af47-ebbaa73bfc86', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 13, 13, 'Also Maacah his mother he removed from being queen, because she had made an abominable image for an Asherah; and Asa cut down her image, and burnt it at the brook Kidron.'),
  ('6ff75d20-ebb2-5335-afff-3bdc48f5d2ba', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 14, 14, 'But the high places were not taken away: nevertheless the heart of Asa was perfect with Yahweh all his days.'),
  ('4ba33889-3b0d-535e-a2e6-af8c5faa3717', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 15, 15, 'He brought into the house of Yahweh the things that his father had dedicated, and the things that himself had dedicated, silver, and gold, and vessels.'),
  ('b3fcbc7c-2a49-5b5a-a29a-73e0f6a8afd2', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 16, 16, 'There was war between Asa and Baasha king of Israel all their days.'),
  ('ccdccfc0-3ef5-547a-af18-87c1123a3564', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 17, 17, 'Baasha king of Israel went up against Judah, and built Ramah, that he might not allow anyone to go out or come in to Asa king of Judah.'),
  ('1bcfbc1a-123a-5664-aca7-a4a3650bdb80', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 18, 18, 'Then Asa took all the silver and the gold that were left in the treasures of the house of Yahweh, and the treasures of the king''s house, and delivered them into the hand of his servants; and king Asa sent them to Ben Hadad, the son of Tabrimmon, the son of Hezion, king of Syria, who lived at Damascus, saying,'),
  ('7ad194ef-59b1-581b-a04f-c11ed1671008', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 19, 19, '"There is a treaty between me and you, between my father and your father. Behold, I have sent to you a present of silver and gold. Go, break your treaty with Baasha king of Israel, that he may depart from me."'),
  ('93d49e06-cccb-5158-a88f-bb9f8452cced', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 20, 20, 'Ben Hadad listened to king Asa, and sent the captains of his armies against the cities of Israel, and struck Ijon, and Dan, and Abel Beth Maacah, and all Chinneroth, with all the land of Naphtali.'),
  ('102dbea2-a72a-585d-a1d6-fbc9d6ca8129', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 21, 21, 'It happened, when Baasha heard of it, that he left off building Ramah, and lived in Tirzah.'),
  ('2bcf4803-7e0c-59e3-a00a-3cfab6346457', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 22, 22, 'Then king Asa made a proclamation to all Judah; none was exempted: and they carried away the stones of Ramah, and its timber, with which Baasha had built; and king Asa built therewith Geba of Benjamin, and Mizpah.'),
  ('587f9ed6-f919-5bd5-a3fd-592c9175e3c0', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 23, 23, 'Now the rest of all the acts of Asa, and all his might, and all that he did, and the cities which he built, aren''t they written in the book of the chronicles of the kings of Judah? But in the time of his old age he was diseased in his feet.'),
  ('a13189fe-36e9-5426-a574-e9524c72e4db', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 24, 24, 'Asa slept with his fathers, and was buried with his fathers in the city of David his father; and Jehoshaphat his son reigned in his place.'),
  ('0e5ff1c3-e95f-526a-aae5-6ab3670ccda3', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 25, 25, 'Nadab the son of Jeroboam began to reign over Israel in the second year of Asa king of Judah; and he reigned over Israel two years.'),
  ('2fc58ce1-e2df-5e7d-ac89-211301876de2', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 26, 26, 'He did that which was evil in the sight of Yahweh, and walked in the way of his father, and in his sin with which he made Israel to sin.'),
  ('abe1662d-1fad-5926-a137-c4ab862db527', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 27, 27, 'Baasha the son of Ahijah, of the house of Issachar, conspired against him; and Baasha struck him at Gibbethon, which belonged to the Philistines; for Nadab and all Israel were laying siege to Gibbethon.'),
  ('17c09214-67c7-5a2d-aec9-cd26e130915a', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 28, 28, 'Even in the third year of Asa king of Judah did Baasha kill him, and reigned in his place.'),
  ('bbf744e2-943a-5783-a44f-255263aa7ed6', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 29, 29, 'It happened that, as soon as he was king, he struck all the house of Jeroboam: he didn''t leave to Jeroboam any who breathed, until he had destroyed him; according to the saying of Yahweh, which he spoke by his servant Ahijah the Shilonite;'),
  ('b3d1913a-e67f-5c19-a9f2-3b6e66776ad4', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 30, 30, 'for the sins of Jeroboam which he sinned, and with which he made Israel to sin, because of his provocation with which he provoked Yahweh, the God of Israel, to anger.'),
  ('56daf3fe-d1f6-5949-a5c3-19a6c51360dc', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 31, 31, 'Now the rest of the acts of Nadab, and all that he did, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('0e19ca9f-95cb-55ed-a7b0-97ccf1274717', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 32, 32, 'There was war between Asa and Baasha king of Israel all their days.'),
  ('4c807c9b-b154-5653-af6a-cf5cb69524f5', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 33, 33, 'In the third year of Asa king of Judah began Baasha the son of Ahijah to reign over all Israel in Tirzah, [and reigned] twenty-four years.'),
  ('1d88b317-a3d6-5b6f-aa75-fe29bd6ad2d6', 'c5ccc806-e4fe-5bc0-aade-18f3bb53424c', NULL, 34, 34, 'He did that which was evil in the sight of Yahweh, and walked in the way of Jeroboam, and in his sin with which he made Israel to sin.'),
  ('5055095c-0310-52ac-a7c0-6047e009089e', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 1, 1, 'The word of Yahweh came to Jehu the son of Hanani against Baasha, saying,'),
  ('49d10279-89d9-50e0-a439-24f4618f4a85', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 2, 2, '"Because I exalted you out of the dust, and made you prince over my people Israel, and you have walked in the way of Jeroboam, and have made my people Israel to sin, to provoke me to anger with their sins;'),
  ('5c34e91a-e2e1-50c9-a333-5664845bbcd8', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 3, 3, 'behold, I will utterly sweep away Baasha and his house; and I will make your house like the house of Jeroboam the son of Nebat.'),
  ('5479f61f-f496-581b-aa2d-8b06999d7de2', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 4, 4, 'The dogs will eat Baasha''s descendants who die in the city; and he who dies of his in the field the birds of the sky will eat."'),
  ('636d92e9-5f44-548c-a86a-228414281e77', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 5, 5, 'Now the rest of the acts of Baasha, and what he did, and his might, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('94f279b7-b6b4-5616-adad-866bc4a0a5d2', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 6, 6, 'Baasha slept with his fathers, and was buried in Tirzah; and Elah his son reigned in his place.'),
  ('9c03b839-6ddf-516c-aaf7-92da1b777f08', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 7, 7, 'Moreover by the prophet Jehu the son of Hanani came the word of Yahweh against Baasha, and against his house, both because of all the evil that he did in the sight of Yahweh, to provoke him to anger with the work of his hands, in being like the house of Jeroboam, and because he struck him.'),
  ('e3741dba-7728-50b7-ab04-9094a3bbf9eb', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 8, 8, 'In the twenty-sixth year of Asa king of Judah began Elah the son of Baasha to reign over Israel in Tirzah, [and reigned] two years.'),
  ('aebb3d4c-c980-5eca-ad03-e5374abd78a7', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 9, 9, 'His servant Zimri, captain of half his chariots, conspired against him. Now he was in Tirzah, drinking himself drunk in the house of Arza, who was over the household in Tirzah:'),
  ('ec36c433-9882-5cf0-acdf-160c736ca61b', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 10, 10, 'and Zimri went in and struck him, and killed him, in the twenty-seventh year of Asa king of Judah, and reigned in his place.'),
  ('80b8eb0f-73dd-5aec-a870-866a31d4d528', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 11, 11, 'It happened, when he began to reign, as soon as he sat on his throne, that he struck all the house of Baasha: he didn''t leave him a single one who urinates on a wall, neither of his relatives, nor of his friends.'),
  ('893c4ecb-04d2-55bc-a0b9-0a34d15232c8', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 12, 12, 'Thus Zimri destroyed all the house of Baasha, according to the word of Yahweh, which he spoke against Baasha by Jehu the prophet,'),
  ('a7e97ab1-1dbb-52e9-a8a1-720221df6048', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 13, 13, 'for all the sins of Baasha, and the sins of Elah his son, which they sinned, and with which they made Israel to sin, to provoke Yahweh, the God of Israel, to anger with their vanities.'),
  ('77824b61-2bc1-5c72-a1c3-808a94faa01a', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 14, 14, 'Now the rest of the acts of Elah, and all that he did, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('75611d40-e648-5090-afba-e49f7934d9b6', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 15, 15, 'In the twenty-seventh year of Asa king of Judah did Zimri reign seven days in Tirzah. Now the people were encamped against Gibbethon, which belonged to the Philistines.'),
  ('b1e7546d-92ac-5fcb-a827-2473e4f565a8', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 16, 16, 'The people who were encamped heard say, Zimri has conspired, and has also struck the king: therefore all Israel made Omri, the captain of the army, king over Israel that day in the camp.'),
  ('5a40d2ec-b55d-5c7b-af78-a45a60dda98f', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 17, 17, 'Omri went up from Gibbethon, and all Israel with him, and they besieged Tirzah.'),
  ('e5038fcb-28b7-55fa-afa7-d5d074900900', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 18, 18, 'It happened, when Zimri saw that the city was taken, that he went into the castle of the king''s house, and burnt the king''s house over him with fire, and died,'),
  ('93fb4152-e307-5771-af81-74ebdf564e38', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 19, 19, 'for his sins which he sinned in doing that which was evil in the sight of Yahweh, in walking in the way of Jeroboam, and in his sin which he did, to make Israel to sin.'),
  ('16456f7f-6a17-5c84-af9f-5183bf0828af', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 20, 20, 'Now the rest of the acts of Zimri, and his treason that he did, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('629d5084-4a01-5d43-a3a5-cf55e247dd45', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 21, 21, 'Then were the people of Israel divided into two parts: half of the people followed Tibni the son of Ginath, to make him king; and half followed Omri.'),
  ('7138cf49-38b3-5230-a0d4-fb1f956c88c9', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 22, 22, 'But the people who followed Omri prevailed against the people who followed Tibni the son of Ginath: so Tibni died, and Omri reigned.'),
  ('359dc956-cfb2-564c-abbc-d9f69a9355f1', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 23, 23, 'In the thirty-first year of Asa king of Judah began Omri to reign over Israel, [and reigned] twelve years: six years reigned he in Tirzah.'),
  ('38b624ad-66bd-5058-ad4f-b5caa24f5781', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 24, 24, 'He bought the hill Samaria of Shemer for two talents of silver; and he built on the hill, and called the name of the city which he built, after the name of Shemer, the owner of the hill, Samaria.'),
  ('72b876fd-cfea-581f-aca9-bde1a85e990d', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 25, 25, 'Omri did that which was evil in the sight of Yahweh, and dealt wickedly above all who were before him.'),
  ('50760476-e7b0-5cc0-aa3b-40560c0c2c3d', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 26, 26, 'For he walked in all the way of Jeroboam the son of Nebat, and in his sins with which he made Israel to sin, to provoke Yahweh, the God of Israel, to anger with their vanities.'),
  ('0c781f67-a8ec-542c-a69c-dfb32fc1ef8f', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 27, 27, 'Now the rest of the acts of Omri which he did, and his might that he showed, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('2e980eea-d2f6-5e9b-abf0-ee02ccad36aa', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 28, 28, 'So Omri slept with his fathers, and was buried in Samaria; and Ahab his son reigned in his place.'),
  ('cab75e4a-5c6a-598d-a363-10540ddbb4d0', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 29, 29, 'In the thirty-eighth year of Asa king of Judah began Ahab the son of Omri to reign over Israel: and Ahab the son of Omri reigned over Israel in Samaria twenty-two years.'),
  ('41eb0d94-feac-5a85-acd7-4a2aac4a7bd1', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 30, 30, 'Ahab the son of Omri did that which was evil in the sight of Yahweh above all that were before him.'),
  ('f99e877c-d469-528a-a7d2-9c9ce2ab28d4', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 31, 31, 'It happened, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took as wife Jezebel the daughter of Ethbaal king of the Sidonians, and went and served Baal, and worshiped him.'),
  ('bcac3042-73e9-5a42-ad6c-900e3d218ca6', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 32, 32, 'He reared up an altar for Baal in the house of Baal, which he had built in Samaria.'),
  ('79305f03-1e2c-55f0-a6ba-4e37fadaceff', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 33, 33, 'Ahab made the Asherah; and Ahab did yet more to provoke Yahweh, the God of Israel, to anger than all the kings of Israel who were before him.'),
  ('a7fed356-3302-55f8-a89c-c259007814da', '80d2db9b-9727-5c15-a1a1-048be320d315', NULL, 34, 34, 'In his days did Hiel the Bethelite build Jericho: he laid its foundation with the loss of Abiram his firstborn, and set up its gates with the loss of his youngest son Segub, according to the word of Yahweh, which he spoke by Joshua the son of Nun.'),
  ('f307f9a2-2b40-5bea-a304-b00617bc6867', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 1, 1, 'Elijah the Tishbite, who was of the foreigners of Gilead, said to Ahab, "As Yahweh, the God of Israel, lives, before whom I stand, there shall not be dew nor rain these years, but according to my word."'),
  ('d7e51f39-4370-5c66-a29c-5e7238723fb1', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 2, 2, 'The word of Yahweh came to him, saying,'),
  ('bff2f156-1304-56d2-ad67-8c411586d1d4', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 3, 3, '"Go away from here, turn eastward, and hide yourself by the brook Cherith, that is before the Jordan.'),
  ('298698eb-b6ad-5852-a8be-4ebf4f8d3a95', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 4, 4, 'It shall be, that you shall drink of the brook. I have commanded the ravens to feed you there."'),
  ('12b93263-bb75-55d3-a1c2-e91b1bb73c65', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 5, 5, 'So he went and did according to the word of Yahweh; for he went and lived by the brook Cherith, that is before the Jordan.'),
  ('a2431f49-d01e-5f49-a20a-ab68915cebc0', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 6, 6, 'The ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook.'),
  ('3a0c8ba9-660e-5917-ac68-2c4a9be8bb10', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 7, 7, 'It happened after a while, that the brook dried up, because there was no rain in the land.'),
  ('f77f0da0-545a-5405-a267-2d3e9feff664', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 8, 8, 'The word of Yahweh came to him, saying,'),
  ('72098fa4-a2b1-59a3-a175-3d639a3be40f', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 9, 9, '"Arise, go to Zarephath, which belongs to Sidon, and stay there. Behold, I have commanded a widow there to sustain you."'),
  ('21a1f8ea-20de-5467-acaf-830a30ab5324', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 10, 10, 'So he arose and went to Zarephath; and when he came to the gate of the city, behold, a widow was there gathering sticks: and he called to her, and said, "Please get me a little water in a vessel, that I may drink."'),
  ('3630b3f1-952f-5c05-abd6-337585707013', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 11, 11, 'As she was going to get it, he called to her, and said, "Please bring me a morsel of bread in your hand."'),
  ('0b20223d-e22c-54b5-ab61-3be1c1e51152', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 12, 12, 'She said, "As Yahweh your God lives, I don''t have a cake, but a handful of meal in the jar, and a little oil in the jar. Behold, I am gathering two sticks, that I may go in and bake it for me and my son, that we may eat it, and die."'),
  ('11171291-84c9-5590-a0da-7d9caa200872', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 13, 13, 'Elijah said to her, "Don''t be afraid. Go and do as you have said; but make me of it a little cake first, and bring it out to me, and afterward make some for you and for your son.'),
  ('7bad29b7-a44c-5da5-a4ca-4d68e79c0334', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 14, 14, 'For thus says Yahweh, the God of Israel, ''The jar of meal shall not empty, neither shall the jar of oil fail, until the day that Yahweh sends rain on the earth.''"'),
  ('f33b0453-d918-583c-a590-dc92bfc41963', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 15, 15, 'She went and did according to the saying of Elijah: and she, and he, and her house, ate [many] days.'),
  ('b229ae1c-f205-50bd-ae47-a5b56b99027d', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 16, 16, 'The jar of meal didn''t empty, neither did the jar of oil fail, according to the word of Yahweh, which he spoke by Elijah.'),
  ('1b88fe5f-9738-5e70-abc7-7db5de082875', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 17, 17, 'It happened after these things, that the son of the woman, the mistress of the house, fell sick; and his sickness was so severe, that there was no breath left in him.'),
  ('69e3d7fe-a6bd-592c-a3e6-d366d7048600', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 18, 18, 'She said to Elijah, "What have I to do with you, you man of God? You have come to me to bring my sin to memory, and to kill my son!"'),
  ('0ae35eb8-42e4-5f86-a66b-66cb274e75b4', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 19, 19, 'He said to her, "Give me your son." He took him out of her bosom, and carried him up into the room where he stayed, and laid him on his own bed.'),
  ('d2622f3b-1bd5-5fa0-a65f-6120aa6f6198', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 20, 20, 'He cried to Yahweh, and said, "Yahweh my God, have you also brought evil on the widow with whom I stay, by killing her son?"'),
  ('503e4fff-cbd3-5746-a01d-90a45e7d5f63', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 21, 21, 'He stretched himself on the child three times, and cried to Yahweh, and said, "Yahweh my God, please let this child''s soul come into him again."'),
  ('60054db9-b482-5ec5-a568-b89902199027', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 22, 22, 'Yahweh listened to the voice of Elijah; and the soul of the child came into him again, and he revived.'),
  ('3215cbab-1c3e-5d40-adf8-18c92734f94a', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 23, 23, 'Elijah took the child, and brought him down out of the room into the house, and delivered him to his mother; and Elijah said, "Behold, your son lives."'),
  ('28c7ede1-5cdd-594a-afe3-e6ff5f2749c6', '0811ca86-a330-56e5-aef5-0a59543e3b2a', NULL, 24, 24, 'The woman said to Elijah, "Now I know that you are a man of God, and that the word of Yahweh in your mouth is truth."'),
  ('911238ae-8d43-5c66-a8d0-64a083a672a0', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 1, 1, 'It happened after many days, that the word of Yahweh came to Elijah, in the third year, saying, "Go, show yourself to Ahab; and I will send rain on the earth."'),
  ('7e2743b5-d125-50b0-ab3e-a4606f894074', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 2, 2, 'Elijah went to show himself to Ahab. The famine was severe in Samaria.'),
  ('79aa674a-de90-5eb6-abca-08976a502a3c', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 3, 3, 'Ahab called Obadiah, who was over the household. (Now Obadiah feared Yahweh greatly:'),
  ('216dc580-5868-5c39-acaa-9621d5567b65', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 4, 4, 'for it was so, when Jezebel cut off the prophets of Yahweh, that Obadiah took one hundred prophets, and hid them by fifty in a cave, and fed them with bread and water.)'),
  ('6bd4e329-5ee2-5626-a4af-a8bb3f40580f', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 5, 5, 'Ahab said to Obadiah, "Go through the land, to all the springs of water, and to all the brooks. Perhaps we may find grass and save the horses and mules alive, that we not lose all the animals."'),
  ('f7d873e5-7083-5674-ac11-25eb06d26127', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 6, 6, 'So they divided the land between them to pass throughout it: Ahab went one way by himself, and Obadiah went another way by himself.'),
  ('bd85616d-edc9-50cb-a98b-51c7c1c94196', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 7, 7, 'As Obadiah was in the way, behold, Elijah met him: and he recognized him, and fell on his face, and said, "Is it you, my lord Elijah?"'),
  ('672b4bff-82b1-5650-a59c-d70e3f4a0bbd', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 8, 8, 'He answered him, "It is I. Go, tell your lord, ''Behold, Elijah is here!''"'),
  ('5c14b094-0212-5095-aa7d-57730a22ad11', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 9, 9, 'He said, "Wherein have I sinned, that you would deliver your servant into the hand of Ahab, to kill me?'),
  ('2d533566-db6d-5494-ab76-44ccb31d44fe', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 10, 10, 'As Yahweh your God lives, there is no nation or kingdom, where my lord has not sent to seek you. When they said, ''He is not here,'' he took an oath of the kingdom and nation, that they didn''t find you.'),
  ('d50da77a-d036-554f-ac70-5ffd93c5871b', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 11, 11, 'Now you say, ''Go, tell your lord, "Behold, Elijah is here."'''),
  ('a5cc75d5-1738-5319-a2e1-234793108391', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 12, 12, 'It will happen, as soon as I am gone from you, that the Spirit of Yahweh will carry you I don''t know where; and so when I come and tell Ahab, and he can''t find you, he will kill me. But I, your servant, have feared Yahweh from my youth.'),
  ('3ae90cce-fc9a-53be-ad0f-0b101ae13365', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 13, 13, 'Wasn''t it told my lord what I did when Jezebel killed the prophets of Yahweh, how I hid one hundred men of Yahweh''s prophets with fifty to a cave, and fed them with bread and water?'),
  ('0c60ba2a-3462-57c7-ad75-2976d83752d1', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 14, 14, 'Now you say, ''Go, tell your lord, "Behold, Elijah is here;"'' and he will kill me."'),
  ('0c189c83-4bf0-5c8e-a909-7e0b0a9013af', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 15, 15, 'Elijah said, "As Yahweh of Armies lives, before whom I stand, I will surely show myself to him today."'),
  ('f62e7285-3371-5bd3-af42-cd2783de92c3', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 16, 16, 'So Obadiah went to meet Ahab, and told him; and Ahab went to meet Elijah.'),
  ('a118510c-6e97-5ea1-a9ea-cd704782f2e5', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 17, 17, 'It happened, when Ahab saw Elijah, that Ahab said to him, "Is that you, you troubler of Israel?"'),
  ('1c126248-17b0-5f82-a70e-4466e4bb2b71', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 18, 18, 'He answered, "I have not troubled Israel; but you, and your father''s house, in that you have forsaken the commandments of Yahweh, and you have followed the Baals.'),
  ('d18aed25-4fa5-5407-ae15-208ea9fab366', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 19, 19, 'Now therefore send, and gather to me all Israel to Mount Carmel, and four hundred fifty of the prophets of Baal, and four hundred of the prophets of the Asherah, who eat at Jezebel''s table."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('d34975b2-99a4-52cf-a718-f75a7a173026', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 20, 20, 'So Ahab sent to all the children of Israel, and gathered the prophets together to Mount Carmel.'),
  ('fd9e1e4a-7274-5b07-aa8e-84fd1c595f8c', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 21, 21, 'Elijah came near to all the people, and said, "How long will you waver between the two sides? If Yahweh is God, follow him; but if Baal, then follow him." The people answered him not a word.'),
  ('130face1-ff7e-5ef7-a29d-c957d83e0b0b', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 22, 22, 'Then Elijah said to the people, "I, even I only, am left a prophet of Yahweh; but Baal''s prophets are four hundred fifty men.'),
  ('63e7be8d-360b-5401-afa0-073e26a787dc', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 23, 23, 'Let them therefore give us two bulls; and let them choose one bull for themselves, and cut it in pieces, and lay it on the wood, and put no fire under; and I will dress the other bull, and lay it on the wood, and put no fire under it.'),
  ('7ff9e5fe-6ace-55ee-a137-569bb17f74a4', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 24, 24, 'You call on the name of your god, and I will call on the name of Yahweh. The God who answers by fire, let him be God." All the people answered, "It is well said."'),
  ('e59b08e4-7095-599d-ad7f-9f1a6ae7c6cc', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 25, 25, 'Elijah said to the prophets of Baal, "Choose one bull for yourselves, and dress it first; for you are many; and call on the name of your god, but put no fire under it."'),
  ('d1fcad77-bf74-52ec-aef9-dc5fa546827b', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 26, 26, 'They took the bull which was given them, and they dressed it, and called on the name of Baal from morning even until noon, saying, Baal, hear us. But there was no voice, nor any who answered. They leaped about the altar which was made.'),
  ('2c747e88-3e13-5ff4-a808-5ac9dd702675', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 27, 27, 'It happened at noon, that Elijah mocked them, and said, "Cry aloud; for he is a god. Either he is musing, or he has gone aside, or he is on a journey, or perhaps he sleeps and must be awakened."'),
  ('4a0839fb-a0e1-55d2-a9a6-29fbfca166f5', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 28, 28, 'They cried aloud, and cut themselves in their way with knives and lances, until the blood gushed out on them.'),
  ('600b9a17-3abd-5c45-a247-0ceacacd2f11', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 29, 29, 'It was so, when midday was past, that they prophesied until the time of the offering of the offering; but there was neither voice, nor any to answer, nor any who regarded.'),
  ('5f56fcf3-7cdf-5896-ad4c-edc01fa7e303', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 30, 30, 'Elijah said to all the people, "Come near to me;" and all the people came near to him. He repaired the altar of Yahweh that was thrown down.'),
  ('3b4901e9-c6fb-52ce-a50b-b5ae433a6338', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 31, 31, 'Elijah took twelve stones, according to the number of the tribes of the sons of Jacob, to whom the word of Yahweh came, saying, "Israel shall be your name."'),
  ('ed444639-0137-577a-a2f3-18a1dc8a0825', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 32, 32, 'With the stones he built an altar in the name of Yahweh. He made a trench around the altar, large enough to contain two measures of seed.'),
  ('5da6f109-2620-520c-a589-63ea43cf85e7', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 33, 33, 'He put the wood in order, and cut the bull in pieces, and laid it on the wood. He said, "Fill four jars with water, and pour it on the burnt offering, and on the wood."'),
  ('d22d4aa5-493b-5c1a-a0c7-d026e583a5eb', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 34, 34, 'He said, "Do it a second time;" and they did it the second time. He said, "Do it a third time;" and they did it the third time.'),
  ('707f45e2-386a-59e8-a1b9-bd74028fc375', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 35, 35, 'The water ran around the altar; and he also filled the trench with water.'),
  ('a1bada92-9346-5713-a914-273f1993ca87', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 36, 36, 'It happened at the time of the offering of the offering, that Elijah the prophet came near, and said, "Yahweh, the God of Abraham, of Isaac, and of Israel, let it be known this day that you are God in Israel, and that I am your servant, and that I have done all these things at your word.'),
  ('95c2cec2-c674-542b-a10a-dd1bd838d3be', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 37, 37, 'Hear me, Yahweh, hear me, that this people may know that you, Yahweh, are God, and that you have turned their heart back again."'),
  ('dae791bc-684a-5fe4-adfc-8669336b3eb6', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 38, 38, 'Then the fire of Yahweh fell, and consumed the burnt offering, and the wood, and the stones, and the dust, and licked up the water that was in the trench.'),
  ('df23ba1f-e86f-50e8-a30e-a0b93a8477f9', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 39, 39, 'When all the people saw it, they fell on their faces. They said, "Yahweh, he is God! Yahweh, he is God!"'),
  ('6b8bab05-2b7e-56d3-a72e-3a1c17204874', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 40, 40, 'Elijah said to them, "Seize the prophets of Baal! Don''t let one of them escape!" They seized them. Elijah brought them down to the brook Kishon, and killed them there.'),
  ('a21466b7-3a41-5554-a090-757645e5df2c', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 41, 41, 'Elijah said to Ahab, "Get up, eat and drink; for there is the sound of abundance of rain."'),
  ('da79780e-87b4-54a4-a873-86f5f1f2baa9', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 42, 42, 'So Ahab went up to eat and to drink. Elijah went up to the top of Carmel; and he bowed himself down on the earth, and put his face between his knees.'),
  ('8ba7a45d-d2de-5b4f-a6eb-56a1797e92c4', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 43, 43, 'He said to his servant, "Go up now, look toward the sea." He went up, and looked, and said, "There is nothing." He said, "Go again" seven times.'),
  ('92629951-5703-5d0c-a655-0e93194d3930', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 44, 44, 'It happened at the seventh time, that he said, "Behold, a small cloud, like a man''s hand, is rising out of the sea." He said, "Go up, tell Ahab, ''Get ready and go down, so that the rain doesn''t stop you.''"'),
  ('4a424baf-a452-5052-ab06-1d765cf4a77d', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 45, 45, 'It happened in a little while, that the sky grew black with clouds and wind, and there was a great rain. Ahab rode, and went to Jezreel.'),
  ('e10fd70d-04df-5778-a15d-853e7fe52aac', '7e4c848e-9737-51a9-a5df-05ae35d54f81', NULL, 46, 46, 'The hand of Yahweh was on Elijah; and he tucked his cloak into his belt and ran before Ahab to the entrance of Jezreel.'),
  ('8a1c32f8-3013-5b1c-ac81-5d7778166815', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 1, 1, 'Ahab told Jezebel all that Elijah had done, and how he had killed all the prophets with the sword.'),
  ('b72c2a8e-faf2-55e7-ab0a-e062232ba070', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 2, 2, 'Then Jezebel sent a messenger to Elijah, saying, "So let the gods do to me, and more also, if I don''t make your life as the life of one of them by tomorrow about this time!"'),
  ('ffa03aad-a417-52bc-a7ac-5565ff920eca', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 3, 3, 'When he saw that, he arose, and went for his life, and came to Beersheba, which belongs to Judah, and left his servant there.'),
  ('dbd0fccf-08d0-5dbf-a73a-b007dce0a8d0', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 4, 4, 'But he himself went a day''s journey into the wilderness, and came and sat down under a juniper tree: and he requested for himself that he might die, and said, "It is enough. Now, O Yahweh, take away my life; for I am not better than my fathers."'),
  ('dd2f0329-1ec1-553a-ae58-e1738fb16e01', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 5, 5, 'He lay down and slept under a juniper tree; and behold, an angel touched him, and said to him, "Arise and eat!"'),
  ('b08c0c69-2c17-5b40-a724-4f8e665de78b', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 6, 6, 'He looked, and behold, there was at his head a cake baked on the coals, and a jar of water. He ate and drank, and laid down again.'),
  ('59874445-673c-595d-acfe-ba03caad1b74', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 7, 7, 'The angel of Yahweh came again the second time, and touched him, and said, "Arise and eat, because the journey is too great for you."'),
  ('78056a6c-6674-5559-a2aa-01fc3c9272b7', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 8, 8, 'He arose, and ate and drank, and went in the strength of that food forty days and forty nights to Horeb the Mount of God.'),
  ('8a33825e-0fad-5207-ae03-44258ea80c4e', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 9, 9, 'He came there to a cave, and lodged there; and behold, the word of Yahweh came to him, and he said to him, "What are you doing here, Elijah?"'),
  ('e85d655d-ff01-5a45-a2b4-42eb6dd76bdc', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 10, 10, 'He said, "I have been very jealous for Yahweh, the God of Armies; for the children of Israel have forsaken your covenant, thrown down your altars, and slain your prophets with the sword. I, even I only, am left; and they seek my life, to take it away."'),
  ('7661c2e5-62c8-5de0-a932-ce6906587164', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 11, 11, 'He said, "Go out, and stand on the mountain before Yahweh." Behold, Yahweh passed by, and a great and strong wind tore the mountains, and broke in pieces the rocks before Yahweh; but Yahweh was not in the wind. After the wind an earthquake; but Yahweh was not in the earthquake.'),
  ('b2be3fdf-4ed5-5ab5-a153-ad5b32bf4216', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 12, 12, 'After the earthquake a fire passed; but Yahweh was not in the fire: and after the fire a still small voice.'),
  ('9b66c417-48fa-5edf-ab8b-93cc0f1f4e76', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 13, 13, 'It was so, when Elijah heard it, that he wrapped his face in his mantle, and went out, and stood in the entrance of the cave. Behold, a voice came to him, and said, "What are you doing here, Elijah?"'),
  ('dcd0ed86-1f57-5b86-a989-fd306e28e3c6', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 14, 14, 'He said, "I have been very jealous for Yahweh, the God of Armies; for the children of Israel have forsaken your covenant, thrown down your altars, and slain your prophets with the sword. I, even I only, am left; and they seek my life, to take it away."'),
  ('9fa439da-24a3-5e25-a904-aa57e5223be4', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 15, 15, 'Yahweh said to him, "Go, return on your way to the wilderness of Damascus. When you arrive, you shall anoint Hazael to be king over Syria.'),
  ('8f4bbf2c-0149-50f9-a9f8-c22ad7bf478b', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 16, 16, 'You shall anoint Jehu the son of Nimshi to be king over Israel; and you shall anoint Elisha the son of Shaphat of Abel Meholah to be prophet in your place.'),
  ('41305512-c954-5365-a3db-9cd6ef24cb22', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 17, 17, 'It shall happen, that he who escapes from the sword of Hazael, Jehu will kill; and he who escapes from the sword of Jehu, Elisha will kill.'),
  ('5d05bd0b-8511-5ccb-afa2-7054dda38b3f', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 18, 18, 'Yet will I leave seven thousand in Israel, all the knees which have not bowed to Baal, and every mouth which has not kissed him."'),
  ('bf450d6c-f93e-5197-ad12-0243e15160dc', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 19, 19, 'So he departed there, and found Elisha the son of Shaphat, who was plowing, with twelve yoke [of oxen] before him, and he with the twelfth: and Elijah passed over to him, and cast his mantle on him.'),
  ('90e1ec46-d05d-5155-a3db-b91ff33a3aa2', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 20, 20, 'He left the oxen, and ran after Elijah, and said, "Let me please kiss my father and my mother, and then I will follow you." He said to him, "Go back again; for what have I done to you?"'),
  ('8de4acf6-eaf0-51e7-a814-c1a1e4a4b81d', '27f7f99c-2074-5264-aac5-0720509e503d', NULL, 21, 21, 'He returned from following him, and took the yoke of oxen, and killed them, and boiled their flesh with the instruments of the oxen, and gave to the people, and they ate. Then he arose, and went after Elijah, and served him.'),
  ('1f9a8ec4-d75d-5163-ae12-cc9018597033', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 1, 1, 'Ben Hadad the king of Syria gathered all his army together; and there were thirty-two kings with him, and horses and chariots: and he went up and besieged Samaria, and fought against it.'),
  ('ceb3ad28-f351-5ec0-ae6f-f045386593f9', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 2, 2, 'He sent messengers to Ahab king of Israel, into the city, and said to him, "Thus says Ben Hadad,'),
  ('baa3ceab-9173-5da2-adc5-a764e2ce6f22', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 3, 3, '''Your silver and your gold is mine. Your wives also and your children, even the best, are mine.''"'),
  ('aabcb91d-45eb-5ec8-a6d4-ff6d16fdaa84', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 4, 4, 'The king of Israel answered, "It is according to your saying, my lord, O king. I am yours, and all that I have."'),
  ('c86cfd51-d1bf-5e4a-a41c-9e45bc97d03b', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 5, 5, 'The messengers came again, and said, "Ben Hadad says, ''I sent indeed to you, saying, "You shall deliver me your silver, and your gold, and your wives, and your children;'),
  ('fcb8ddff-3a93-5397-a360-b0983a68bb4a', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 6, 6, 'but I will send my servants to you tomorrow about this time, and they shall search your house, and the houses of your servants; and it shall be, that whatever is pleasant in your eyes, they shall put it in their hand, and take it away."''"'),
  ('e005d150-5a4a-5159-a82c-1f6e34455442', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 7, 7, 'Then the king of Israel called all the elders of the land, and said, "Please notice how this man seeks mischief; for he sent to me for my wives, and for my children, and for my silver, and for my gold; and I didn''t deny him."'),
  ('a94f182c-0687-51c3-a91d-1a47aed81d6d', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 8, 8, 'All the elders and all the people said to him, "Don''t listen, neither consent."'),
  ('5468b3bc-31f1-5f9c-a319-e9f1252a86fb', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 9, 9, 'Therefore he said to the messengers of Ben Hadad, "Tell my lord the king, ''All that you sent for to your servant at the first I will do; but this thing I cannot do.''" The messengers departed, and brought him back the message.'),
  ('a8d28ce7-a03f-567f-a32b-60b4d44003c8', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 10, 10, 'Ben Hadad sent to him, and said, "The gods do so to me, and more also, if the dust of Samaria shall suffice for handfuls for all the people who follow me."'),
  ('9a1953ea-8313-57f6-a245-47648ef14800', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 11, 11, 'The king of Israel answered, "Tell him, ''Don''t let him who puts on his armor brag like he who takes it off.''"'),
  ('cecf81a5-b7c6-5299-a8a2-b9001c94db5c', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 12, 12, 'It happened, when Ben Hadad heard this message, as he was drinking, he and the kings, in the pavilions, that he said to his servants, "Prepare to attack!" They prepared to attack the city.'),
  ('995f41a6-af82-5f23-a2e8-9d8d908a138a', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 13, 13, 'Behold, a prophet came near to Ahab king of Israel, and said, "Thus says Yahweh, ''Have you seen all this great multitude? Behold, I will deliver it into your hand this day; and you shall know that I am Yahweh.''"'),
  ('5c602a42-5fa8-59f2-a23b-28e640350f05', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 14, 14, 'Ahab said, "By whom?" He said, "Thus says Yahweh, ''By the young men of the princes of the provinces.''" Then he said, "Who shall begin the battle?" He answered, "You."'),
  ('6bc4353e-1c2a-5968-a908-4ee9d56ea8b9', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 15, 15, 'Then he mustered the young men of the princes of the provinces, and they were two hundred and thirty-two. After them, he mustered all the people, even all the children of Israel, being seven thousand.'),
  ('a2578d2d-a970-5f42-a196-b57e90db72c5', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 16, 16, 'They went out at noon. But Ben Hadad was drinking himself drunk in the pavilions, he and the kings, the thirty-two kings who helped him.'),
  ('806683e4-580f-571a-aae5-5f65220e80f6', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 17, 17, 'The young men of the princes of the provinces went out first; and Ben Hadad sent out, and they told him, saying, "Men are coming out from Samaria."'),
  ('9d4d781c-18c1-54d7-ae1d-9f5b9d8563fd', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 18, 18, 'He said, "If they have come out for peace, take them alive; or if they have come out for war, take them alive."'),
  ('e52c6d7e-21ff-591b-a704-368cf2ea717f', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 19, 19, 'So these went out of the city, the young men of the princes of the provinces, and the army which followed them.'),
  ('8dfc0dbb-f546-5d29-a081-dfbe6aa6e628', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 20, 20, 'They each killed his man. The Syrians fled, and Israel pursued them. Ben Hadad the king of Syria escaped on a horse with horsemen.'),
  ('89e3785c-62de-5497-add0-788b99ddf35d', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 21, 21, 'The king of Israel went out, and struck the horses and chariots, and killed the Syrians with a great slaughter.'),
  ('5bd2f577-d237-5a54-a4e0-eed3e7e9f277', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 22, 22, 'The prophet came near to the king of Israel, and said to him, "Go, strengthen yourself, and mark, and see what you do; for at the return of the year the king of Syria will come up against you."'),
  ('74383cd0-af67-5af5-a964-4e356e8fd18b', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 23, 23, 'The servants of the king of Syria said to him, "Their god is a god of the hills; therefore they were stronger than we. But let us fight against them in the plain, and surely we shall be stronger than they.'),
  ('9a158106-32cc-57c6-a1e7-f598cbd6df31', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 24, 24, 'Do this thing: take the kings away, every man out of his place, and put captains in their place.'),
  ('615f4e3b-9302-5916-a4ca-2fbb9c2d7eab', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 25, 25, 'Muster an army, like the army that you have lost, horse for horse, and chariot for chariot. We will fight against them in the plain, and surely we will be stronger than them." He listened to their voice, and did so.'),
  ('995b9d23-b7b2-5cc6-a330-1d77668e10a7', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 26, 26, 'It happened at the return of the year, that Ben Hadad mustered the Syrians, and went up to Aphek, to fight against Israel.'),
  ('c5b98425-f037-58fa-a336-87b68eee36b3', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 27, 27, 'The children of Israel were mustered, and were provisioned, and went against them. The children of Israel encamped before them like two little flocks of young goats; but the Syrians filled the country.'),
  ('abdafefb-cf64-566b-ab08-b1437cb19ef8', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 28, 28, 'A man of God came near and spoke to the king of Israel, and said, "Thus says Yahweh, ''Because the Syrians have said, "Yahweh is a god of the hills, but he is not a god of the valleys;" therefore I will deliver all this great multitude into your hand, and you shall know that I am Yahweh.''"'),
  ('5d380bde-a8f2-5232-a184-ce60dc720448', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 29, 29, 'They encamped one over against the other seven days. So it was, that in the seventh day the battle was joined; and the children of Israel killed one hundred thousand footmen of the Syrians in one day.'),
  ('cdab1683-f7d9-5808-a685-ea6657504b9a', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 30, 30, 'But the rest fled to Aphek, into the city; and the wall fell on twenty-seven thousand men who were left. Ben Hadad fled, and came into the city, into an inner room.'),
  ('9de3a91a-7167-59fb-a113-8e21fb0f2904', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 31, 31, 'His servants said to him, "See now, we have heard that the kings of the house of Israel are merciful kings. Please let us put sackcloth on our bodies, and ropes on our heads, and go out to the king of Israel. Maybe he will save your life."'),
  ('1e3d513b-f068-5ac4-ade4-19231b0341c8', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 32, 32, 'So they put sackcloth on their bodies and ropes on their heads, and came to the king of Israel, and said, "Your servant Ben Hadad says, ''Please let me live.''" He said, "Is he still alive? He is my brother."'),
  ('7645e5e5-19d2-5bb2-afd2-6bd48751af43', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 33, 33, 'Now the men observed diligently, and hurried to take this phrase; and they said, "Your brother Ben Hadad." Then he said, "Go, bring him." Then Ben Hadad came out to him; and he caused him to come up into the chariot.'),
  ('2ea85645-5648-5a58-a6a6-61505c744596', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 34, 34, 'Ben Hadad said to him, "The cities which my father took from your father I will restore. You shall make streets for yourself in Damascus, as my father made in Samaria." "I," said Ahab, "will let you go with this covenant." So he made a covenant with him, and let him go.'),
  ('5a91a6cf-f002-5d3f-ac69-797308f4d5a2', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 35, 35, 'A certain man of the sons of the prophets said to his fellow by the word of Yahweh, "Please strike me!" The man refused to strike him.'),
  ('704dea00-e180-5a57-a39c-042472a2dd65', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 36, 36, 'Then he said to him, "Because you have not obeyed the voice of Yahweh, behold, as soon as you are departed from me, a lion shall kill you." As soon as he was departed from him, a lion found him, and killed him.'),
  ('a25ae8fd-5ac8-5ee0-a39b-ae9435648b3f', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 37, 37, 'Then he found another man, and said, "Please strike me." The man struck him, smiting and wounding him.'),
  ('371b4d30-b931-5856-afa3-452132dd6ab0', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 38, 38, 'So the prophet departed, and waited for the king by the way, and disguised himself with his headband over his eyes.'),
  ('cdbdd15e-7426-5d3d-ab97-846b60d0847d', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 39, 39, 'As the king passed by, he cried to the king; and he said, "Your servant went out into the midst of the battle; and behold, a man turned aside, and brought a man to me, and said, ''Guard this man! If by any means he be missing, then your life shall be for his life, or else you shall pay a talent of silver.'''),
  ('c118c6eb-3652-5950-a1d8-64be6a88a691', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 40, 40, 'As your servant was busy here and there, he was gone." The king of Israel said to him, "So your judgment shall be; yourself have decided it."'),
  ('732e5ef9-a1f5-5456-a035-9a770ed67e5b', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 41, 41, 'He hurried, and took the headband away from his eyes; and the king of Israel recognized that he was of the prophets.'),
  ('53722a15-d311-5e30-ac8b-11d8d30968cb', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 42, 42, 'He said to him, "Thus says Yahweh, ''Because you have let go out of your hand the man whom I had devoted to destruction, therefore your life shall go for his life, and your people for his people.''"'),
  ('f6006e2b-a8b2-51d7-a7e1-56ca1caa822b', '3baf8549-c12e-5793-a0da-1e03f3137e87', NULL, 43, 43, 'The king of Israel went to his house sullen and angry, and came to Samaria.'),
  ('b6f35461-2d1f-543f-a449-0b04a10ff84c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 1, 1, 'It happened after these things, that Naboth the Jezreelite had a vineyard, which was in Jezreel, hard by the palace of Ahab king of Samaria.'),
  ('95ae2830-a72d-56a1-a384-dba144b06cda', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 2, 2, 'Ahab spoke to Naboth, saying, "Give me your vineyard, that I may have it for a garden of herbs, because it is near to my house; and I will give you for it a better vineyard than it. Or, if it seems good to you, I will give you its worth in money."'),
  ('904e1e58-c068-510a-af6e-198f6824eb49', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 3, 3, 'Naboth said to Ahab, "May Yahweh forbid me, that I should give the inheritance of my fathers to you!"'),
  ('9c84edb2-7a94-55bf-a2f2-3c43b5917b3c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 4, 4, 'Ahab came into his house sullen and angry because of the word which Naboth the Jezreelite had spoken to him; for he had said, "I will not give you the inheritance of my fathers." He laid himself down on his bed, and turned away his face, and would eat no bread.'),
  ('f2cb144d-797f-563a-ac81-cc77d6594056', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 5, 5, 'But Jezebel his wife came to him, and said to him, "Why is your spirit so sad, that you eat no bread?"'),
  ('d5b1d113-2563-5edb-a5bc-e254e43f7d61', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 6, 6, 'He said to her, "Because I spoke to Naboth the Jezreelite, and said to him, ''Give me your vineyard for money; or else, if it pleases you, I will give you another vineyard for it.'' He answered, ''I will not give you my vineyard.''"'),
  ('4cebb8b7-5005-5daa-af1c-679791f3e66b', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 7, 7, 'Jezebel his wife said to him, "Do you now govern the kingdom of Israel? Arise, and eat bread, and let your heart be merry. I will give you the vineyard of Naboth the Jezreelite."'),
  ('331aea76-14c5-55f6-a5e8-6416650bc39c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 8, 8, 'So she wrote letters in Ahab''s name, and sealed them with his seal, and sent the letters to the elders and to the nobles who were in his city, who lived with Naboth.'),
  ('b3417ab5-9343-598d-a83c-d89d73854d7c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 9, 9, 'She wrote in the letters, saying, "Proclaim a fast, and set Naboth on high among the people.'),
  ('10c9ecb3-0de4-5127-afcb-95d336869c6f', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 10, 10, 'Set two men, base fellows, before him, and let them testify against him, saying, ''You cursed God and the king!'' Then carry him out, and stone him to death."'),
  ('f0197c3d-064a-5050-a9af-b597f6759a0d', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 11, 11, 'The men of his city, even the elders and the nobles who lived in his city, did as Jezebel had sent to them, according as it was written in the letters which she had sent to them.'),
  ('c05add7e-32ce-5324-a238-43500861271c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 12, 12, 'They proclaimed a fast, and set Naboth on high among the people.'),
  ('8a94d653-f9c3-51c3-a15a-7f7287a8ee64', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 13, 13, 'The two men, the base fellows, came in and sat before him. The base fellows testified against him, even against Naboth, in the presence of the people, saying, "Naboth cursed God and the king!" Then they carried him out of the city, and stoned him to death with stones.'),
  ('c8d67f27-ba4f-5ccb-a60e-468a81bb9de6', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 14, 14, 'Then they sent to Jezebel, saying, "Naboth has been stoned, and is dead."'),
  ('1dd12d85-7601-50a5-a0b7-ae54d4bf02a7', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 15, 15, 'It happened, when Jezebel heard that Naboth was stoned, and was dead, that Jezebel said to Ahab, "Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money; for Naboth is not alive, but dead."'),
  ('dbd7bb11-8d1c-5a45-a212-bf0370eb7753', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 16, 16, 'It happened, when Ahab heard that Naboth was dead, that Ahab rose up to go down to the vineyard of Naboth the Jezreelite, to take possession of it.'),
  ('301329fa-28c3-5d82-ade4-429408d22d32', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 17, 17, 'The word of Yahweh came to Elijah the Tishbite, saying,'),
  ('2da99afb-6695-5925-af9b-1f86e8927951', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 18, 18, '"Arise, go down to meet Ahab king of Israel, who dwells in Samaria. Behold, he is in the vineyard of Naboth, where he has gone down to take possession of it.'),
  ('2afb5f22-87a7-5844-a92a-686bfd1e890c', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 19, 19, 'You shall speak to him, saying, ''Thus says Yahweh, "Have you killed and also taken possession?"'' You shall speak to him, saying, ''Thus says Yahweh, "In the place where dogs licked the blood of Naboth, dogs will lick your blood, even yours."''"'),
  ('7f48ef2c-1834-50d0-a529-aae7e97a1e83', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 20, 20, 'Ahab said to Elijah, "Have you found me, my enemy?" He answered, "I have found you, because you have sold yourself to do that which is evil in the sight of Yahweh.'),
  ('7330e389-64ad-558e-af4d-f6e98226e409', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 21, 21, 'Behold, I will bring evil on you, and will utterly sweep you away and will cut off from Ahab everyone who urinates against a wall, and him who is shut up and him who is left at large in Israel.'),
  ('c1112480-877e-5d77-aefb-b295177eaf91', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 22, 22, 'I will make your house like the house of Jeroboam the son of Nebat, and like the house of Baasha the son of Ahijah for the provocation with which you have provoked me to anger, and have made Israel to sin."'),
  ('e20efc2d-8659-5498-ac81-7447533c853b', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 23, 23, 'Yahweh also spoke of Jezebel, saying, "The dogs shall eat Jezebel by the rampart of Jezreel.'),
  ('30ae32bc-c221-5235-a5db-c56c1a92aebc', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 24, 24, 'The dogs will eat he who dies of Ahab in the city; and the birds of the sky will eat he who dies in the field."'),
  ('d3279842-5479-5f82-a42a-04e3e8866d21', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 25, 25, 'But there was none like Ahab, who sold himself to do that which was evil in the sight of Yahweh, whom Jezebel his wife stirred up.'),
  ('0f44a0fe-f61d-5ef3-a293-dc74e7643cff', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 26, 26, 'He did very abominably in following idols, according to all that the Amorites did, whom Yahweh cast out before the children of Israel.'),
  ('2dc406a4-3f21-597c-a3f2-f1615b0e4be6', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 27, 27, 'It happened, when Ahab heard those words, that he tore his clothes, and put sackcloth on his flesh, and fasted, and lay in sackcloth, and went softly.'),
  ('2ef6ac0d-8986-5113-a779-1b728af79ee3', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 28, 28, 'The word of Yahweh came to Elijah the Tishbite, saying,'),
  ('9e69cec5-fa68-5a2b-ab75-6e8e0a43d046', '0ca57a30-e43a-5b04-a1de-ef4a5ed0e4cd', NULL, 29, 29, '"See how Ahab humbles himself before me? Because he humbles himself before me, I will not bring the evil in his days; but in his son''s days will I bring the evil on his house."'),
  ('038ae045-9fcf-572f-a5ea-ed8c40b185ff', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 1, 1, 'They continued three years without war between Syria and Israel.'),
  ('5541c5c3-3336-56c1-a552-236822858816', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 2, 2, 'It happened in the third year, that Jehoshaphat the king of Judah came down to the king of Israel.'),
  ('fb1a8ef3-c0c4-5e62-a38a-5bbd18b66bfa', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 3, 3, 'The king of Israel said to his servants, "You know that Ramoth Gilead is ours, and we are still, and don''t take it out of the hand of the king of Syria?"'),
  ('248fea3a-aeca-5c6b-a855-b73e40f27ace', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 4, 4, 'He said to Jehoshaphat, "Will you go with me to battle to Ramoth Gilead?" Jehoshaphat said to the king of Israel, "I am as you are, my people as your people, my horses as your horses."'),
  ('be8ff8e2-2c39-5967-ac71-4964c392af4e', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 5, 5, 'Jehoshaphat said to the king of Israel, "Please inquire first for the word of Yahweh."'),
  ('f5406cee-86c4-5440-a5f2-7d01ee6eba9d', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 6, 6, 'Then the king of Israel gathered the prophets together, about four hundred men, and said to them, "Shall I go against Ramoth Gilead to battle, or shall I forbear?" They said, "Go up; for the Lord will deliver it into the hand of the king."'),
  ('2a5f9383-735a-58c6-a6e5-ae77058c80e8', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 7, 7, 'But Jehoshaphat said, "Isn''t there here a prophet of Yahweh, that we may inquire of him?"'),
  ('eb2a0148-3bc3-5687-a4cd-5e6c9cf84484', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 8, 8, 'The king of Israel said to Jehoshaphat, "There is yet one man by whom we may inquire of Yahweh, Micaiah the son of Imlah; but I hate him; for he does not prophesy good concerning me, but evil." Jehoshaphat said, "Don''t let the king say so."'),
  ('81ada3d0-7de0-59fc-ac18-4c125d1ae94e', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 9, 9, 'Then the king of Israel called an officer, and said, "Quickly get Micaiah the son of Imlah."'),
  ('7c05e1d1-246b-5432-a0cc-2ee38ae80ce2', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 10, 10, 'Now the king of Israel and Jehoshaphat the king of Judah were sitting each on his throne, arrayed in their robes, in an open place at the entrance of the gate of Samaria; and all the prophets were prophesying before them.'),
  ('2fdfb436-f2fd-59f1-afc7-6d0cf03f47b7', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 11, 11, 'Zedekiah the son of Chenaanah made him horns of iron, and said, "Thus says Yahweh, ''With these you shall push the Syrians, until they are consumed.''"'),
  ('461d2de3-495b-5f69-a2ee-d85816a82002', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 12, 12, 'All the prophets prophesied so, saying, "Go up to Ramoth Gilead, and prosper; for Yahweh will deliver it into the hand of the king."'),
  ('7aad5554-5471-51c6-a003-0b4a74728527', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 13, 13, 'The messenger who went to call Micaiah spoke to him, saying, "See now, the prophets declare good to the king with one mouth. Please let your word be like the word of one of them, and speak good."'),
  ('a60381e2-4ed6-5b8b-a812-7498e321593d', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 14, 14, 'Micaiah said, "As Yahweh lives, what Yahweh says to me, that I will speak."'),
  ('867cf1ee-1cac-5a96-a8b2-751f16abdf82', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 15, 15, 'When he had come to the king, the king said to him, "Micaiah, shall we go to Ramoth Gilead to battle, or shall we forbear?" He answered him, "Go up and prosper; and Yahweh will deliver it into the hand of the king."'),
  ('ce11159c-a26d-5b02-ace1-fb684f21ba6c', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 16, 16, 'The king said to him, "How many times do I have to adjure you that you speak to me nothing but the truth in the name of Yahweh?"'),
  ('ca961eeb-1a45-5b7f-afcf-dce7fad2a066', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 17, 17, 'He said, "I saw all Israel scattered on the mountains, as sheep that have no shepherd. Yahweh said, ''These have no master. Let them each return to his house in peace.''"'),
  ('b1dfff2e-5d5e-5441-a4ce-6bff63f3b261', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 18, 18, 'The king of Israel said to Jehoshaphat, "Didn''t I tell you that he would not prophesy good concerning me, but evil?"'),
  ('89ba5d59-0f56-5d3d-a3b8-22597f89d923', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 19, 19, 'Micaiah said, "Therefore hear the word of Yahweh. I saw Yahweh sitting on his throne, and all the army of heaven standing by him on his right hand and on his left.'),
  ('6c7b4a7f-2060-5f02-a9a5-e249995d0ea2', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 20, 20, 'Yahweh said, ''Who shall entice Ahab, that he may go up and fall at Ramoth Gilead?'' One said one thing; and another said another.'),
  ('e1b9d640-8390-5cd0-a9db-93a4b3817abd', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 21, 21, 'A spirit came out and stood before Yahweh, and said, ''I will entice him.'''),
  ('d7c7b195-8c07-5f34-ac70-163c394b95c0', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 22, 22, 'Yahweh said to him, ''How?'' He said, ''I will go out and will be a lying spirit in the mouth of all his prophets.'' He said, ''You will entice him, and will also prevail. Go out and do so.'''),
  ('6c829664-9848-59ba-aec1-2d73cc8127f2', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 23, 23, 'Now therefore, behold, Yahweh has put a lying spirit in the mouth of all these your prophets; and Yahweh has spoken evil concerning you."'),
  ('741166be-6796-5779-ac54-53ed75b0a042', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 24, 24, 'Then Zedekiah the son of Chenaanah came near, and struck Micaiah on the cheek, and said, "Which way did the Spirit of Yahweh go from me to speak to you?"'),
  ('8fcd35db-4059-55c8-a1af-13e2ba5c9177', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 25, 25, 'Micaiah said, "Behold, you will see on that day, when you go into an inner room to hide yourself."'),
  ('329a4241-e441-5bee-a8ee-8ef7703617a9', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 26, 26, 'The king of Israel said, "Take Micaiah, and carry him back to Amon the governor of the city, and to Joash the king''s son.'),
  ('d6940147-2666-5951-a074-1f166b4f1de2', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 27, 27, 'Say, ''Thus says the king, "Put this fellow in the prison, and feed him with bread of affliction and with water of affliction, until I come in peace."''"'),
  ('99ade910-c969-55b3-a9d1-9fa2c9e81276', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 28, 28, 'Micaiah said, "If you return at all in peace, Yahweh has not spoken by me." He said, "Listen, all you people!"'),
  ('fd6a0527-efc1-587e-a651-2efb301e9359', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 29, 29, 'So the king of Israel and Jehoshaphat the king of Judah went up to Ramoth Gilead.'),
  ('1c4a78fe-07bf-5598-a304-bbed17a32836', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 30, 30, 'The king of Israel said to Jehoshaphat, "I will disguise myself, and go into the battle; but you put on your robes." The king of Israel disguised himself, and went into the battle.'),
  ('34e2171b-8d68-5386-a691-7dfb3743e749', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 31, 31, 'Now the king of Syria had commanded the thirty-two captains of his chariots, saying, Fight neither with small nor great, except only with the king of Israel.'),
  ('eca9ab6d-3df4-555a-aa44-edc06c60b952', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 32, 32, 'It happened, when the captains of the chariots saw Jehoshaphat, that they said, "Surely that is the king of Israel!" and they turned aside to fight against him. Jehoshaphat cried out.'),
  ('8762114c-5c08-5855-abe5-ab3a120cac9d', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 33, 33, 'It happened, when the captains of the chariots saw that it was not the king of Israel, that they turned back from pursuing him.'),
  ('6175ab3a-42e8-548d-a157-44af9ec30b82', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 34, 34, 'A certain man drew his bow at random, and struck the king of Israel between the joints of the armor. Therefore he said to the driver of his chariot, "Turn your hand, and carry me out of the battle; for I am severely wounded."'),
  ('df0aa22f-47d2-5522-abe5-f9f59350761a', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 35, 35, 'The battle increased that day. The king was propped up in his chariot facing the Syrians, and died at evening. The blood ran out of the wound into the bottom of the chariot.'),
  ('acbe665b-8636-5e4c-af21-576cee76e359', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 36, 36, 'A cry went throughout the army about the going down of the sun, saying, "Every man to his city, and every man to his country!"'),
  ('59e5e873-f0c5-5773-a967-c81304255c35', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 37, 37, 'So the king died, and was brought to Samaria; and they buried the king in Samaria.'),
  ('9617a7d3-0975-5991-ad52-b7f96f332d83', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 38, 38, 'They washed the chariot by the pool of Samaria; and the dogs licked up his blood where the prostitutes washed themselves; according to the word of Yahweh which he spoke.'),
  ('cdf0d347-85f5-52c6-a004-5724273ba36a', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 39, 39, 'Now the rest of the acts of Ahab, and all that he did, and the ivory house which he built, and all the cities that he built, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('dfbbedef-9a0b-5aa5-a76e-86dbf41300c4', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 40, 40, 'So Ahab slept with his fathers; and Ahaziah his son reigned in his place.'),
  ('48feabab-32aa-553b-a56e-1273ac6085c7', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 41, 41, 'Jehoshaphat the son of Asa began to reign over Judah in the fourth year of Ahab king of Israel.'),
  ('874f158f-25b2-5d8f-ada4-699b17fb3236', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 42, 42, 'Jehoshaphat was thirty-five years old when he began to reign; and he reigned twenty-five years in Jerusalem. His mother''s name was Azubah the daughter of Shilhi.'),
  ('0d9e0341-5178-5205-ad91-b0e59ebd3bb0', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 43, 43, 'He walked in all the way of Asa his father; He didn''t turn aside from it, doing that which was right in the eyes of Yahweh: however the high places were not taken away; the people still sacrificed and burnt incense in the high places.'),
  ('7477a021-0b20-54b1-ae48-16415742a1ea', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 44, 44, 'Jehoshaphat made peace with the king of Israel.'),
  ('f96cd86d-b5d4-57ad-ac18-8f1d43edf85b', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 45, 45, 'Now the rest of the acts of Jehoshaphat, and his might that he showed, and how he warred, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('b8c7bdd0-21e6-560a-a754-6d8364d2f35e', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 46, 46, 'The remnant of the sodomites, that remained in the days of his father Asa, he put away out of the land.'),
  ('7c6aaf33-2b56-5ff8-a959-46fd28950bda', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 47, 47, 'There was no king in Edom: a deputy was king.'),
  ('fa720282-9c63-56b6-aeb3-e22f2549c408', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 48, 48, 'Jehoshaphat made ships of Tarshish to go to Ophir for gold: but they didn''t go; for the ships were broken at Ezion Geber.'),
  ('0fe7ecc1-0b38-5ef9-a626-af447d747a51', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 49, 49, 'Then Ahaziah the son of Ahab said to Jehoshaphat, "Let my servants go with your servants in the ships." But Jehoshaphat would not.'),
  ('7511058c-7555-5bf6-a3cb-a75c0d816583', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 50, 50, 'Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David his father; Jehoram his son reigned in his place.'),
  ('aff2333e-ea63-5a09-a840-8571e755ce8a', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 51, 51, 'Ahaziah the son of Ahab began to reign over Israel in Samaria in the seventeenth year of Jehoshaphat king of Judah, and he reigned two years over Israel.'),
  ('e982f22e-7038-5292-a023-8f93e3d05581', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 52, 52, 'He did that which was evil in the sight of Yahweh, and walked in the way of his father, and in the way of his mother, and in the way of Jeroboam the son of Nebat, in which he made Israel to sin.'),
  ('b93b0bfa-2377-57fa-a8b8-59f94c00dfa7', 'ab0ef126-34fb-55b7-a4c2-661716ba152a', NULL, 53, 53, 'He served Baal, and worshiped him, and provoked to anger Yahweh, the God of Israel, according to all that his father had done.'),
  ('dc771a11-4510-5be1-a365-82fbd9f97480', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 1, 1, 'Moab rebelled against Israel after the death of Ahab.'),
  ('8ef52f25-63a3-56a9-aae5-6d4ac8238fd4', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 2, 2, 'Ahaziah fell down through the lattice in his upper room that was in Samaria, and was sick. So he sent messengers, and said to them, "Go, inquire of Baal Zebub, the god of Ekron, whether I will recover of this sickness."'),
  ('ca848fe0-b154-578a-ad96-982a2363a6bb', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 3, 3, 'But the angel of Yahweh said to Elijah the Tishbite, "Arise, go up to meet the messengers of the king of Samaria, and tell them, ''Is it because there is no God in Israel, that you go to inquire of Baal Zebub, the god of Ekron?'),
  ('fafde23b-1085-59e3-a4a5-a7a312a498f9', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 4, 4, 'Now therefore thus says Yahweh, "You shall not come down from the bed where you have gone up, but shall surely die."''" Elijah departed.'),
  ('f852132a-c079-565d-a82e-43ca530cb853', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 5, 5, 'The messengers returned to him, and he said to them, "Why is it that you have returned?"'),
  ('db8119d2-2567-5989-a86d-e6e21317f11f', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 6, 6, 'They said to him, "A man came up to meet us, and said to us, ''Go, return to the king who sent you, and tell him, "Thus says Yahweh, ''Is it because there is no God in Israel, that you send to inquire of Baal Zebub, the god of Ekron? Therefore you shall not come down from the bed where you have gone up, but shall surely die.''"''"'),
  ('b7b43fb6-ca66-59d4-a619-7e57da348507', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 7, 7, 'He said to them, "What kind of man was he who came up to meet you, and told you these words?"'),
  ('a6b97587-07fe-5ea7-a88c-b23e64f54fcc', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 8, 8, 'They answered him, "He was a hairy man, and wearing a leather belt around his waist." He said, "It is Elijah the Tishbite."'),
  ('bd601763-2951-5261-a830-d2cac6cdfc96', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 9, 9, 'Then [the king] sent a captain of fifty with his fifty to him. He went up to him; and behold, he was sitting on the top of the hill. He said to him, "Man of God, the king has said, ''Come down!''"'),
  ('be17c81e-e9b4-542b-a31f-60a74b9c2d1f', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 10, 10, 'Elijah answered to the captain of fifty, "If I am a man of God, let fire come down from the sky, and consume you and your fifty!" Fire came down from the sky, and consumed him and his fifty.'),
  ('0844d69b-4045-5fad-a2e0-2f5d1171dec9', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 11, 11, 'Again he sent to him another captain of fifty and his fifty. He answered him, "Man of God, the king has said, ''Come down quickly!''"'),
  ('2721d62e-db23-5588-a9cc-e2e034d02c2b', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 12, 12, 'Elijah answered them, "If I am a man of God, let fire come down from the sky, and consume you and your fifty!" The fire of God came down from the sky, and consumed him and his fifty.'),
  ('e1b0aed1-aab7-5995-a436-9bda00cdb6c5', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 13, 13, 'Again he sent the captain of a third fifty with his fifty. The third captain of fifty went up, and came and fell on his knees before Elijah, and begged him, and said to him, "Man of God, please let my life, and the life of these fifty your servants, be precious in your sight.'),
  ('1b122679-c505-5fa6-a577-0d4153225093', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 14, 14, 'Behold, fire came down from the sky, and consumed the two former captains of fifty with their fifties. But now let my life be precious in your sight."'),
  ('942a08c4-1d58-53e6-a8ee-5475ae71ced8', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 15, 15, 'The angel of Yahweh said to Elijah, "Go down with him. Don''t be afraid of him." He arose, and went down with him to the king.'),
  ('d03541a3-56be-53ae-aec3-0572c90a7ec2', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 16, 16, 'He said to him, "Thus says Yahweh, ''Because you have sent messengers to inquire of Baal Zebub, the god of Ekron, is it because there is no God in Israel to inquire of his word? Therefore you shall not come down from the bed where you have gone up, but shall surely die.''"'),
  ('b0f71c64-6394-5020-a6db-7676eea074d7', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 17, 17, 'So he died according to the word of Yahweh which Elijah had spoken. Jehoram began to reign in his place in the second year of Jehoram the son of Jehoshaphat king of Judah; because he had no son.'),
  ('effe7a20-723b-5699-ae0a-61bef0775eb8', 'c4b3c81e-e6cc-5d5f-ad5c-62a1adb219fa', NULL, 18, 18, 'Now the rest of the acts of Ahaziah which he did, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('d096f15c-77a9-5368-ac00-8060ed7d3f2c', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 1, 1, 'It happened, when Yahweh would take up Elijah by a whirlwind into heaven, that Elijah went with Elisha from Gilgal.'),
  ('f5200276-7a93-5126-a216-02d5ab55f52e', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 2, 2, 'Elijah said to Elisha, "Please wait here, for Yahweh has sent me as far as Bethel." Elisha said, "As Yahweh lives, and as your soul lives, I will not leave you." So they went down to Bethel.'),
  ('dfb36f00-177c-50b0-a64a-741e5573859b', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 3, 3, 'The sons of the prophets who were at Bethel came out to Elisha, and said to him, "Do you know that Yahweh will take away your master from your head today?" He said, "Yes, I know it; hold your peace."'),
  ('33ff74b3-5c26-5df8-acb0-46d0d32b498e', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 4, 4, 'Elijah said to him, "Elisha, please wait here, for Yahweh has sent me to Jericho." He said, "As Yahweh lives, and as your soul lives, I will not leave you." So they came to Jericho.'),
  ('2716b68b-5d7c-588f-ad08-0005a7cbab0b', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 5, 5, 'The sons of the prophets who were at Jericho came near to Elisha, and said to him, "Do you know that Yahweh will take away your master from your head today?" He answered, "Yes, I know it. Hold your peace."'),
  ('11ca7ddf-bffb-5de1-a420-276ee0ac88c7', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 6, 6, 'Elijah said to him, "Please wait here, for Yahweh has sent me to the Jordan." He said, "As Yahweh lives, and as your soul lives, I will not leave you." They both went on.'),
  ('db182d62-9931-52cb-a540-067b6904059e', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 7, 7, 'Fifty men of the sons of the prophets went, and stood opposite them at a distance; and they both stood by the Jordan.'),
  ('00aea9e8-89ed-5539-a22c-84c55ee70241', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 8, 8, 'Elijah took his mantle, and wrapped it together, and struck the waters, and they were divided here and there, so that they two went over on dry ground.'),
  ('0779bbe9-053c-5482-a180-ef20c7011136', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 9, 9, 'It happened, when they had gone over, that Elijah said to Elisha, "Ask what I shall do for you, before I am taken from you." Elisha said, "Please let a double portion of your spirit be on me."'),
  ('d8b5f562-7046-56b1-a55c-0e0ad754d667', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 10, 10, 'He said, "You have asked a hard thing. If you see me when I am taken from you, it shall be so for you; but if not, it shall not be so."'),
  ('8db4b97b-a5c7-5ea0-a9d7-b8b0f06e95d1', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 11, 11, 'It happened, as they still went on, and talked, that behold, a chariot of fire and horses of fire separated them; and Elijah went up by a whirlwind into heaven.'),
  ('7e2f987f-3682-5af7-ac1e-fc798c0635a1', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 12, 12, 'Elisha saw it, and he cried, "My father, my father, the chariots of Israel and its horsemen!" He saw him no more: and he took hold of his own clothes, and tore them in two pieces.'),
  ('7c973c77-c8a9-513f-a56b-2166a96df89d', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 13, 13, 'He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of the Jordan.'),
  ('db42dc23-b0a1-5772-ad80-7f25ae3a0169', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 14, 14, 'He took the mantle of Elijah that fell from him, and struck the waters, and said, "Where is Yahweh, the God of Elijah?" When he also had struck the waters, they were divided here and there; and Elisha went over.'),
  ('e379072c-b1bb-571c-ad5b-1ae4c902d904', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 15, 15, 'When the sons of the prophets who were at Jericho over against him saw him, they said, "The spirit of Elijah rests on Elisha." They came to meet him, and bowed themselves to the ground before him.'),
  ('cbd031ef-58e0-5fb5-a5af-e3ecb6a4bee2', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 16, 16, 'They said to him, "See now, there are with your servants fifty strong men. Please let them go and seek your master. Perhaps the Spirit of Yahweh has taken him up, and put him on some mountain, or into some valley. He said, "You shall not send them."'),
  ('1a68d42a-ff8c-5d81-a3be-82db12d345de', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 17, 17, 'When they urged him until he was ashamed, he said, "Send them." They sent therefore fifty men; and they searched for three days, but didn''t find him.'),
  ('9bd3ef04-46bd-54fa-a809-9290568685e2', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 18, 18, 'They came back to him, while he stayed at Jericho; and he said to them, "Didn''t I tell you, ''Don''t go?''"'),
  ('011c7c08-e038-5092-ad34-612aa884bbda', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 19, 19, 'The men of the city said to Elisha, "Behold, please, the situation of this city is pleasant, as my lord sees; but the water is bad, and the land miscarries."'),
  ('42d25161-5dda-5724-aa83-32c4eb5b495d', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 20, 20, 'He said, "Bring me a new jar, and put salt in it." They brought it to him.'),
  ('c77a4a1d-c9a8-52af-a688-6e08abf0c772', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 21, 21, 'He went out to the spring of the waters, and threw salt into it, and said, "Thus says Yahweh, ''I have healed these waters. There shall not be from there any more death or miscarrying.''"'),
  ('ba9b3b81-4889-565e-aa19-dc274d5cb596', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 22, 22, 'So the waters were healed to this day, according to the word of Elisha which he spoke.'),
  ('ef08fff5-48b4-5091-a041-6afc82f45c42', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 23, 23, 'He went up from there to Bethel. As he was going up by the way, some youths came out of the city and mocked him, and said to him, "Go up, you baldy! Go up, you baldhead!"'),
  ('7cae84d5-b637-5b88-a275-a13d14e72c25', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 24, 24, 'He looked behind him and saw them, and cursed them in the name of Yahweh. Two female bears came out of the woods, and mauled forty-two of those youths.'),
  ('503c56aa-b1a7-59f0-af6e-b2687493e11f', '9a63e618-b4a0-5be4-ac3c-e78b082557be', NULL, 25, 25, 'He went from there to Mount Carmel, and from there he returned to Samaria.'),
  ('d8288b15-678f-5512-ae6b-376112aee3d4', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 1, 1, 'Now Jehoram the son of Ahab began to reign over Israel in Samaria in the eighteenth year of Jehoshaphat king of Judah, and reigned twelve years.'),
  ('cc8508b3-8450-5dce-adde-30c7fa2c4383', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, but not like his father, and like his mother; for he put away the pillar of Baal that his father had made.'),
  ('56b1bbe1-f170-5d79-aa26-2cd8835aa7fb', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 3, 3, 'Nevertheless he held to the sins of Jeroboam the son of Nebat, with which he made Israel to sin; he didn''t depart from it.'),
  ('8955d8ea-9fff-5def-a2ea-ff4b58d5dc46', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 4, 4, 'Now Mesha king of Moab was a sheep breeder; and he rendered to the king of Israel the wool of one hundred thousand lambs, and of one hundred thousand rams.'),
  ('b5bdcd26-fb72-50cb-a308-92be98d08a6a', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 5, 5, 'But it happened, when Ahab was dead, that the king of Moab rebelled against the king of Israel.'),
  ('b56e6ef0-c330-5df9-a63b-b9d6f67b0c24', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 6, 6, 'King Jehoram went out of Samaria at that time, and mustered all Israel.'),
  ('fcb1d3c2-2599-545e-ae82-da219a7ded7a', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 7, 7, 'He went and sent to Jehoshaphat the king of Judah, saying, "The king of Moab has rebelled against me. Will you go with me against Moab to battle?" He said, "I will go up. I am as you are, my people as your people, my horses as your horses."'),
  ('e36f3071-03f2-5752-ad4c-0ff3017e5493', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 8, 8, 'He said, "Which way shall we go up?" He answered, "The way of the wilderness of Edom."'),
  ('d250f3d4-a47b-528c-ac4c-39bd648e66c2', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 9, 9, 'So the king of Israel went, and the king of Judah, and the king of Edom; and they made a circuit of seven days'' journey. There was no water for the army, nor for the animals that followed them.'),
  ('cf1ba6b3-565f-579a-a491-05cf76f34e8f', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 10, 10, 'The king of Israel said, "Alas! For Yahweh has called these three kings together to deliver them into the hand of Moab."'),
  ('5136dd45-b42c-5b90-a20c-b3ad8ebfd601', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 11, 11, 'But Jehoshaphat said, "Isn''t there here a prophet of Yahweh, that we may inquire of Yahweh by him?" One of the king of Israel''s servants answered, "Elisha the son of Shaphat is here, who poured water on the hands of Elijah."'),
  ('c2b92392-5ec8-516a-a33f-56ef0f1c6e90', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 12, 12, 'Jehoshaphat said, "The word of Yahweh is with him." So the king of Israel and Jehoshaphat and the king of Edom went down to him.'),
  ('6d68f053-ff26-5118-a518-ab2f76495785', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 13, 13, 'Elisha said to the king of Israel, "What have I to do with you? Go to the prophets of your father, and to the prophets of your mother." The king of Israel said to him, "No; for Yahweh has called these three kings together to deliver them into the hand of Moab."'),
  ('2651e642-2df2-598e-a151-d77c0665ffdc', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 14, 14, 'Elisha said, "As Yahweh of Armies lives, before whom I stand, surely, were it not that I respect the presence of Jehoshaphat the king of Judah, I would not look toward you, nor see you.'),
  ('4d1c5820-8137-5067-a2b2-bc44e13dab7c', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 15, 15, 'But now bring me a minstrel." It happened, when the minstrel played, that the hand of Yahweh came on him.'),
  ('99f6094d-6d59-5753-a63d-f61b3c747cb0', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 16, 16, 'He said, "Thus says Yahweh, ''Make this valley full of trenches.'''),
  ('137207cd-4497-5f2e-a1f8-7519491cfd1f', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 17, 17, 'For thus says Yahweh, ''You will not see wind, neither will you see rain; yet that valley shall be filled with water, and you will drink, both you and your livestock and your animals.'),
  ('045bc576-a1b3-5715-abac-3b649a52bfdd', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 18, 18, 'This is but a light thing in the sight of Yahweh. He will also deliver the Moabites into your hand.'),
  ('4cfee0df-e82a-5669-acfc-69cebc692341', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 19, 19, 'You shall strike every fortified city, and every choice city, and shall fell every good tree, and stop all springs of water, and mar every good piece of land with stones.''"'),
  ('befcacfb-f3ee-5415-ae57-f84ce5ede979', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 20, 20, 'It happened in the morning, about the time of offering the offering, that behold, water came by the way of Edom, and the country was filled with water.'),
  ('c1178066-7b1a-5d25-a304-2ecc1b15f801', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 21, 21, 'Now when all the Moabites heard that the kings had come up to fight against them, they gathered themselves together, all who were able to put on armor, and upward, and stood on the border.'),
  ('2021bfa6-ed76-5af8-ada6-60fcac5ffea3', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 22, 22, 'They rose up early in the morning, and the sun shone on the water, and the Moabites saw the water over against them as red as blood.'),
  ('de8d28f5-dfd2-598e-a170-d651cb616a14', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 23, 23, 'They said, "This is blood. The kings are surely destroyed, and they have struck each other. Now therefore, Moab, to the spoil!"'),
  ('7aa6536f-0674-50ba-a6ca-831de1ba04c6', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 24, 24, 'When they came to the camp of Israel, the Israelites rose up and struck the Moabites, so that they fled before them; and they went forward into the land smiting the Moabites.'),
  ('578f2be3-d87a-5e9c-a766-9870157d0be4', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 25, 25, 'They beat down the cities; and on every good piece of land they cast every man his stone, and filled it; and they stopped all the springs of water, and felled all the good trees, until in Kir Hareseth [only] they left its stones; however the men armed with slings went about it, and struck it.'),
  ('bc7c2f79-2bb3-527b-a71a-3ab5d7208e5d', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 26, 26, 'When the king of Moab saw that the battle was too severe for him, he took with him seven hundred men who drew sword, to break through to the king of Edom; but they could not.'),
  ('446de659-0592-50de-a444-08f3a38070c8', '6efb86fb-cd9e-5f15-adb2-a3c164deaf4f', NULL, 27, 27, 'Then he took his eldest son who would have reigned in his place, and offered him for a burnt offering on the wall. There was great wrath against Israel: and they departed from him, and returned to their own land.'),
  ('ae770aab-01e4-5cbe-a86a-12e62d9fb642', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 1, 1, 'Now there cried a certain woman of the wives of the sons of the prophets to Elisha, saying, "Your servant my husband is dead. You know that your servant feared Yahweh. Now the creditor has come to take for himself my two children to be slaves."'),
  ('7a049743-a450-5c96-a4f2-228d9892f39f', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 2, 2, 'Elisha said to her, "What shall I do for you? Tell me: what do you have in the house?" She said, "Your handmaid has nothing in the house, except a pot of oil."'),
  ('751e8c9f-d2a4-5736-a787-bb98504d20f6', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 3, 3, 'Then he said, "Go, borrow containers from of all your neighbors, even empty containers. Don''t borrow just a few.'),
  ('bf69c87a-c567-596c-a473-8d705f74bda1', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 4, 4, 'You shall go in, and shut the door on you and on your sons, and pour out into all those containers; and you shall set aside that which is full."'),
  ('e54a2773-a4fe-5fad-a165-c7bac6ac5927', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 5, 5, 'So she went from him, and shut the door on her and on her sons; they brought the containers to her, and she poured out.'),
  ('e2a14f47-65d9-57f9-ab8a-ffc917f26f78', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 6, 6, 'It happened, when the containers were full, that she said to her son, "Bring me another container." He said to her, "There isn''t another container." The oil stopped flowing.'),
  ('93922952-9186-57a5-a3bc-3cb48cb10005', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 7, 7, 'Then she came and told the man of God. He said, "Go, sell the oil, and pay your debt; and you and your sons live on the rest."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('833e9737-eef2-5754-ad47-1813de85e793', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 8, 8, 'It fell on a day, that Elisha passed to Shunem, where there was a prominent woman; and she persuaded him to eat bread. So it was, that as often as he passed by, he turned in there to eat bread.'),
  ('e1927c6a-f664-5593-ac55-53a9e3453eda', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 9, 9, 'She said to her husband, "See now, I perceive that this is a holy man of God, that passes by us continually.'),
  ('5d591bd7-381d-57f5-a92d-c3e1673bd9f7', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 10, 10, 'Please let us make a little room on the wall. Let us set for him there a bed, a table, a chair, and a lamp stand. It shall be, when he comes to us, that he shall turn in there."'),
  ('00a19302-6682-593f-a38b-507bc9d8fa8f', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 11, 11, 'One day he came there, and he turned into the room and lay there.'),
  ('25af635b-a002-5d98-ac7a-51c617521dcc', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 12, 12, 'He said to Gehazi his servant, "Call this Shunammite." When he had called her, she stood before him.'),
  ('57aad3d9-2daf-5242-ae51-5bbbfcb2e8c3', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 13, 13, 'He said to him, "Say now to her, ''Behold, you have cared for us with all this care. What is to be done for you? Would you like to be spoken for to the king, or to the captain of the army?''" She answered, "I dwell among my own people."'),
  ('7ee9829f-ca53-5405-a76d-07dcab2ec43d', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 14, 14, 'He said, "What then is to be done for her?" Gehazi answered, "Most certainly she has no son, and her husband is old."'),
  ('d10a90b0-4477-55b8-a1e1-45bf9b35e26e', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 15, 15, 'He said, "Call her." When he had called her, she stood in the door.'),
  ('181b2ca7-59af-5ba2-aaee-49df25179e01', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 16, 16, 'He said, "At this season, when the time comes around, you will embrace a son." She said, "No, my lord, you man of God, do not lie to your handmaid."'),
  ('cf57ac73-0a90-5ce9-a76d-5848725be7e7', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 17, 17, 'The woman conceived, and bore a son at that season, when the time came around, as Elisha had said to her.'),
  ('60e98904-41d8-5edb-ad1f-9913baa44652', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 18, 18, 'When the child was grown, it happened one day that he went out to his father to the reapers.'),
  ('b7459775-5c01-5d53-aebc-9708bb03bed5', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 19, 19, 'He said to his father, "My head! My head!" He said to his servant, "Carry him to his mother."'),
  ('09820516-f99b-508d-a20f-e7c6586d196b', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 20, 20, 'When he had taken him, and brought him to his mother, he sat on her knees until noon, and then died.'),
  ('4434801f-f7d3-5df8-a3a4-d470c311cd88', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 21, 21, 'She went up and laid him on the bed of the man of God, and shut the door on him, and went out.'),
  ('93813cf9-d29b-58b7-ab71-28f4e404d42b', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 22, 22, 'She called to her husband, and said, "Please send me one of the servants, and one of the donkeys, that I may run to the man of God, and come again."'),
  ('51590d55-31b8-5ecb-a02c-cc92dd4b6434', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 23, 23, 'He said, "Why would you want go to him today? It is neither new moon nor Sabbath." She said, "It''s alright."'),
  ('67175069-2ce0-50fc-a10a-f1275e0e4c1f', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 24, 24, 'Then she saddled a donkey, and said to her servant, "Drive, and go forward! Don''t slow down for me, unless I ask you to."'),
  ('622fd29f-2ccc-5861-a720-b9c01143f6de', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 25, 25, 'So she went, and came to the man of God to Mount Carmel. It happened, when the man of God saw her afar off, that he said to Gehazi his servant, "Behold, there is the Shunammite.'),
  ('225f820b-3517-509c-a11b-bc02b357f16b', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 26, 26, 'Please run now to meet her, and ask her, ''Is it well with you? Is it well with your husband? Is it well with the child?''" She answered, "It is well."'),
  ('8b4a5c3c-b697-5123-aace-03e213d9f12b', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 27, 27, 'When she came to the man of God to the hill, she caught hold of his feet. Gehazi came near to thrust her away; but the man of God said, "Leave her alone; for her soul is troubled within her; and Yahweh has hidden it from me, and has not told me."'),
  ('a88370b7-31ea-5d9c-acde-1058c19116dc', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 28, 28, 'Then she said, "Did I desire a son of my lord? Didn''t I say, Do not deceive me?"'),
  ('e94ce74d-d287-5073-a959-b42f2a011137', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 29, 29, 'Then he said to Gehazi, "Tuck your cloak into your belt, take my staff in your hand, and go your way. If you meet any man, don''t greet him; and if anyone greets you, don''t answer him again. Then lay my staff on the face of the child."'),
  ('78bdb87c-b28a-5f95-a5c6-eba742bce008', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 30, 30, 'The mother of the child said, "As Yahweh lives, and as your soul lives, I will not leave you." He arose, and followed her.'),
  ('b71cd7ca-5e19-586a-a55e-1174c3517b0c', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 31, 31, 'Gehazi passed on before them, and laid the staff on the face of the child; but there was neither voice, nor hearing. Therefore he returned to meet him, and told him, saying, "The child has not awakened."'),
  ('3934881d-946a-5557-ab55-832894901254', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 32, 32, 'When Elisha had come into the house, behold, the child was dead, and laid on his bed.'),
  ('b6fe5639-0151-5002-af7e-7c7f1f9384c6', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 33, 33, 'He went in therefore, and shut the door on them both, and prayed to Yahweh.'),
  ('13e1a71d-960a-5970-a1dc-af090df8712a', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 34, 34, 'He went up, and lay on the child, and put his mouth on his mouth, and his eyes on his eyes, and his hands on his hands. He stretched himself on him; and the flesh of the child grew warm.'),
  ('894b76c5-d3d9-5738-a414-8d816e88ffcf', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 35, 35, 'Then he returned, and walked in the house once back and forth; and went up, and stretched himself on him. Then the child sneezed seven times, and the child opened his eyes.'),
  ('ee14add7-d62d-5625-a9d9-22968b7ca0ff', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 36, 36, 'He called Gehazi, and said, "Call this Shunammite!" So he called her. When she had come in to him, he said, "Take up your son."'),
  ('cf77ac08-4e34-5a72-ab10-aaf2a4a2cc16', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 37, 37, 'Then she went in, and fell at his feet, and bowed herself to the ground; and she took up her son, and went out.'),
  ('f2950002-6c79-56dd-a431-3ed60fff997d', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 38, 38, 'Elisha came again to Gilgal. There was a famine in the land; and the sons of the prophets were sitting before him; and he said to his servant, "Set on the great pot, and boil stew for the sons of the prophets."'),
  ('b9c2b75c-4a1a-53b8-ac39-bbc4170e8446', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 39, 39, 'One went out into the field to gather herbs, and found a wild vine, and gathered of it wild gourds his lap full, and came and shred them into the pot of stew; for they didn''t recognize them.'),
  ('5890f082-7823-58c1-a181-0c3141490c61', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 40, 40, 'So they poured out for the men to eat. It happened, as they were eating of the stew, that they cried out, and said, "Man of God, there is death in the pot!" They could not eat of it.'),
  ('236a1ff3-a9e7-5eba-a5f4-08d47530e44a', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 41, 41, 'But he said, "Then bring meal." He cast it into the pot; and he said, "Pour out for the people, that they may eat." There was no harm in the pot.'),
  ('5e8345e2-9daf-5250-a7eb-4d6460bf36c1', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 42, 42, 'A man from Baal Shalishah came, and brought the man of God bread of the first fruits, twenty loaves of barley, and fresh ears of grain in his sack. He said, "Give to the people, that they may eat."'),
  ('0f93c183-9e19-54b2-a6c9-c07c7d3b83d2', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 43, 43, 'His servant said, "What, should I set this before a hundred men?" But he said, "Give the people, that they may eat; for thus says Yahweh, ''They will eat, and will have some left over.''"'),
  ('e9d87b9c-48bf-5d41-ac9c-66b0d19df9c8', 'a362c078-cbb3-5d5e-a066-bef26aab859e', NULL, 44, 44, 'So he set it before them, and they ate, and left some of it, according to the word of Yahweh.'),
  ('594ac843-d119-5764-abda-6f09da2c292e', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 1, 1, 'Now Naaman, captain of the army of the king of Syria, was a great man with his master, and honorable, because by him Yahweh had given victory to Syria: he was also a mighty man of valor, [but he was] a leper.'),
  ('de68830d-4e3a-5fa2-a23e-f3595df02af4', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 2, 2, 'The Syrians had gone out in bands, and had brought away captive out of the land of Israel a little maiden; and she waited on Naaman''s wife.'),
  ('bed5bad2-bd24-58f9-ae8b-ccbf2b0b1ecc', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 3, 3, 'She said to her mistress, "I wish that my lord were with the prophet who is in Samaria! Then he would heal him of his leprosy."'),
  ('ccfc5813-c8f6-5d57-ab99-d7db9d89a4da', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 4, 4, 'Someone went in, and told his lord, saying, "The maiden who is from the land of Israel said this."'),
  ('b977319f-1887-57b3-a66e-f1eeed52a1ee', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 5, 5, 'The king of Syria said, "Go now, and I will send a letter to the king of Israel." He departed, and took with him ten talents of silver, and six thousand pieces of gold, and ten changes of clothing.'),
  ('7ad46ad3-e8e6-5b7f-a461-500d0603c25c', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 6, 6, 'He brought the letter to the king of Israel, saying, "Now when this letter has come to you, behold, I have sent Naaman my servant to you, that you may heal him of his leprosy."'),
  ('a49fe194-edd8-529e-aba4-44e26c6f90de', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 7, 7, 'It happened, when the king of Israel had read the letter, that he tore his clothes, and said, "Am I God, to kill and to make alive, that this man sends to me to heal a man of his leprosy? But please consider and see how he seeks a quarrel against me."'),
  ('8e1ba98f-9a42-551a-aefa-6a1847654b5d', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 8, 8, 'It was so, when Elisha the man of God heard that the king of Israel had torn his clothes, that he sent to the king, saying, "Why have you torn your clothes? Let him come now to me, and he shall know that there is a prophet in Israel."'),
  ('8fd75ea7-ed79-52a3-a6f2-91600ded87f2', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 9, 9, 'So Naaman came with his horses and with his chariots, and stood at the door of the house of Elisha.'),
  ('d69c3869-f055-524c-acd1-4149ea8d2a88', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 10, 10, 'Elisha sent a messenger to him, saying, "Go and wash in the Jordan seven times, and your flesh shall come again to you, and you shall be clean."'),
  ('2deb8c95-9c2d-5b2f-a59b-baa825890a8b', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 11, 11, 'But Naaman was angry, and went away, and said, "Behold, I thought, ''He will surely come out to me, and stand, and call on the name of Yahweh his God, and wave his hand over the place, and heal the leper.'''),
  ('e58ae22e-7d94-5e70-a004-2915a6df3a79', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 12, 12, 'Aren''t Abanah and Pharpar, the rivers of Damascus, better than all the waters of Israel? Couldn''t I wash in them, and be clean?" So he turned and went away in a rage.'),
  ('024d2512-6868-566b-a5a7-1818c252c0c7', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 13, 13, 'His servants came near, and spoke to him, and said, "My father, if the prophet had asked you do some great thing, wouldn''t you have done it? How much rather then, when he says to you, ''Wash, and be clean?''"'),
  ('68f6ab7e-f719-5b1c-a821-a34368718de2', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 14, 14, 'Then went he down, and dipped [himself] seven times in the Jordan, according to the saying of the man of God; and his flesh was restored like the flesh of a little child, and he was clean.'),
  ('ae6d458f-efb9-554f-a4e3-21ef89d03d3f', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 15, 15, 'He returned to the man of God, he and all his company, and came, and stood before him; and he said, "See now, I know that there is no God in all the earth, but in Israel. Now therefore, please take a gift from your servant."'),
  ('fef1282f-64a4-5331-a597-a8fbae0508d4', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 16, 16, 'But he said, "As Yahweh lives, before whom I stand, I will receive none." He urged him to take it; but he refused.'),
  ('a146a13f-2941-553f-a397-bf46ec4ce35c', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 17, 17, 'Naaman said, "If not, then, please let there be given to your servant two mules'' burden of earth; for your servant will from now on offer neither burnt offering nor sacrifice to other gods, but to Yahweh.'),
  ('95653655-4b49-5bc8-aa65-c48d40ff1b42', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 18, 18, 'In this thing may Yahweh pardon your servan: when my master goes into the house of Rimmon to worship there, and he leans on my hand, and I bow myself in the house of Rimmon. When I bow myself in the house of Rimmon, may Yahweh pardon your servant in this thing."'),
  ('489bdf80-84db-5941-a990-164595b61294', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 19, 19, 'He said to him, "Go in peace." So he departed from him a little way.'),
  ('83ad30eb-ce96-5655-abfa-53cdb27846c4', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 20, 20, 'But Gehazi the servant of Elisha the man of God, said, "Behold, my master has spared this Naaman the Syrian, in not receiving at his hands that which he brought. As Yahweh lives, I will run after him, and take something from him."'),
  ('339a1430-f5c4-556d-abb8-27b1c84f321f', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 21, 21, 'So Gehazi followed after Naaman. When Naaman saw one running after him, he came down from the chariot to meet him, and said, "Is all well?"'),
  ('edf26fe1-5753-53d7-a5a7-0ec77b2df7b5', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 22, 22, 'He said, "All is well. My master has sent me, saying, ''Behold, even now two young men of the sons of the prophets have come to me from the hill country of Ephraim. Please give them a talent of silver and two changes of clothing.''"'),
  ('36bca7a3-1ad6-5d10-adc5-4a1d45756511', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 23, 23, 'Naaman said, "Be pleased to take two talents." He urged him, and bound two talents of silver in two bags, with two changes of clothing, and laid them on two of his servants; and they carried them before him.'),
  ('8d0a35e8-261c-5e39-a1b1-9cfe9fd49697', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 24, 24, 'When he came to the hill, he took them from their hand, and stored them in the house. Then he let the men go, and they departed.'),
  ('0b19ad62-c45b-5e58-a6e1-1a1fa47efea6', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 25, 25, 'But he went in, and stood before his master. Elisha said to him, "Where did you come from, Gehazi?" He said, "Your servant went nowhere."'),
  ('54da49b1-1e65-5e2e-ac02-39b3e18c34dd', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 26, 26, 'He said to him, "Didn''t my heart go with you, when the man turned from his chariot to meet you? Is it a time to receive money, and to receive garments, and olive groves and vineyards, and sheep and cattle, and male servants and female servants?'),
  ('4c6e63f6-a7f1-5918-a394-fa98e9f86a37', '155d52e3-312c-5c8d-a689-5defde08ae4c', NULL, 27, 27, 'Therefore the leprosy of Naaman will cling to you and to your seed forever." He went out from his presence a leper, as white as snow.'),
  ('e261c8c3-44fc-52c9-a02e-64ff05761663', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 1, 1, 'The sons of the prophets said to Elisha, "See now, the place where we dwell before you is too small for us.'),
  ('654379e3-67e1-5ccc-a69a-bbd965fa0315', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 2, 2, 'Please let us go to the Jordan, and every man take a beam from there, and let us make us a place there, where we may dwell." He answered, "Go!"'),
  ('53007bfb-74b8-5dc7-a6bc-4dcae24cf176', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 3, 3, 'One said, "Please be pleased to go with your servants." He answered, "I will go."'),
  ('0f216c77-8d3f-5480-ac87-75aa51688f47', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 4, 4, 'So he went with them. When they came to the Jordan, they cut down wood.'),
  ('846d3ca6-0536-5fe4-a313-3a2db41f6770', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 5, 5, 'But as one was felling a beam, the axe head fell into the water. Then he cried, and said, "Alas, my master! For it was borrowed."'),
  ('f28880ed-1d0b-51ec-ab1c-a6b5d085c621', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 6, 6, 'The man of God asked, "Where did it fall?" He showed him the place. He cut down a stick, threw it in there, and made the iron float.'),
  ('a664632b-597f-55d2-a4f4-bc12fccd2650', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 7, 7, 'He said, "Take it." So he put out his hand and took it.'),
  ('e70964b3-a249-5d21-a008-4ac4110d04d5', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 8, 8, 'Now the king of Syria was warring against Israel; and he took counsel with his servants, saying, "My camp will be in such and such a place."'),
  ('60f744ab-4fca-54cf-a5f6-85cabe0e0f16', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 9, 9, 'The man of God sent to the king of Israel, saying, "Beware that you not pass such a place; for the Syrians are coming down there."'),
  ('93265753-78a3-5030-a559-cf2a82315a65', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 10, 10, 'The king of Israel sent to the place which the man of God told him and warned him of; and he saved himself there, not once nor twice.'),
  ('c9e0948e-2194-5d03-a666-cb65c6748229', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 11, 11, 'The heart of the king of Syria was very troubled about this. He called his servants, and said to them, "Won''t you show me which of us is for the king of Israel?"'),
  ('e2cacb8c-2950-51ad-ae08-a8091bc9398a', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 12, 12, 'One of his servants said, "No, my lord, O king; but Elisha, the prophet who is in Israel, tells the king of Israel the words that you speak in your bedroom."'),
  ('b5d515bf-6347-5163-a0d0-955ad25d9820', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 13, 13, 'He said, "Go and see where he is, that I may send and get him." It was told him, saying, "Behold, he is in Dothan."'),
  ('47953bb9-c80c-5317-abdc-25ae6576cd2a', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 14, 14, 'Therefore he sent horses, chariots, and a great army there. They came by night, and surrounded the city.'),
  ('b138fb1f-b67d-59cb-a62b-a7b412b8799d', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 15, 15, 'When the servant of the man of God had risen early, and gone out, behold, an army with horses and chariots was around the city. His servant said to him, "Alas, my master! What shall we do?"'),
  ('a1e7c969-859e-58be-af43-e8a4927a35db', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 16, 16, 'He answered, "Don''t be afraid; for those who are with us are more than those who are with them."'),
  ('213fc8eb-03c3-51e3-a22b-5baf2ffb6361', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 17, 17, 'Elisha prayed, and said, "Yahweh, please open his eyes, that he may see." Yahweh opened the eyes of the young man; and he saw: and behold, the mountain was full of horses and chariots of fire around Elisha.'),
  ('be1001db-5c90-5bfe-ac46-2ab0e0fa8a06', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 18, 18, 'When they came down to him, Elisha prayed to Yahweh, and said, "Please strike this people with blindness." He struck them with blindness according to the word of Elisha.'),
  ('cc44410b-ccbf-5357-ad6b-77df14135a18', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 19, 19, 'Elisha said to them, "This is not the way, neither is this the city. Follow me, and I will bring you to the man whom you seek." He led them to Samaria.'),
  ('08c14c6f-3bb6-52fd-a6dc-254e7f0dd167', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 20, 20, 'It happened, when they were come into Samaria, that Elisha said, "Yahweh, open the eyes of these men, that they may see." Yahweh opened their eyes, and they saw; and behold, they were in the midst of Samaria.'),
  ('c0ddac9a-d52d-5664-a3ec-7bdf8f323b36', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 21, 21, 'The king of Israel said to Elisha, when he saw them, "My father, shall I strike them? Shall I strike them?"'),
  ('935318d1-03a8-5ecb-aca7-a1124dd75c37', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 22, 22, 'He answered, "You shall not strike them. Would you strike those whom you have taken captive with your sword and with your bow? Set bread and water before them, that they may eat and drink, and go to their master."'),
  ('d4715fc7-e6cf-50a4-a8a8-3d8ec059ef03', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 23, 23, 'He prepared great feast for them. When they had eaten and drunk, he sent them away, and they went to their master. The bands of Syria stopped raiding the land of Israel.'),
  ('6dff446a-7f53-56b9-aaea-e44a953ac169', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 24, 24, 'It happened after this, that Benhadad king of Syria gathered all his army, and went up and besieged Samaria.'),
  ('c18a4dce-70c5-51be-a475-7dc11f157f8c', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 25, 25, 'There was a great famine in Samaria. Behold, they besieged it, until a donkey''s head was sold for eighty pieces of silver, and the fourth part of a kab of dove''s dung for five pieces of silver.'),
  ('b0f4b8c9-5a6f-5daf-a8a4-22cd9db678e1', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 26, 26, 'As the king of Israel was passing by on the wall, a woman cried to him, saying, "Help, my lord, O king!"'),
  ('416e3f8f-36d4-53e6-a771-7542e0c6f58b', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 27, 27, 'He said, "If Yahweh doesn''t help you, from where could I help you? From of the threshing floor, or from the winepress?"'),
  ('e8373e51-8ed5-5c7d-a5be-6c0df1261519', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 28, 28, 'The king said to her, "What ails you?" She answered, "This woman said to me, ''Give your son, that we may eat him today, and we will eat my son tomorrow.'''),
  ('ff075344-8da6-58a9-a881-3d1b257b7761', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 29, 29, 'So we boiled my son, and ate him: and I said to her on the next day, ''Give your son, that we may eat him;'' and she has hidden her son."'),
  ('4ad9d477-bd0f-5db4-a69c-97ae958ef302', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 30, 30, 'It happened, when the king heard the words of the woman, that he tore his clothes (now he was passing by on the wall); and the people looked, and behold, he had sackcloth underneath on his flesh.'),
  ('749c93bb-eb6e-5d19-a803-11c6e0bbf9b9', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 31, 31, 'Then he said, "God do so to me, and more also, if the head of Elisha the son of Shaphat shall stay on him this day."'),
  ('1bcd7b3e-48c9-5301-afbe-41d205869a5f', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 32, 32, 'But Elisha was sitting in his house, and the elders were sitting with him. Then the king sent a man from before him; but before the messenger came to him, he said to the elders, "Do you see how this son of a murderer has sent to take away my head? Behold, when the messenger comes, shut the door, and hold the door shut against him. Isn''t the sound of his master''s feet behind him?"'),
  ('d4bc789d-19f4-5034-ab5a-9217bba54249', '5b1b7ab4-42a8-50ba-a8a2-385bad3a5578', NULL, 33, 33, 'While he was still talking with them, behold, the messenger came down to him. Then he said, "Behold, this evil is from Yahweh. Why should I wait for Yahweh any longer?"'),
  ('031326dc-a611-5728-a036-dccc98fc2927', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 1, 1, 'Elisha said, "Hear the word of Yahweh. Thus says Yahweh, ''Tomorrow about this time a measure of fine flour will be sold for a shekel, and two measures of barley for a shekel, in the gate of Samaria.''"'),
  ('34efc418-abca-5efa-a36a-35bd0c8ba5d8', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 2, 2, 'Then the captain on whose hand the king leaned answered the man of God, and said, "Behold, if Yahweh made windows in heaven, could this thing be?" He said, "Behold, you shall see it with your eyes, but shall not eat of it."'),
  ('3aa191dd-ace2-5f9f-a94b-fe73c02ed0eb', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 3, 3, 'Now there were four leprous men at the entrance of the gate. They said one to another, "Why do we sit here until we die?'),
  ('53015ede-024b-5688-a240-11ffe36e8ec5', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 4, 4, 'If we say, ''We will enter into the city,'' then the famine is in the city, and we shall die there. If we sit still here, we also die. Now therefore come, and let us surrender to the army of the Syrians. If they save us alive, we will live; and if they kill us, we will only die."'),
  ('94448a2e-eb10-54f7-ac98-8a78becbb515', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 5, 5, 'They rose up in the twilight, to go to the camp of the Syrians. When they had come to the outermost part of the camp of the Syrians, behold, there was no man there.'),
  ('8ad22ea0-666c-58c0-a03a-5210c6f2d38f', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 6, 6, 'For the Lord had made the army of the Syrians to hear a noise of chariots, and a noise of horses, even the noise of a great army: and they said one to another, Behold, the king of Israel has hired against us the kings of the Hittites, and the kings of the Egyptians, to come on us.'),
  ('0a07344c-69f1-5de3-ae4d-b3dc1d025f7c', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 7, 7, 'Therefore they arose and fled in the twilight, and left their tents, and their horses, and their donkeys, even the camp as it was, and fled for their life.'),
  ('864d1ae3-346e-565b-a69c-a2a9773145fa', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 8, 8, 'When these lepers came to the outermost part of the camp, they went into one tent, and ate and drink, and carried there silver, and gold, and clothing, and went and hid it. Then they came back, and entered into another tent, and carried there also, and went and hid it.'),
  ('6564a7d1-631d-507b-aa19-2b4c1c779cba', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 9, 9, 'Then they said one to another, "We aren''t doing right. This day is a day of good news, and we keep silent. If we wait until the morning light, punishment will overtake us. Now therefore come, let us go and tell the king''s household."'),
  ('2f0ceaef-ea27-5aec-a339-531075d990da', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 10, 10, 'So they came and called to the porter of the city; and they told them, saying, "We came to the camp of the Syrians, and, behold, there was no man there, neither voice of man, but the horses tied, and the donkeys tied, and the tents as they were."'),
  ('d873baef-914c-5efb-ad27-0b8670e0863b', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 11, 11, 'He called the porters; and they told it to the king''s household within.'),
  ('f20cc372-7fa9-59b5-a92e-1adfc4d7031d', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 12, 12, 'The king arose in the night, and said to his servants, "I will now show you what the Syrians have done to us. They know that we are hungry. Therefore are they gone out of the camp to hide themselves in the field, saying, ''When they come out of the city, we shall take them alive, and get into the city.''"'),
  ('3f00a5ca-0326-5de5-ae7b-b48407e202c9', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 13, 13, 'One of his servants answered, "Please let some take five of the horses that remain, which are left in the city. Behold, they are like all the multitude of Israel who are left in it. Behold, they are like all the multitude of Israel who are consumed. Let us send and see."'),
  ('fd65db39-c1d2-59e7-a303-c5a4ed66970d', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 14, 14, 'They took therefore two chariots with horses; and the king sent after the army of the Syrians, saying, "Go and see."'),
  ('4a657802-f008-585c-a918-18b47b09e104', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 15, 15, 'They went after them to the Jordan; and behold, all the way was full of garments and vessels, which the Syrians had cast away in their haste. The messengers returned, and told the king.'),
  ('d1686c0c-068d-58df-a3c9-4f76dfb7533c', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 16, 16, 'The people went out, and plundered the camp of the Syrians. So a measure of fine flour was [sold] for a shekel, and two measures of barley for a shekel, according to the word of Yahweh.'),
  ('2070dbae-e1d9-51af-a33d-acf6b7f4da0d', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 17, 17, 'The king appointed the captain on whose hand he leaned to be in charge of the gate: and the people trod on him in the gate, and he died as the man of God had said, who spoke when the king came down to him.'),
  ('794fb5f0-2dd1-5a43-a218-667572c59392', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 18, 18, 'It happened, as the man of God had spoken to the king, saying, "Two measures of barley for a shekel, and a measure of fine flour for a shekel, shall be tomorrow about this time in the gate of Samaria;"'),
  ('6b0a0847-87d6-5d33-a7b6-4dec3c398a44', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 19, 19, 'and that captain answered the man of God, and said, "Now, behold, if Yahweh should make windows in heaven, might such a thing be?" and he said, "Behold, you shall see it with your eyes, but shall not eat of it."'),
  ('321e15e1-2525-5bf8-ac2a-c2a51e3dd543', '2d217b66-e8df-5a0b-afe7-e3c0d9e0898a', NULL, 20, 20, 'It happened like that to him; for the people trod on him in the gate, and he died.'),
  ('abe6fcb6-22f1-5ba5-a932-3215955a0c3e', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 1, 1, 'Now Elisha had spoken to the woman, whose son he had restored to life, saying, "Arise, and go, you and your household, and stay for a while wherever you can; for Yahweh has called for a famine. It shall also come on the land seven years."'),
  ('35604d14-9f3a-5ff4-ad57-81102a2a406d', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 2, 2, 'The woman arose, and did according to the word of the man of God. She went with her household, and lived in the land of the Philistines seven years.'),
  ('6f5c35eb-8357-5339-a6ff-ecc5ad673827', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 3, 3, 'It happened at the seven years'' end, that the woman returned out of the land of the Philistines. Then she went forth to cry to the king for her house and for her land.'),
  ('1bf86c8a-8988-534e-af92-01d18a19023a', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 4, 4, 'Now the king was talking with Gehazi the servant of the man of God, saying, "Please tell me all the great things that Elisha has done."'),
  ('beb5b0d6-fbd3-5691-a0c3-3b8c508dcf87', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 5, 5, 'It happened, as he was telling the king how he had restored to life him who was dead, that behold, the woman, whose son he had restored to life, cried to the king for her house and for her land. Gehazi said, "My lord, O king, this is the woman, and this is her son, whom Elisha restored to life."'),
  ('20d3b5f1-4751-582d-abc0-7219320c065c', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 6, 6, 'When the king asked the woman, she told him. So the king appointed to her a certain officer, saying, "Restore all that was hers, and all the fruits of the field since the day that she left the land, even until now."'),
  ('95541adc-fa71-51d1-a859-528a7fd3cc9f', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 7, 7, 'Elisha came to Damascus; and Benhadad the king of Syria was sick. It was told him, saying, "The man of God has come here."'),
  ('472badc7-4dab-5811-affe-7871333d24b5', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 8, 8, 'The king said to Hazael, "Take a present in your hand, and go, meet the man of God, and inquire of Yahweh by him, saying, ''Will I recover from this sickness?''"'),
  ('78e8ca32-a925-5567-af0d-1adef567874b', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 9, 9, 'So Hazael went to meet him, and took a present with him, even of every good thing of Damascus, forty camels'' burden, and came and stood before him, and said, "Your son Benhadad king of Syria has sent me to you, saying, ''Will I recover from this sickness?''"'),
  ('5cc6487a-14bb-5aba-a4e1-e75cd41bc042', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 10, 10, 'Elisha said to him, "Go, tell him, ''You shall surely recover;'' however Yahweh has shown me that he shall surely die."'),
  ('7febbe1e-3af1-5f56-a334-39ce60a2bf37', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 11, 11, 'He settled his gaze steadfastly [on him], until he was ashamed. Then the man of God wept.'),
  ('250af90f-2970-55f2-a0e6-15037ee9c87b', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 12, 12, 'Hazael said, "Why do you weep, my lord?" He answered, "Because I know the evil that you will do to the children of Israel. You will set their strongholds on fire, and you will kill their young men with the sword, and will dash in pieces their little ones, and rip up their women with child."'),
  ('47768bda-8ab5-5b0b-a251-dd726e038320', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 13, 13, 'Hazael said, "But what is your servant, who is but a dog, that he should do this great thing?" Elisha answered, "Yahweh has shown me that you will be king over Syria."'),
  ('858b73b2-f3b7-591f-ad06-22f4a1e3806e', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 14, 14, 'Then he departed from Elisha, and came to his master, who said to him, "What did Elisha say to you?" He answered, "He told me that you would surely recover."'),
  ('6ed528c4-1b21-5d19-a605-bad9cf4444b9', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 15, 15, 'It happened on the next day, that he took a thick cloth, dipped it in water, and spread it on his face, so that he died. Then Hazael reigned in his place.'),
  ('465b45a5-f8af-5020-a9af-016dc3dbb30c', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 16, 16, 'In the fifth year of Joram the son of Ahab king of Israel, Jehoshaphat being king of Judah then, Jehoram the son of Jehoshaphat king of Judah began to reign.'),
  ('d2a4e1a7-7e08-5c92-a6c5-850b4098a622', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 17, 17, 'He was thirty-two years old when he began to reign. He reigned eight years in Jerusalem.'),
  ('5b5ea26e-ebc4-597b-ad69-cfac73d241d0', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 18, 18, 'He walked in the way of the kings of Israel, as did the house of Ahab; for he had the daughter of Ahab as wife. He did that which was evil in the sight of Yahweh.'),
  ('6549effd-2617-56d3-a122-00811ca4a437', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 19, 19, 'However Yahweh would not destroy Judah, for David his servant''s sake, as he promised him to give to him a lamp for his children always.'),
  ('bbf03418-7c7e-5667-a950-ede128be6ac1', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 20, 20, 'In his days Edom revolted from under the hand of Judah, and made a king over themselves.'),
  ('260490a7-a65c-573d-af26-40d18dadca12', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 21, 21, 'Then Joram passed over to Zair, and all his chariots with him: and he rose up by night, and struck the Edomites who surrounded him, and the captains of the chariots; and the people fled to their tents.'),
  ('e540eeba-5714-58bc-a695-6430ed7dd10e', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 22, 22, 'So Edom revolted from under the hand of Judah to this day. Then did Libnah revolt at the same time.'),
  ('46de0cf0-03fd-5606-a6dc-6da73db601c3', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 23, 23, 'The rest of the acts of Joram, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('9e4ce1bf-d235-541e-a8c5-e63e44fa6c15', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 24, 24, 'Joram slept with his fathers, and was buried with his fathers in the city of David; and Ahaziah his son reigned in his place.'),
  ('d4bfd727-dbd9-5ecf-ae12-8b06bcd1ed94', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 25, 25, 'In the twelfth year of Joram the son of Ahab king of Israel did Ahaziah the son of Jehoram king of Judah begin to reign.'),
  ('260e7aaf-b157-5344-ad93-c753f1ff1bd6', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 26, 26, 'Twenty-two years old was Ahaziah when he began to reign; and he reigned one year in Jerusalem. His mother''s name was Athaliah the daughter of Omri king of Israel.'),
  ('df3ce675-e479-5dac-aa1d-37890eb69c54', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 27, 27, 'He walked in the way of the house of Ahab, and did that which was evil in the sight of Yahweh, as did the house of Ahab; for he was the son-in-law of the house of Ahab.'),
  ('d2695c95-ae6a-512a-ad30-c1bca3ba5aa8', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 28, 28, 'He went with Joram the son of Ahab to war against Hazael king of Syria at Ramoth Gilead: and the Syrians wounded Joram.'),
  ('639d9c39-8015-56d7-a28d-93a5f22e70e8', '2d3e97a7-8edc-5613-a59e-34f7081dca65', NULL, 29, 29, 'King Joram returned to be healed in Jezreel of the wounds which the Syrians had given him at Ramah, when he fought against Hazael king of Syria. Ahaziah the son of Jehoram king of Judah went down to see Joram the son of Ahab in Jezreel, because he was sick.'),
  ('d3935fb4-0b44-56fd-a477-79f0d79cdae6', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 1, 1, 'Elisha the prophet called one of the sons of the prophets, and said to him, "Put your belt on your waist, take this vial of oil in your hand, and go to Ramoth Gilead.'),
  ('d6568d5e-3868-5507-a6da-57e1441092b7', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 2, 2, 'When you come there, find Jehu the son of Jehoshaphat the son of Nimshi, and go in, and make him arise up from among his brothers, and carry him to an inner room.'),
  ('18175257-b8b3-5b3a-a91c-c6b0e262e069', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 3, 3, 'Then take the vial of oil, and pour it on his head, and say, ''Thus says Yahweh, "I have anointed you king over Israel."'' Then open the door, flee, and don''t wait."'),
  ('490e6e94-016e-5f54-a8fe-9fd9fc0ed276', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 4, 4, 'So the young man, even the young man the prophet, went to Ramoth Gilead.'),
  ('a5d1fc03-2042-54fb-a1f9-2e5c78ced944', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 5, 5, 'When he came, behold, the captains of the army were sitting. Then he said, "I have a message for you, captain." Jehu said, "To which of us all?" He said, "To you, O captain."'),
  ('92770e21-19cc-536b-aa94-70c0b831928d', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 6, 6, 'He arose, and went into the house. Then he poured the oil on his head, and said to him, "Thus says Yahweh, the God of Israel, ''I have anointed you king over the people of Yahweh, even over Israel.'),
  ('de5ab216-f34d-5cc5-a081-c884130c2366', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 7, 7, 'You shall strike the house of Ahab your master, that I may avenge the blood of my servants the prophets, and the blood of all the servants of Yahweh, at the hand of Jezebel.'),
  ('3b24a01e-27dd-5ded-a9dd-0e5c4aeba87c', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 8, 8, 'For the whole house of Ahab shall perish. I will cut off from Ahab everyone who urinates against a wall, both him who is shut up and him who is left at large in Israel.'),
  ('954f263f-35e8-55be-ab4e-b30d94b06489', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 9, 9, 'I will make the house of Ahab like the house of Jeroboam the son of Nebat, and like the house of Baasha the son of Ahijah.'),
  ('6f005520-21b3-53ac-a94b-43999aacce91', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 10, 10, 'The dogs will eat Jezebel on the plot of ground of Jezreel, and there shall be none to bury her.''" He opened the door, and fled.'),
  ('7abb4bdc-6e52-5927-ad10-549becc8c293', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 11, 11, 'Then Jehu came forth to the servants of his lord: and one said to him, "Is all well? Why did this mad fellow come to you?" He said to them, "You know the man and what his talk was."'),
  ('82d9d68a-9c71-5ebf-a373-d82a22dd42fe', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 12, 12, 'They said, "That is a lie. Tell us now." He said, "He said to me, ''Thus says Yahweh, I have anointed you king over Israel.''"'),
  ('79dcfc1e-d2e3-522b-aecb-496e759e3529', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 13, 13, 'Then they hurried, and took every man his garment, and put it under him on the top of the stairs, and blew the trumpet, saying, "Jehu is king."'),
  ('050b413e-db89-58dc-a1bb-3f10d8fa8da3', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 14, 14, 'So Jehu the son of Jehoshaphat the son of Nimshi conspired against Joram. (Now Joram was keeping Ramoth Gilead, he and all Israel, because of Hazael king of Syria;'),
  ('3c259cd4-57bb-5620-aecd-45557f59e4eb', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 15, 15, 'but king Joram was returned to be healed in Jezreel of the wounds which the Syrians had given him, when he fought with Hazael king of Syria.) Jehu said, "If this is your thinking, then let no one escape and go out of the city, to go to tell it in Jezreel."'),
  ('0f7b78c6-80e9-503e-a510-44a23bf2a762', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 16, 16, 'So Jehu rode in a chariot, and went to Jezreel; for Joram lay there. Ahaziah king of Judah had come down to see Joram.'),
  ('bd2a12cb-7fcb-5c36-ab4f-78fcd7981ad0', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 17, 17, 'Now the watchman was standing on the tower in Jezreel, and he spied the company of Jehu as he came, and said, "I see a company." Joram said, "Take a horseman, and send to meet them, and let him say, ''Is it peace?''"'),
  ('6ac0debf-d9dc-5f67-a858-c98da30e3bcf', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 18, 18, 'So there went one on horseback to meet him, and said, "Thus says the king, ''Is it peace?''" Jehu said, "What do you have to do with peace? Fall in behind me!" The watchman said, "The messenger came to them, but he isn''t coming back."'),
  ('67d2ffed-da62-5b9a-ae8c-eb28cf1a5b8c', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 19, 19, 'Then he sent out a second on horseback, who came to them, and said, "Thus says the king, ''Is it peace?''" Jehu answered, "What do you have to do with peace? Fall in behind me!"'),
  ('1918e474-25c8-5f45-a892-9c6744c29edd', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 20, 20, 'The watchman said, "He came to them, and isn''t coming back. The driving is like the driving of Jehu the son of Nimshi; for he drives furiously."'),
  ('34fb89d2-0530-5919-a4a7-69dace22b83c', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 21, 21, 'Joram said, "Get ready!" They got his chariot ready. Joram king of Israel and Ahaziah king of Judah went out, each in his chariot, and they went out to meet Jehu, and found him in the portion of Naboth the Jezreelite.'),
  ('8b103b40-2c92-51b5-af18-644491b271a3', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 22, 22, 'It happened, when Joram saw Jehu, that he said, "Is it peace, Jehu?" He answered, "What peace, so long as the prostitution of your mother Jezebel and her witchcraft abound?"'),
  ('557ccc7b-e0dc-58bf-a61e-95d5a6130a67', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 23, 23, 'Joram turned his hands, and fled, and said to Ahaziah, "There is treason, Ahaziah!"'),
  ('f5089a07-3be3-59a4-a92c-6f3953197022', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 24, 24, 'Jehu drew his bow with his full strength, and struck Joram between his arms; and the arrow went out at his heart, and he sunk down in his chariot.'),
  ('e909b1b1-2048-5071-a27b-94e996db10a4', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 25, 25, 'Then Jehu said to Bidkar his captain, "Pick him up, and throw him in the plot of the field of Naboth the Jezreelite; for remember how, when you and I rode together after Ahab his father, Yahweh laid this burden on him:'),
  ('05aacad1-e093-5fc0-ace2-2c84d670a7e1', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 26, 26, '''Surely I have seen yesterday the blood of Naboth, and the blood of his sons,'' says Yahweh; ''and I will repay you in this plot of ground,'' says Yahweh. Now therefore take and cast him onto the plot of ground, according to the word of Yahweh."'),
  ('5162a3f1-8dc6-5702-a557-ec926895f221', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 27, 27, 'But when Ahaziah the king of Judah saw this, he fled by the way of the garden house. Jehu followed after him, and said, "Strike him also in the chariot!" They struck him at the ascent of Gur, which is by Ibleam. He fled to Megiddo, and died there.'),
  ('61e5c4b4-cf34-50cb-a2a4-1c739e252f01', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 28, 28, 'His servants carried him in a chariot to Jerusalem, and buried him in his tomb with his fathers in the city of David.'),
  ('ad1e8aac-a9a8-5688-aac3-c57eff4d74eb', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 29, 29, 'In the eleventh year of Joram the son of Ahab began Ahaziah to reign over Judah.'),
  ('95b8e6f6-7c7a-5fa9-a813-4fc8307f1f7d', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 30, 30, 'When Jehu was come to Jezreel, Jezebel heard of it; and she painted her eyes, and attired her head, and looked out at the window.'),
  ('b2efb8da-49a8-5d42-af12-9b2cfd09fe9c', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 31, 31, 'As Jehu entered in at the gate, she said, "Do you come in peace, Zimri, you murderer of your master?"'),
  ('3383ef90-ffa0-555c-a50c-14d15b7a7670', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 32, 32, 'He lifted up his face to the window, and said, "Who is on my side? Who?" Two or three eunuchs looked out at him.'),
  ('5209b511-6b0b-50fd-a407-22d6ff79d765', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 33, 33, 'He said, "Throw her down!" So they threw her down; and some of her blood was sprinkled on the wall, and on the horses. Then he trampled her under foot.'),
  ('c8a4a7cc-db08-5d94-a7c2-bf37b0f564fd', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 34, 34, 'When he was come in, he ate and drink; and he said, "See now to this cursed woman, and bury her; for she is a king''s daughter."'),
  ('23db07d0-5df6-537d-a693-e9dd0c49c3f7', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 35, 35, 'They went to bury her; but they found no more of her than the skull, and the feet, and the palms of her hands.'),
  ('41f11d35-99cd-55f3-a581-e2ddbf85f617', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 36, 36, 'Therefore they came back, and told him. He said, "This is the word of Yahweh, which he spoke by his servant Elijah the Tishbite, saying, ''The dogs will eat the flesh of Jezebel on the plot of Jezreel,'),
  ('999a54a5-aad3-5548-a61d-4d10af39974a', '6adbdcd0-17df-5d59-ae89-c1dbea307de7', NULL, 37, 37, 'and the body of Jezebel shall be as dung on the face of the field in the portion of Jezreel, so that they shall not say, "This is Jezebel."''"'),
  ('09835973-4df1-5a98-a780-8887847ece7b', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 1, 1, 'Now Ahab had seventy sons in Samaria. Jehu wrote letters, and sent to Samaria, to the rulers of Jezreel, even the elders, and to those who brought up [the sons of] Ahab, saying,'),
  ('70e0a8fd-087d-54a8-a6ab-b7c07e24356e', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 2, 2, '"Now as soon as this letter comes to you, since your master''s sons are with you, and there are with you chariots and horses, a fortified city also, and armor.'),
  ('21dca288-5a44-5490-aef7-6f4903fd0dcb', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 3, 3, 'Select the best and fittest of your master''s sons, set him on his father''s throne, and fight for your master''s house."'),
  ('dc4a11b4-4a03-5ca5-af59-aa2a66fe76cd', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 4, 4, 'But they were exceedingly afraid, and said, "Behold, the two kings didn''t stand before him! How then shall we stand?"'),
  ('e186f834-f466-5aa5-a271-32751e1678f2', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 5, 5, 'He who was over the household, and he who was over the city, the elders also, and those who raised the children, sent to Jehu, saying, "We are your servants, and will do all that you ask us. We will not make any man king. You do that which is good in your eyes."'),
  ('5de1511a-409b-50b3-aa4a-876658a385fa', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 6, 6, 'Then he wrote a letter the second time to them, saying, "If you are on my side, and if you will listen to my voice, take the heads of the men your master''s sons, and come to me to Jezreel by tomorrow this time." Now the king''s sons, being seventy persons, were with the great men of the city, who brought them up.'),
  ('f82810cc-519e-5994-a820-f235a4befad5', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 7, 7, 'It happened, when the letter came to them, that they took the king''s sons, and killed them, even seventy persons, and put their heads in baskets, and sent them to him to Jezreel.'),
  ('fdf85762-f210-57f3-a586-2cba37f7d450', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 8, 8, 'A messenger came, and told him, "They have brought the heads of the king''s sons." He said, "Lay them in two heaps at the entrance of the gate until the morning."'),
  ('f85e3c96-08a1-5a9e-a851-18e9849c2b6f', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 9, 9, 'It happened in the morning, that he went out, and stood, and said to all the people, "You are righteous. Behold, I conspired against my master, and killed him; but who struck all these?'),
  ('b5d9fd02-14ad-5867-a058-375201e443e7', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 10, 10, 'Know now that nothing shall fall to the earth of the word of Yahweh, which Yahweh spoke concerning the house of Ahab. For Yahweh has done that which he spoke by his servant Elijah."'),
  ('12e00d5c-57d3-51e6-a37b-bf0cc87b12e2', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 11, 11, 'So Jehu struck all that remained of the house of Ahab in Jezreel, with all his great men, his familiar friends, and his priests, until he left him none remaining.'),
  ('912d4f6c-d73a-561c-ade6-066ef97d1712', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 12, 12, 'He arose and departed, and went to Samaria. As he was at the shearing house of the shepherds on the way,'),
  ('a1f3919c-01e4-5a4d-acb9-46665511119b', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 13, 13, 'Jehu met with the brothers of Ahaziah king of Judah, and said, "Who are you?" They answered, "We are the brothers of Ahaziah. We are going down to greet the children of the king and the children of the queen."'),
  ('0623a288-7ed3-56b9-a891-5356bd1a0d46', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 14, 14, 'He said, "Take them alive!" They took them alive, and killed them at the pit of the shearing house, even forty-two men. He didn''t leave any of them.'),
  ('1c9eb7b1-0eda-5480-a8ed-0466cc441228', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 15, 15, 'When he had departed from there, he met Jehonadab the son of Rechab coming to meet him. He greeted him, and said to him, "Is your heart right, as my heart is with your heart?" Jehonadab answered, "It is." "If it is, give me your hand." He gave him his hand; and he took him up to him into the chariot.'),
  ('7019eee6-fee3-52b3-a741-3867b53e8d1b', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 16, 16, 'He said, "Come with me, and see my zeal for Yahweh." So they made him ride in his chariot.'),
  ('48c84dbc-9f82-59ba-ad92-12271949494e', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 17, 17, 'When he came to Samaria, he struck all who remained to Ahab in Samaria, until he had destroyed him, according to the word of Yahweh, which he spoke to Elijah.'),
  ('8e7aba38-fc1a-54e6-ab37-0fa851295255', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 18, 18, 'Jehu gathered all the people together, and said to them, "Ahab served Baal a little; but Jehu will serve him much.'),
  ('2d9670b7-96fb-5c35-a219-cc8e7e3c6658', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 19, 19, 'Now therefore call to me all the prophets of Baal, all of his worshippers, and all of his priests. Let none be absent; for I have a great sacrifice to Baal. Whoever is absent, he shall not live." But Jehu did it in subtlety, intending that he might destroy the worshippers of Baal.'),
  ('e8a5fc69-eb55-5657-a1b0-fae7ce825c93', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 20, 20, 'Jehu said, "Sanctify a solemn assembly for Baal!" They proclaimed it.'),
  ('710861bb-f8b6-51e4-a8ed-da4f50dfc6ac', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 21, 21, 'Jehu sent through all Israel; and all the worshippers of Baal came, so that there was not a man left that didn''t come. They came into the house of Baal; and the house of Baal was filled from one end to another.'),
  ('5be0fa76-a39f-58a0-a6ea-98ec5faede1f', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 22, 22, 'He said to him who was over the vestry, "Bring out robes for all the worshippers of Baal!" He brought robes out to them.'),
  ('5bdcd123-95a7-55d8-a09d-69b717f57f7a', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 23, 23, 'Jehu went with Jehonadab the son of Rechab into the house of Baal. Then he said to the worshippers of Baal, "Search, and look that there are here with you none of the servants of Yahweh, but the worshippers of Baal only."'),
  ('13f96a06-9417-555b-a952-01651f958db7', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 24, 24, 'They went in to offer sacrifices and burnt offerings. Now Jehu had appointed him eighty men outside, and said, "If any of the men whom I bring into your hands escape, [he who lets him go], his life shall be for the life of him."'),
  ('780788b2-e14d-5a0d-a4b3-81a1f5ea947c', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 25, 25, 'It happened, as soon as he had made an end of offering the burnt offering, that Jehu said to the guard and to the captains, "Go in, and kill them! Let none escape." They struck them with the edge of the sword; and the guard and the captains cast them out, and went to the city of the house of Baal.'),
  ('bd52566d-98da-584c-a202-01a08c688c13', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 26, 26, 'They brought out the pillars that were in the house of Baal, and burned them.'),
  ('9c054f0c-04cc-52a0-aa7a-6b42d4103f39', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 27, 27, 'They broke down the pillar of Baal, and broke down the house of Baal, and made it a latrine, to this day.'),
  ('a2c03318-a35a-521f-a837-6d3f02ce9e15', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 28, 28, 'Thus Jehu destroyed Baal out of Israel.'),
  ('92a77aeb-e776-5752-a585-2ee7284d892a', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 29, 29, 'However from the sins of Jeroboam the son of Nebat, with which he made Israel to sin, Jehu didn''t depart from after them, [to wit], the golden calves that were in Bethel, and that were in Dan.'),
  ('388918dd-7a30-5d70-af1b-f6862246e7a4', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 30, 30, 'Yahweh said to Jehu, "Because you have done well in executing that which is right in my eyes, [and] have done to the house of Ahab according to all that was in my heart, your sons of the fourth generation shall sit on the throne of Israel."'),
  ('dd8a60e7-794f-5e71-a8ae-b8ee552d7683', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 31, 31, 'But Jehu took no heed to walk in the law of Yahweh, the God of Israel, with all his heart. He didn''t depart from the sins of Jeroboam, with which he made Israel to sin.'),
  ('93a5a2a2-5664-5563-a5f9-ac04119acea7', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 32, 32, 'In those days Yahweh began to cut off from Israel; and Hazael struck them in all the borders of Israel;'),
  ('e2e2b3d7-710b-58bf-a117-01514c05dcae', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 33, 33, 'from the Jordan eastward, all the land of Gilead, the Gadites, and the Reubenites, and the Manassites, from Aroer, which is by the valley of the Arnon, even Gilead and Bashan.'),
  ('4d84a85a-5be4-5081-a771-09785b40380f', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 34, 34, 'Now the rest of the acts of Jehu, and all that he did, and all his might, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('b9b01e1f-55e3-5d73-a952-32b0d1eeece7', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 35, 35, 'Jehu slept with his fathers; and they buried him in Samaria. Jehoahaz his son reigned in his place.'),
  ('6c7a25bc-0df7-52fe-a519-adc1bb03368c', 'f91985eb-0484-52fa-a996-18665d413516', NULL, 36, 36, 'The time that Jehu reigned over Israel in Samaria was twenty-eight years.'),
  ('609b2fcd-79ad-5382-a6a5-34751ff029ce', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 1, 1, 'Now when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the seed royal.'),
  ('21710b74-fa0b-5ce6-a4bd-59fc1f4d50ab', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 2, 2, 'But Jehosheba, the daughter of king Joram, sister of Ahaziah, took Joash the son of Ahaziah, and stole him away from among the king''s sons who were slain, even him and his nurse, [and put them] in the bedroom; and they hid him from Athaliah, so that he was not slain;'),
  ('932ea324-0df7-56dd-a3fc-777da67f1e88', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 3, 3, 'He was with her hidden in the house of Yahweh six years. Athaliah reigned over the land.'),
  ('c05d7412-062a-5532-ae4b-1a4baf9844ed', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 4, 4, 'In the seventh year Jehoiada sent and fetched the captains over hundreds of the Carites and of the guard, and brought them to him into the house of Yahweh; and he made a covenant with them, and took an oath of them in the house of Yahweh, and showed them the king''s son.'),
  ('bd8b5b38-d1f4-5d65-aa79-968ba8d77663', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 5, 5, 'He commanded them, saying, "This is the thing that you shall do: a third part of you, who come in on the Sabbath, shall be keepers of the watch of the king''s house;'),
  ('ee6a56a0-6513-5c97-af4f-b136bc61575a', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 6, 6, 'A third part shall be at the gate Sur; and a third part at the gate behind the guard. So you shall keep the watch of the house, and be a barrier.'),
  ('f844d23b-8b41-5a1d-a5bf-eaec3b00085b', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 7, 7, 'The two companies of you, even all who go out on the Sabbath, shall keep the watch of the house of Yahweh around the king.'),
  ('36c39d04-f339-507b-ad4c-306b43b33a7a', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 8, 8, 'You shall surround the king, every man with his weapons in his hand; and he who comes within the ranks, let him be slain. Be with the king when he goes out, and when he comes in."'),
  ('66c02c88-8e6d-51ca-ae65-f8bda717cd3a', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 9, 9, 'The captains over hundreds did according to all that Jehoiada the priest commanded; and they took every man his men, those who were to come in on the Sabbath, with those who were to go out on the Sabbath, and came to Jehoiada the priest.'),
  ('a3cb0aef-1d47-513a-ab67-6fa1eef22e9a', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 10, 10, 'The priest delivered to the captains over hundreds the spears and shields that had been king David''s, which were in the house of Yahweh.'),
  ('37624e6b-2afd-50a5-a5aa-db991536371f', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 11, 11, 'The guard stood, every man with his weapons in his hand, from the right side of the house to the left side of the house, along by the altar and the house, around the king.'),
  ('b1292af2-2a2f-5e36-ad2c-fbeea866d172', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 12, 12, 'Then he brought out the king''s son, and put the crown on him, and [gave him] the testimony; and they made him king, and anointed him; and they clapped their hands, and said, "Long live the king!"'),
  ('5632c440-ab76-5911-a016-ecc68d6393d5', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 13, 13, 'When Athaliah heard the noise of the guard [and of] the people, she came to the people into the house of Yahweh:'),
  ('9b2f31f6-24fa-5a43-a0b5-cbdba08ce5f8', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 14, 14, 'and she looked, and behold, the king stood by the pillar, as the tradition was, and the captains and the trumpets by the king; and all the people of the land rejoiced, and blew trumpets. Then Athaliah tore her clothes, and cried, "Treason! Treason!"'),
  ('a303fb78-31b7-5dca-a366-ee149f062d77', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 15, 15, 'Jehoiada the priest commanded the captains of hundreds who were set over the army, and said to them, "Bring her out between the ranks. Kill him who follows her with the sword." For the priest said, "Don''t let her be slain in the house of Yahweh."'),
  ('79bbda49-af85-557c-af45-740860d6ed49', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 16, 16, 'So they made way for her; and she went by the way of the horses'' entry to the king''s house. She was slain there.'),
  ('eda1589f-fe04-5625-a65a-c60361858d0e', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 17, 17, 'Jehoiada made a covenant between Yahweh and the king and the people, that they should be Yahweh''s people; between the king also and the people.'),
  ('f002c2f8-d80a-5ea1-af57-c43c71696b41', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 18, 18, 'All the people of the land went to the house of Baal, and broke it down; his altars and his images broke they in pieces thoroughly, and killed Mattan the priest of Baal before the altars. The priest appointed officers over the house of Yahweh.'),
  ('eec4aed7-e27c-5c21-aa61-fbeda7f5428e', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 19, 19, 'He took the captains over hundreds, and the Carites, and the guard, and all the people of the land; and they brought down the king from the house of Yahweh, and came by the way of the gate of the guard to the king''s house. He sat on the throne of the kings.'),
  ('9683231d-3df3-552b-a85c-3d781be1a3e6', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 20, 20, 'So all the people of the land rejoiced, and the city was quiet. Athaliah they had slain with the sword at the king''s house.'),
  ('a973451a-1045-51ef-a9cd-5bdbe54dd760', '8a278d6d-0846-5590-a999-113c28c71fad', NULL, 21, 21, 'Jehoash was seven years old when he began to reign.'),
  ('b2f13c1e-9833-541d-a72e-0d6ae51bb93b', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 1, 1, 'In the seventh year of Jehu began Jehoash to reign; and he reigned forty years in Jerusalem: and his mother''s name was Zibiah of Beersheba.'),
  ('eaf16a64-6bc3-5f71-abee-60e307496306', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 2, 2, 'Jehoash did that which was right in the eyes of Yahweh all his days in which Jehoiada the priest instructed him.'),
  ('5920e2f7-a472-5df4-ab6f-850521064efd', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 3, 3, 'However the high places were not taken away; the people still sacrificed and burnt incense in the high places.'),
  ('3bf2837f-9325-59c6-a924-8eb532dea99a', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 4, 4, 'Jehoash said to the priests, "All the money of the holy things that is brought into the house of Yahweh, in current money, the money of the persons for whom each man is rated, and all the money that it comes into any man''s heart to bring into the house of Yahweh,'),
  ('6cdcd142-90d4-572e-afed-380292109cc9', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 5, 5, 'let the priests take it to them, every man from his acquaintance; and they shall repair the breaches of the house, wherever any breach shall be found."'),
  ('ca7c5533-290a-5459-a9ab-f4f166e03f2a', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 6, 6, 'But it was so, that in the three and twentieth year of king Jehoash the priests had not repaired the breaches of the house.'),
  ('c87c236f-8018-5ef8-aec2-d644cf8d5a79', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 7, 7, 'Then king Jehoash called for Jehoiada the priest, and for the [other] priests, and said to them, "Why don''t you repair the breaches of the house? Now therefore take no more money from your treasurers, but deliver it for the breaches of the house."'),
  ('c4c07c6c-ef2f-5ad7-a404-bb1e2e157659', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 8, 8, 'The priests consented that they should take no [more] money from the people, neither repair the breaches of the house.'),
  ('fd8cf249-33c0-5611-a411-0ed649c5f35d', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 9, 9, 'But Jehoiada the priest took a chest, and bored a hole in its lid, and set it beside the altar, on the right side as one comes into the house of Yahweh: and the priests who kept the threshold put therein all the money that was brought into the house of Yahweh.'),
  ('2ac5d86f-0212-574c-a6e8-7994dc66c2af', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 10, 10, 'It was so, when they saw that there was much money in the chest, that the king''s scribe and the high priest came up, and they put up in bags and counted the money that was found in the house of Yahweh.')
